QT_ISI(1,{"1":["(Dengan nama Allah Yang Maha Pemurah lagi Maha Penyayang)",[["بِسْمِ","Dengan nama"],["ٱللَّهِ","(milik) Allah"],["ٱلرَّحْمَـٰنِ","Yang Maha Pemurah"],["ٱلرَّحِيمِ","Yang Maha Mengasihani"]]],"2":["(Segala puji bagi Allah) Lafal ayat ini merupakan kalimat berita, dimaksud sebagai ungkapan pujian kepada Allah berikut pengertian yang terkandung di dalamnya, yaitu bahwa Allah Taala adalah yang memiliki semua pujian yang diungkapkan oleh semua hamba-Nya. Atau makna yang dimaksud ialah bahwa Allah Taala itu adalah Zat yang harus mereka puji. Lafal Allah merupakan nama bagi Zat yang berhak untuk disembah. (Tuhan semesta alam) artinya Allah adalah yang memiliki pujian semua makhluk-Nya, yaitu terdiri dari manusia, jin, malaikat, hewan-hewan melata dan lain-lainnya. Masing-masing mereka disebut alam. Oleh karenanya ada alam manusia, alam jin dan lain sebagainya. Lafal 'al-`aalamiin' merupakan bentuk jamak dari lafal '`aalam', yaitu dengan memakai huruf ya dan huruf nun untuk menekankan makhluk berakal/berilmu atas yang lainnya. Kata 'aalam berasal dari kata `alaamah (tanda) mengingat ia adalah tanda bagi adanya yang menciptakannya.",[["ٱلْحَمْدُ","Segala puji"],["لِلَّهِ","bagi Allah"],["رَبِّ","Tuhan"],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"3":["(Yang Maha Pemurah lagi Maha Penyayang) yaitu yang mempunyai rahmat. Rahmat ialah menghendaki kebaikan bagi orang yang menerimanya.",[["ٱلرَّحْمَـٰنِ","Yang Maha Pemurah"],["ٱلرَّحِيمِ","Yang Maha Mengasihani"]]],"4":["(Yang menguasai hari pembalasan) di hari kiamat kelak. Lafal 'yaumuddiin' disebutkan secara khusus, karena di hari itu tiada seorang pun yang mempunyai kekuasaan, kecuali hanya Allah Taala semata, sesuai dengan firman Allah Taala yang menyatakan, \"Kepunyaan siapakah kerajaan pada hari ini (hari kiamat)? Kepunyaan Allah Yang Maha Esa lagi Maha Mengalahkan.\" (Q.S. Al-Mukmin 16) Bagi orang yang membacanya 'maaliki' maknanya menjadi \"Dia Yang memiliki semua perkara di hari kiamat\". Atau Dia adalah Zat yang memiliki sifat ini secara kekal, perihalnya sama dengan sifat-sifat-Nya yang lain, yaitu seperti 'ghaafiruz dzanbi' (Yang mengampuni dosa-dosa). Dengan demikian maka lafal 'maaliki yaumiddiin' ini sah menjadi sifat bagi Allah, karena sudah ma`rifah (dikenal).",[["مَـٰلِكِ","Yang Menguasai"],["يَوْمِ","hari"],["ٱلدِّينِ","pembalasan"]]],"5":["(Hanya Engkaulah yang kami sembah dan hanya kepada Engkaulah kami memohon pertolongan) Artinya kami beribadah hanya kepada-Mu, seperti mengesakan dan lain-lainnya, dan kami memohon pertolongan hanya kepada-Mu dalam menghadapi semua hamba-Mu dan lain-lainnya.",[["إِيَّاكَ","Engkau sahaja"],["نَعْبُدُ","kami sembah"],["وَإِيَّاكَ","dan Engkau sahaja"],["نَسْتَعِينُ","kami mohon pertolongan"]]],"6":["(Tunjukilah kami ke jalan yang lurus) Artinya bimbinglah kami ke jalan yang lurus, kemudian dijelaskan pada ayat berikutnya, yaitu:",[["ٱهْدِنَا","Tunjukilah kami"],["ٱلصِّرَٰطَ","jalan"],["ٱلْمُسْتَقِيمَ","yang lurus"]]],"7":["(Jalan orang-orang yang telah Engkau anugerahkan nikmat kepada mereka), yaitu melalui petunjuk dan hidayah-Mu. Kemudian diperjelas lagi maknanya oleh ayat berikut: (Bukan (jalan) mereka yang dimurkai) Yang dimaksud adalah orang-orang Yahudi. (Dan bukan pula) dan selain (mereka yang sesat.) Yang dimaksud adalah orang-orang Kristen. Faedah adanya penjelasan tersebut tadi mempunyai pengertian bahwa orang-orang yang mendapat hidayah itu bukanlah orang-orang Yahudi dan bukan pula orang-orang Kristen. Hanya Allahlah Yang Maha Mengetahui dan hanya kepada-Nyalah dikembalikan segala sesuatu. Semoga selawat dan salam-Nya dicurahkan kepada junjungan kita Nabi Muhammad saw. beserta keluarga dan para sahabatnya, selawat dan salam yang banyak untuk selamanya. Cukuplah bagi kita Allah sebagai penolong dan Dialah sebaik-baik penolong. Tiada daya dan tiada kekuatan melainkan hanya berkat pertolongan Allah Yang Maha Tinggi lagi Maha Besar.",[["صِرَٰطَ","jalan"],["ٱلَّذِينَ","orang"],["أَنْعَمْتَ","Engkau kurniakan nikmat"],["عَلَيْهِمْ","ke atas mereka"],["غَيْرِ","bukan"],["ٱلْمَغْضُوبِ","orang yang dimurkai"],["عَلَيْهِمْ","ke atas mereka"],["وَلَا","dan bukan"],["ٱلضَّآلِّينَ","orang yang sesat"]]],"8":["(Alif laam miim) Allah yang lebih mengetahui akan maksudnya.",[["الٓمٓ","Alif Laam Mim"]]],"9":["(Kitab ini) yakni yang dibaca oleh Muhammad saw. (tidak ada keraguan) atau kebimbangan (padanya) bahwa ia benar-benar dari Allah swt. Kalimat negatif menjadi predikat dari subyek 'Kitab ini', sedangkan kata-kata isyarat 'ini' dipakai sebagai penghormatan. (menjadi petunjuk) sebagai predikat kedua, artinya menjadi penuntun (bagi orang-orang yang bertakwa) maksudnya orang-orang yang mengusahakan diri mereka supaya menjadi takwa dengan jalan mengikuti perintah dan menjauhi larangan demi menjaga diri dari api neraka.",[["ذَٰلِكَ","Itu"],["ٱلْكِتَـٰبُ","(ialah) buku itu"],["لَا","tidak"],["رَيْبَ ۛ","keraguan"],["فِيهِ ۛ","di dalamnya"],["هُدًۭى","sebuah Bimbingan"],["لِّلْمُتَّقِينَ","untuk orang yang bertakwa kepada Tuhan"]]],"10":["(Orang-orang yang beriman) yang membenarkan (kepada yang gaib) yaitu yang tidak kelihatan oleh mereka, seperti kebangkitan, surga dan neraka (dan mendirikan salat) artinya melakukannya sebagaimana mestinya (dan sebagian dari yang Kami berikan kepada mereka) yang Kami anugerahkan kepada mereka sebagai rezeki (mereka nafkahkan) mereka belanjakan untuk jalan menaati Allah.",[["ٱلَّذِينَ","Orang yang"],["يُؤْمِنُونَ","beriman"],["بِٱلْغَيْبِ","dengan perkara ghaib"],["وَيُقِيمُونَ","dan mendirikan"],["ٱلصَّلَوٰةَ","solat"],["وَمِمَّا","dan sebahagian daripada apa"],["رَزَقْنَـٰهُمْ","Kami rezekikan kepada mereka"],["يُنفِقُونَ","mereka nafkahkan"]]],"11":["(Dan orang-orang yang beriman pada apa yang diturunkan kepadamu) maksudnya Alquran, (dan apa yang diturunkan sebelummu) yaitu Taurat, Injil dan selainnya (serta mereka yakin akan hari akhirat), artinya mengetahui secara pasti.",[["وَٱلَّذِينَ","Dan orang yang"],["يُؤْمِنُونَ","beriman"],["بِمَآ","pada apa"],["أُنزِلَ","(adalah) diturunkan"],["إِلَيْكَ","kepada kamu"],["وَمَآ","dan apa"],["أُنزِلَ","telah diturunkan"],["مِن","daripada"],["قَبْلِكَ","sebelum kamu"],["وَبِٱلْـَٔاخِرَةِ","dan di akhirat"],["هُمْ","mereka"],["يُوقِنُونَ","teguh beriman"]]],"12":["(Merekalah), yakni orang-orang yang memenuhi sifat-sifat yang disebutkan di atas (yang beroleh petunjuk dari Tuhan mereka dan merekalah orang-orang yang beruntung) yang akan berhasil meraih surga dan terlepas dari siksa neraka.",[["أُو۟لَـٰٓئِكَ","Mereka itu"],["عَلَىٰ","(ada) pada"],["هُدًۭى","Bimbingan"],["مِّن","daripada"],["رَّبِّهِمْ ۖ","Tuhan mereka"],["وَأُو۟لَـٰٓئِكَ","dan mereka"],["هُمُ","mereka"],["ٱلْمُفْلِحُونَ","(adalah) orang-orang yang berjaya"]]],"13":["(Sesungguhnya orang-orang kafir) seperti Abu Jahal, Abu Lahab dan lainnya (sama saja bagi mereka, apakah kamu beri peringatan) dibaca, a-andzartahum, yakni dengan dua buah hamzah secara tegas. Dapat pula hamzah yang kedua dilebur menjadi alif hingga hanya tinggal satu hamzah saja yang dibaca panjang (atau tidak kamu beri peringatan, mereka tidak juga akan beriman.) Hal itu telah diketahui oleh Allah, maka janganlah kamu berharap mereka akan beriman. 'Indzar' atau peringatan, artinya pemberitahuan disertai ancaman.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","tidak beriman[d]"],["سَوَآءٌ","(ia) adalah sama"],["عَلَيْهِمْ","kepada mereka"],["ءَأَنذَرْتَهُمْ","sama ada kamu memberi amaran kepada mereka"],["أَمْ","atau"],["لَمْ","tidak"],["تُنذِرْهُمْ","kamu memberi amaran kepada mereka"],["لَا","tidak"],["يُؤْمِنُونَ","mereka beriman"]]],"14":["(Allah mengunci mati hati mereka) maksudnya menutup rapat hati mereka sehingga tidak dapat dimasuki oleh kebaikan (begitu pun pendengaran mereka) maksudnya alat-alat atau sumber-sumber pendengaran mereka dikunci sehingga mereka tidak memperoleh manfaat dari kebenaran yang mereka terima (sedangkan penglihatan mereka ditutup) dengan penutup yang menutupinya sehingga mereka tidak dapat melihat kebenaran (dan bagi mereka siksa yang besar) yang berat lagi tetap. Terhadap orang-orang munafik diturunkan:",[["خَتَمَ","Telah menetapkan meterai"],["ٱللَّهُ","Allah"],["عَلَىٰ","pada"],["قُلُوبِهِمْ","hati mereka"],["وَعَلَىٰ","dan seterusnya"],["سَمْعِهِمْ ۖ","pendengaran mereka"],["وَعَلَىٰٓ","dan seterusnya"],["أَبْصَـٰرِهِمْ","penglihatan mereka"],["غِشَـٰوَةٌۭ ۖ","(adalah) tudung"],["وَلَهُمْ","Dan untuk mereka"],["عَذَابٌ","(ialah) azab"],["عَظِيمٌۭ","yang besar"]]],"15":["(Di antara manusia ada orang yang mengatakan, \"Kami beriman kepada Allah dan hari akhir.\") yaitu hari kiamat, karena hari itu adalah hari terakhir. (Padahal mereka bukan orang-orang yang beriman). Di sini ditekankan arti kata 'orang', jika kata ganti yang disebutkan lafalnya, yakni 'mereka'.",[["وَمِنَ","Dan daripada"],["ٱلنَّاسِ","manusia"],["مَن","(adalah beberapa) siapa"],["يَقُولُ","berkata"],["ءَامَنَّا","Kami beriman"],["بِٱللَّهِ","kepada Allah"],["وَبِٱلْيَوْمِ","dan pada hari itu"],["ٱلْـَٔاخِرِ","[yang] Terakhir"],["وَمَا","tetapi tidak"],["هُم","mereka"],["بِمُؤْمِنِينَ","(adalah) orang yang beriman (sama sekali)"]]],"16":["(Mereka hendak menipu Allah dan orang-orang yang beriman) yakni dengan berpura-pura beriman dan menyembunyikan kekafiran guna melindungi diri mereka dari hukum-hukum duniawi (padahal mereka hanya menipu diri mereka sendiri) karena bencana tipu daya itu akan kembali menimpa diri mereka sendiri. Di dunia, rahasia mereka akan diketahui juga dengan dibuka Allah kepada Nabi-Nya, sedangkan di akhirat mereka akan menerima hukuman setimpal (tetapi mereka tidak menyadari) dan tidak menginsafi bahwa tipu daya mereka itu menimpa diri mereka sendiri. Mukhada`ah atau tipu-menipu di sini muncul dari satu pihak, jadi bukan berarti berserikat di antara dua belah pihak. Contoh yang lainnya mu`aqabatul lish yang berarti menghukum pencuri. Menyebutkan Allah di sana hanya merupakan salah satu dari gaya bahasa saja. Menurut suatu qiraat tidak tercantum 'wamaa yasy`uruuna' tetapi 'wamaa yakhda`uuna', artinya 'tetapi mereka tidak berhasil menipu'.",[["يُخَـٰدِعُونَ","Mereka berusaha untuk menipu"],["ٱللَّهَ","Allah"],["وَٱلَّذِينَ","dan orang yang"],["ءَامَنُوا۟","beriman"],["وَمَا","dan bukan"],["يَخْدَعُونَ","mereka menipu"],["إِلَّآ","kecuali"],["أَنفُسَهُمْ","diri mereka"],["وَمَا","dan bukan"],["يَشْعُرُونَ","mereka menyedari (itu)"]]],"17":["(Dalam hati mereka ada penyakit) berupa keragu-raguan dan kemunafikan yang menyebabkan sakit atau lemahnya hati mereka. (Lalu ditambah Allah penyakit mereka) dengan menurunkan Alquran yang mereka ingkari itu. (Dan bagi mereka siksa yang pedih) yang menyakitkan (disebabkan kedustaan mereka.) Yukadzdzibuuna dibaca pakai tasydid, artinya amat mendustakan, yakni terhadap Nabi Allah dan tanpa tasydid 'yakdzibuuna' yang berarti berdusta, yakni dengan mengakui beriman padahal tidak.",[["فِى","Dalam"],["قُلُوبِهِم","hati mereka"],["مَّرَضٌۭ","(adalah) penyakit"],["فَزَادَهُمُ","begitu juga telah meningkatkan mereka"],["ٱللَّهُ","Allah"],["مَرَضًۭا ۖ","(dalam) penyakit"],["وَلَهُمْ","dan untuk mereka"],["عَذَابٌ","(ialah) azab"],["أَلِيمٌۢ","yang pedih"],["بِمَا","kerana"],["كَانُوا۟","mereka dahulu"],["يَكْذِبُونَ","[mereka] berbohong"]]],"18":["(Dan jika dikatakan kepada mereka,) maksudnya kepada orang-orang munafik tadi (\"Janganlah kamu membuat kerusakan di muka bumi!\") yakni dengan kekafiran dan menyimpang dari keimanan. (Jawab mereka, \"Sesungguhnya kami ini berbuat kebaikan.\") dan tidak dijumpai pada perbuatan kami hal-hal yang menjurus pada kebinasaan. Maka Allah swt. berfirman sebagai sanggahan atas ucapan mereka itu:",[["وَإِذَا","Dan apabila"],["قِيلَ","dikatakan"],["لَهُمْ","kepada mereka"],["لَا","Jangan"],["تُفْسِدُوا۟","menyebarkan rasuah"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["قَالُوٓا۟","mereka berkata"],["إِنَّمَا","Hanya"],["نَحْنُ","kita"],["مُصْلِحُونَ","(adalah) reformis"]]],"19":["(Ingatlah!) Seruan untuk membangkitkan perhatian. (Sesungguhnya mereka itulah yang membuat kerusakan, tetapi mereka tidak sadar) akan kenyataan itu.",[["أَلَآ","Awas"],["إِنَّهُمْ","sesungguhnya mereka"],["هُمُ","diri mereka"],["ٱلْمُفْسِدُونَ","(ialah) orang-orang yang menyebarkan rasuah"],["وَلَـٰكِن","[dan] tetapi"],["لَّا","tidak"],["يَشْعُرُونَ","mereka menyedari (itu)"]]],"20":["(Apabila dikatakan kepada mereka, \"Berimanlah kamu sebagaimana orang-orang lain beriman!\") yakni sebagaimana berimannya para sahabat Nabi. (Jawab mereka, \"Apakah kami akan beriman sebagaimana berimannya orang-orang yang bodoh?\") Artinya kami tidak akan melakukan seperti yang dilakukan oleh orang-orang yang bodoh itu. Maka firman Allah menolak ucapan mereka itu: (Ketahuilah, merekalah orang-orang bodoh tetapi mereka tidak tahu) akan hal itu.",[["وَإِذَا","Dan apabila"],["قِيلَ","dikatakan"],["لَهُمْ","kepada mereka"],["ءَامِنُوا۟","Percayalah"],["كَمَآ","seperti"],["ءَامَنَ","beriman"],["ٱلنَّاسُ","manusia"],["قَالُوٓا۟","mereka berkata"],["أَنُؤْمِنُ","Patutkah kita beriman"],["كَمَآ","seperti"],["ءَامَنَ","beriman"],["ٱلسُّفَهَآءُ ۗ","orang bodoh"],["أَلَآ","Awas"],["إِنَّهُمْ","sudah tentu mereka"],["هُمُ","diri mereka"],["ٱلسُّفَهَآءُ","(adalah) orang-orang yang bodoh"],["وَلَـٰكِن","[dan] tetapi"],["لَّا","tidak"],["يَعْلَمُونَ","mereka tahu"]]],"21":["(Dan jika mereka berjumpa) asalnya 'laqiyuu' lalu damah pada ya dibuang karena beratnya pada lidah berikut ya itu sendiri karena bertemunya dalam keadaan sukun dengan wau sehingga menjadi 'laquu' (dengan orang yang beriman, mereka berkata, \"Kami telah beriman.\" Dan bila mereka telah berpisah) dengan orang-orang yang beriman dan kembali (kepada setan-setan mereka) maksudnya pemimpin-pemimpin mereka. (Kata mereka, \"Sesungguhnya kami ini bersama kamu) maksudnya sependirian dengan kamu dalam keagamaan, (kami ini hanya berolok-olok.\") dengan berpura-pura beriman.",[["وَإِذَا","Dan apabila"],["لَقُوا۟","mereka berjumpa"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["قَالُوٓا۟","mereka berkata"],["ءَامَنَّا","Kami beriman[d]"],["وَإِذَا","Tetapi apabila"],["خَلَوْا۟","mereka bersendirian"],["إِلَىٰ","dengan"],["شَيَـٰطِينِهِمْ","jahat mereka"],["قَالُوٓا۟","mereka berkata"],["إِنَّا","Sesungguhnya kami"],["مَعَكُمْ","(ada) bersama kamu"],["إِنَّمَا","sahaja"],["نَحْنُ","kita"],["مُسْتَهْزِءُونَ","(adalah) pengejek"]]],"22":["(Allahlah yang memperolok-olokkan mereka) artinya membalas olok-olokkan itu dengan memperolok-olokkan mereka pula (dan membiarkan mereka) terpedaya (dalam kesesatan mereka) yakni melanggar batas disebabkan kekafiran (terumbang-ambing) dalam keadaan bingung tanpa tujuan atau pegangan.",[["ٱللَّهُ","Allah"],["يَسْتَهْزِئُ","mengejek"],["بِهِمْ","pada mereka"],["وَيَمُدُّهُمْ","dan memanjangkannya"],["فِى","dalam"],["طُغْيَـٰنِهِمْ","pelanggaran mereka"],["يَعْمَهُونَ","mereka merayau buta"]]],"23":["(Mereka itulah orang-orang yang membeli kesesatan dengan petunjuk) artinya mengambil kesesatan sebagai pengganti petunjuk (maka tidaklah beruntung perniagaan mereka) bahkan sebaliknya mereka merugi, karena membawa mereka ke dalam neraka yang menjadi tempat kediaman mereka untuk selama-lamanya. (Dan tidaklah mereka mendapat petunjuk) disebabkan perbuatan mereka itu.",[["أُو۟لَـٰٓئِكَ","Mereka itu"],["ٱلَّذِينَ","(adalah) orang-orang yang"],["ٱشْتَرَوُا۟","dibeli"],["ٱلضَّلَـٰلَةَ","[yang] sesat"],["بِٱلْهُدَىٰ","untuk bimbingan"],["فَمَا","Jadi tidak"],["رَبِحَت","mendapat keuntungan"],["تِّجَـٰرَتُهُمْ","perdagangan mereka"],["وَمَا","dan bukan"],["كَانُوا۟","adakah mereka"],["مُهْتَدِينَ","berpandu"]]],"24":["(Perumpamaan mereka) sifat mereka dalam kemunafikannya itu, (seperti orang yang menyalakan) atau menghidupkan (api) dalam kegelapan (dan setelah api itu menerangi) atau menyinari (apa yang di sekelilingnya) hingga ia dapat melihat, berdiang dan merasa aman dari apa yang ditakutinya (Allah pun menghilangkan cahaya yang menyinari mereka) yaitu dengan memadamkannya. Kata ganti orang dijadikan jamak 'him' merujuk kepada makna 'alladzii' (dan meninggalkan mereka dalam kegelapan tidak dapat melihat) apa yang terdapat di sekeliling mereka, sehingga tidak tahu jalan dan mereka dalam keadaan kecemasan. Demikianlah halnya orang-orang munafik yang mengucapkan kata-kata beriman, bila mereka mati mereka akan ditimpa ketakutan dan azab.",[["مَثَلُهُمْ","contoh mereka"],["كَمَثَلِ","(adalah) seperti (the) contoh"],["ٱلَّذِى","(dari) orang yang"],["ٱسْتَوْقَدَ","dinyalakan"],["نَارًۭا","api"],["فَلَمَّآ","kemudian, apabila"],["أَضَآءَتْ","ia bercahaya"],["مَا","apa"],["حَوْلَهُۥ","(ada) di sekelilingnya"],["ذَهَبَ","dibawa pergi"],["ٱللَّهُ","Allah"],["بِنُورِهِمْ","cahaya mereka"],["وَتَرَكَهُمْ","dan meninggalkan mereka"],["فِى","dalam"],["ظُلُمَـٰتٍۢ","kegelapan[es]"],["لَّا","(jadi) tidak"],["يُبْصِرُونَ","(adakah) mereka melihat"]]],"25":["(Mereka tuli) terhadap kebenaran, maksudnya tidak mau menerima kebenaran yang didengarnya (bisu) terhadap kebaikan hingga tidak mampu mengucapkannya (buta) terhadap jalan kebenaran dan petunjuk Allah sehingga tidak dapat melihatnya, (maka mereka tidaklah akan kembali) dari kesesatan.",[["صُمٌّۢ","pekak"],["بُكْمٌ","bodoh"],["عُمْىٌۭ","buta"],["فَهُمْ","jadi mereka"],["لَا","tidak"],["يَرْجِعُونَ","[mereka] tidak akan kembali"]]],"26":["(Atau) perumpamaan mereka itu, (seperti hujan lebat) maksudnya seperti orang-orang yang ditimpa hujan lebat; asal kata shayyibin dari shaaba-yashuubu, artinya turun (dari langit) maksudnya dari awan (padanya) yakni pada awan itu (kegelapan) yang tebal, (dan guruh) maksudnya malaikat yang mengurusnya. Ada pula yang mengatakan suara dari malaikat itu, (dan kilat) yakni kilatan suara yang dikeluarkannya untuk menghardik, (mereka menaruh) maksudnya orang-orang yang ditimpa hujan lebat tadi (jari-jemari mereka) maksudnya dengan ujung jari, (pada telinga mereka, dari) maksudnya disebabkan (bunyi petir) yang amat keras itu supaya tidak kedengaran karena (takut mati) bila mendengarnya. Demikianlah orang-orang tadi, jika diturunkan kepada mereka Alquran disebutkan kekafiran yang diserupakan dengan gelap gulita, ancaman yang dibandingkan dengan guruh serta keterangan-keterangan nyata yang disamakan dengan kilat, mereka menyumbat anak-anak telinga mereka agar tidak mendengarnya, karena takut akan terpengaruh lalu cenderung kepada keimanan yang akan menyebabkan mereka meninggalkan agama mereka, yang bagi mereka sama artinya dengan kematian. (Dan Allah meliputi orang-orang kafir) baik dengan ilmu maupun dengan kekuasaan-Nya hingga tidak sesuatu pun yang luput dari-Nya.",[["أَوْ","Atau"],["كَصَيِّبٍۢ","seperti ribut hujan"],["مِّنَ","daripada"],["ٱلسَّمَآءِ","langit"],["فِيهِ","di dalamnya (adalah)"],["ظُلُمَـٰتٌۭ","kegelapan[es]"],["وَرَعْدٌۭ","dan guruh"],["وَبَرْقٌۭ","dan kilat"],["يَجْعَلُونَ","Mereka meletakkan"],["أَصَـٰبِعَهُمْ","jari mereka"],["فِىٓ","dalam"],["ءَاذَانِهِم","telinga mereka"],["مِّنَ","daripada"],["ٱلصَّوَٰعِقِ","guruh berdentum"],["حَذَرَ","(dalam) ketakutan (kepada)"],["ٱلْمَوْتِ ۚ","[the] kematian"],["وَٱللَّهُ","Dan Allah"],["مُحِيطٌۢ","(ialah) [Yang] meliputi"],["بِٱلْكَـٰفِرِينَ","orang kafir"]]],"27":["(Hampir saja) maksudnya mendekati (kilat menyambar penglihatan mereka) merebutnya dengan cepat. (Setiap kali kilat itu menyinari mereka, mereka berjalan padanya) maksudnya pada cahaya atau di bawah sinarnya, (dan bila gelap menimpa mereka, mereka pun berhenti) sebagai tamsil dari bukti-bukti keterangan ayat-ayat Alquran yang mengejutkan hati mereka. Mereka membenarkannya setelah mendengar padanya hal-hal yang mereka senangi sehingga mereka berhenti dari apa-apa yang dibencinya. (Sekiranya Allah menghendaki, niscaya dilenyapkan-Nya pendengaran dan penglihatan mereka) baik yang lahir maupun yang batin (Sesungguhnya Allah Maha Kuasa atas segala sesuatu) yang dikehendaki-Nya, termasuk apa-apa yang telah disebutkan tadi.",[["يَكَادُ","hampir"],["ٱلْبَرْقُ","kilat itu"],["يَخْطَفُ","menyambar"],["أَبْصَـٰرَهُمْ ۖ","penglihatan mereka"],["كُلَّمَآ","apabila-apabila masa"],["أَضَآءَ","ia berkelip"],["لَهُم","bagi mereka"],["مَّشَوْا۟","mereka berjalan"],["فِيهِ","di dalamnya"],["وَإِذَآ","dan apabila"],["أَظْلَمَ","ia menjadi gelap"],["عَلَيْهِمْ","ke atas mereka"],["قَامُوا۟ ۚ","mereka berdiri (diam)"],["وَلَوْ","Dan jika"],["شَآءَ","telah berkehendak"],["ٱللَّهُ","Allah"],["لَذَهَبَ","Dia pasti akan membawa pergi"],["بِسَمْعِهِمْ","pendengaran mereka"],["وَأَبْصَـٰرِهِمْ ۚ","dan penglihatan mereka"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["عَلَىٰ","(berada) di atas"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["قَدِيرٌۭ","Maha Berkuasa"]]],"28":["(Hai manusia!) Maksudnya warga Mekah, (Sembahlah olehmu) dengan bertauhid atau mengesakan (Tuhanmu yang telah menciptakanmu) padahal sebelum itu kamu dalam keadaan tiada (dan) diciptakan-Nya pula (orang-orang yang sebelum kamu, agar kamu bertakwa), artinya terpelihara dari siksa dan azab-Nya yakni dengan jalan beribadah kepada-Nya. Pada asalnya 'la`alla' mengungkapkan harapan, tetapi pada firman Allah berarti menyatakan kepastian.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلنَّاسُ","manusia"],["ٱعْبُدُوا۟","ibadah"],["رَبَّكُمُ","Tuhanmu"],["ٱلَّذِى","yang Esa"],["خَلَقَكُمْ","mencipta kamu"],["وَٱلَّذِينَ","dan mereka"],["مِن","daripada"],["قَبْلِكُمْ","sebelum kamu"],["لَعَلَّكُمْ","supaya kamu"],["تَتَّقُونَ","menjadi soleh"]]],"29":["(Dialah yang telah menjadikan) menciptakan (bagimu bumi sebagai hamparan), yakni hamparan yang tidak begitu keras dan tidak pula begitu lunak sehingga tidak mungkin didiami secara tetap (dan langit sebagai naungan) sebagai atap (dan diturunkan-Nya dari langit air hujan lalu dikeluarkan-Nya daripadanya) maksudnya bermacam (buah-buahan sebagai rezeki bagi kamu) buat kamu makan dan kamu berikan rumputnya pada binatang ternakmu (maka janganlah kamu adakan sekutu-sekutu bagi Allah), artinya serikat-serikat-Nya dalam pengabdian (padahal kamu mengetahui) bahwa Dia adalah pencipta, sedangkan mereka itu tidak dapat menciptakan apa-apa, maka tidaklah layak disebut dan dikatakan tuhan.",[["ٱلَّذِى","Dia yang"],["جَعَلَ","dibuat"],["لَكُمُ","bagi kamu"],["ٱلْأَرْضَ","bumi"],["فِرَٰشًۭا","tempat berehat"],["وَٱلسَّمَآءَ","dan langit"],["بِنَآءًۭ","sebuah kanopi"],["وَأَنزَلَ","dan diturunkan"],["مِنَ","daripada"],["ٱلسَّمَآءِ","langit"],["مَآءًۭ","air"],["فَأَخْرَجَ","kemudian dilahirkan"],["بِهِۦ","dengan itu"],["مِنَ","[daripada]"],["ٱلثَّمَرَٰتِ","buah-buahan"],["رِزْقًۭا","(sebagai) peruntukan"],["لَّكُمْ ۖ","bagi kamu"],["فَلَا","Jadi (jangan)"],["تَجْعَلُوا۟","sediakan"],["لِلَّهِ","kepada Allah"],["أَندَادًۭا","saingan"],["وَأَنتُمْ","sedangkan kamu"],["تَعْلَمُونَ","[kamu] tahu"]]],"30":["(Sekiranya kamu merasa ragu) atau bimbang (tentang apa yang Kami turunkan kepada hamba Kami) maksudnya tentang Alquran yang Kami wahyukan kepada Muhammad, bahwa itu benar-benar dari Allah, (maka buatlah sebuah surah yang sebanding dengannya) dengan surah yang diwahyukan itu. 'Min mitslihi', min yang berarti dari, maksudnya di sini ialah untuk menjadi keterangan atau penjelasan, hingga artinya ialah yang sebanding dengannya, baik dalam kedalaman makna maupun dalam keindahan susunan kata serta pemberitaan tentang hal-hal gaib dan sebagainya. Yang dimaksud dengan 'surah' ialah suatu penggal perkataan yang mempunyai permulaan kesudahan dan sekurang-kurangnya terdiri dari tiga ayat. (Dan ajaklah saksi-saksimu) maksudnya tuhan-tuhanmu yang kamu sembah itu (selain dari Allah) untuk menjadi penolong-penolongmu, (jika kamu orang-orang yang benar) bahwa Alquran itu hanyalah buatan dan ucapan Muhammad belaka, maka cobalah lakukan demikian, bukankah kamu orang-orang yang berlidah fasih seperti Muhammad pula?",[["وَإِن","Dan jika"],["كُنتُمْ","kamu"],["فِى","dalam"],["رَيْبٍۢ","keraguan"],["مِّمَّا","tentang apa"],["نَزَّلْنَا","Kami telah mendedahkan"],["عَلَىٰ","kepada"],["عَبْدِنَا","hamba kita"],["فَأْتُوا۟","kemudian menghasilkan"],["بِسُورَةٍۢ","satu bab"],["مِّن","[daripada]"],["مِّثْلِهِۦ","suka"],["وَٱدْعُوا۟","dan panggil"],["شُهَدَآءَكُم","saksi kamu"],["مِّن","daripada"],["دُونِ","selain daripada"],["ٱللَّهِ","Allah"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","jujur"]]],"31":["Tatkala mereka tidak mampu memenuhi permintaan itu, maka Allah swt. berfirman, (Dan jika kamu tidak dapat melakukan) apa yang disebutkan itu disebabkan kelemahan dan ketidakmampuanmu (dan kamu pasti tidak akan dapat melakukannya) demikian itu untuk selama-lamanya disebabkan terhalang mukjizat Alquran itu, (maka jagalah dirimu dari neraka) dengan jalan beriman kepada Allah dan meyakini bahwa Alquran itu bukanlah ucapan manusia (yang kayu apinya terdiri dari manusia), yakni orang-orang kafir (dan batu), misalnya yang dipakai untuk membuat patung-patung atau berhala-berhala mereka. Maksudnya api neraka itu amat panas dan tambah menyala dengan bahan bakar manusia dan batu jadi bukan seperti api dunia yang hanya dapat dinyalakan dengan kayu bakar atau yang lainnya (yang disediakan bagi orang-orang kafir) sebagai alat untuk menyiksa mereka. Kalimat belakang ini dapat menjadi kalimat baru atau menunjukkan keadaan yang lazim.",[["فَإِن","Tetapi jika"],["لَّمْ","tidak"],["تَفْعَلُوا۟","kamu lakukan"],["وَلَن","dan tidak pernah"],["تَفْعَلُوا۟","adakah kamu akan lakukan"],["فَٱتَّقُوا۟","kemudian takut"],["ٱلنَّارَ","neraka"],["ٱلَّتِى","yang"],["وَقُودُهَا","[nya] bahan bakar"],["ٱلنَّاسُ","(ialah) lelaki"],["وَٱلْحِجَارَةُ ۖ","dan batu-batu itu"],["أُعِدَّتْ","disediakan"],["لِلْكَـٰفِرِينَ","bagi orang-orang kafir"]]],"32":["(Dan sampaikanlah berita gembira) kabarkanlah (kepada orang-orang yang beriman) yang membenarkan Allah (dan mengerjakan kebaikan), baik yang fardu atau yang sunah (bahwa bagi mereka disediakan surga-surga), yaitu taman-taman yang ada pepohonan dan tempat-tempat kediaman (yang mengalir di bawahnya) maksudnya di bawah kayu-kayuan dan mahligai-mahligainya (sungai-sungai) maksudnya air yang berada di sungai-sungai itu, karena sungai artinya ialah galian tempat mengalirnya air, sebab airlah yang telah menggali atau menjadikannya 'nahr' dan menisbatkan 'mengalir' pada selokan disebut 'majaz' atau simbolisme. (Setiap mereka diberi rezeki di dalam surga itu) maksudnya diberi makanan (berupa buah-buahan, mereka mengatakan, \"Inilah yang pernah) maksudnya seperti inilah yang pernah (diberikan kepada kami dulu\"), yakni sebelum masuk surga, karena buah-buahan itu seperti itu pula ciri masing-masingnya, hampir serupa. (Mereka disuguhi) atau dipetikkan buah itu (dalam keadaan serupa), yakni warnanya tetapi berbeda rasanya, (dan diberi istri-istri) berupa wanita-wanita cantik dan selainnya, (yang suci) suci dari haid dan dari kotoran lainnya, (dan mereka kekal di dalamnya) untuk selama-lamanya, hingga mereka tak pernah fana dan tidak pula dikeluarkan dari dalamnya.",[["وَبَشِّرِ","Dan sampaikan berita gembira"],["ٱلَّذِينَ","(kepada) mereka yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan melakukan"],["ٱلصَّـٰلِحَـٰتِ","[yang] amal soleh"],["أَنَّ","bahawa"],["لَهُمْ","bagi mereka"],["جَنَّـٰتٍۢ","(akan menjadi) taman-taman"],["تَجْرِى","aliran"],["مِن","[dari]"],["تَحْتِهَا","di bawah mereka"],["ٱلْأَنْهَـٰرُ ۖ","sungai-sungai"],["كُلَّمَا","setiap masa"],["رُزِقُوا۟","mereka disediakan"],["مِنْهَا","daripadanya"],["مِن","daripada"],["ثَمَرَةٍۢ","buah-buahan"],["رِّزْقًۭا ۙ","(sebagai) peruntukan"],["قَالُوا۟","mereka (akan) berkata"],["هَـٰذَا","ini (ialah)"],["ٱلَّذِى","yang mana"],["رُزِقْنَا","kami disediakan"],["مِن","daripada"],["قَبْلُ ۖ","sebelum"],["وَأُتُوا۟","Dan mereka akan diberikan"],["بِهِۦ","daripadanya"],["مُتَشَـٰبِهًۭا ۖ","(benda) yang serupa"],["وَلَهُمْ","Dan untuk mereka"],["فِيهَآ","di dalamnya"],["أَزْوَٰجٌۭ","pasangan suami isteri"],["مُّطَهَّرَةٌۭ ۖ","disucikan"],["وَهُمْ","dan mereka"],["فِيهَا","di dalamnya"],["خَـٰلِدُونَ","(akan) kekal selama-lamanya"]]],"33":["Untuk menolak perkataan orang-orang Yahudi, \"Apa maksud Allah menyebutkan barang-barang hina ini\", yakni ketika Allah mengambil perbandingan pada lalat dalam firman-Nya, \"... dan sekiranya lalat mengambil sesuatu dari mereka\" dan pada laba-laba dalam firman-Nya, \"Tak ubahnya seperti laba-laba,\" Allah menurunkan: (Sesungguhnya Allah tidak segan membuat) atau mengambil (perbandingan) berfungsi sebagai maf`ul awal atau obyek pertama, sedangkan (apa juga) kata penyerta yang diberi keterangan dengan kata-kata yang di belakangnya menjadi maf`ul tsani atau obyek kedua hingga berarti tamsil perbandingan apa pun jua. Atau dapat juga sebagai tambahan untuk memperkuat kehinaan, sedangkan kata-kata di belakangnya menjadi maf`ul tsani (seekor nyamuk) yakni serangga kecil, (atau yang lebih atas dari itu) artinya yang lebih besar dari itu, maksudnya Allah tak hendak mengabaikan hal-hal tersebut, karena mengandung hukum yang perlu diterangkan-Nya. (Ada pun orang-orang yang beriman, maka mereka yakin bahwa ia), maksudnya perumpamaan itu (benar), tepat dan cocok dengan situasinya (dari Tuhan mereka, tetapi orang-orang kafir mengatakan, \"Apakah maksud Allah menjadikan ini sebagai perumpamaan?\") Matsalan atau perumpamaan itu berfungsi sebagai tamyiz hingga berarti dengan perumpamaan ini. 'Ma' yang berarti 'apakah' merupakan kata-kata pertanyaan disertai kecaman dan berfungsi sebagai mubtada atau subyek. Sedangkan 'dza' berarti yang berikut shilahnya atau kata-kata pelengkapnya menjadi khabar atau predikat, hingga maksudnya ialah 'apa gunanya?' Sebagai jawaban terhadap mereka Allah berfirman: (Allah menyesatkan dengannya), maksudnya dengan tamsil perbandingan ini, (banyak manusia) berpaling dari kebenaran disebabkan kekafiran mereka terhadapnya, (dan dengan perumpamaan itu, banyak pula orang yang diberi-Nya petunjuk), yaitu dari golongan orang-orang beriman disebabkan mereka membenarkan dan mempercayainya (Tetapi yang disesatkan-Nya itu hanyalah orang-orang yang fasik), yakni yang menyimpang dan tak mau menaati-Nya.",[["۞ إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["لَا","(adalah) tidak"],["يَسْتَحْىِۦٓ","malu"],["أَن","kepada"],["يَضْرِبَ","ditetapkan"],["مَثَلًۭا","satu contoh"],["مَّا","(seperti) walaupun"],["بَعُوضَةًۭ","(dari) nyamuk"],["فَمَا","dan (bahkan) sesuatu"],["فَوْقَهَا ۚ","di atasnya"],["فَأَمَّا","Kemudian untuk"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["فَيَعْلَمُونَ","[dengan demikian] mereka akan mengetahui"],["أَنَّهُ","bahawa ia"],["ٱلْحَقُّ","(adalah) kebenaran"],["مِن","daripada"],["رَّبِّهِمْ ۖ","Tuhan mereka"],["وَأَمَّا","Dan untuk"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["فَيَقُولُونَ","[demikian] mereka akan berkata"],["مَاذَآ","apa"],["أَرَادَ","(ada) berniat"],["ٱللَّهُ","Allah"],["بِهَـٰذَا","oleh ini"],["مَثَلًۭا ۘ","contoh"],["يُضِلُّ","Dia biarkan sesat"],["بِهِۦ","olehnya"],["كَثِيرًۭا","ramai"],["وَيَهْدِى","dan Dia memberi petunjuk"],["بِهِۦ","olehnya"],["كَثِيرًۭا ۚ","ramai"],["وَمَا","Dan tidak"],["يُضِلُّ","Dia biarkan sesat"],["بِهِۦٓ","olehnya"],["إِلَّا","kecuali"],["ٱلْفَـٰسِقِينَ","yang durhaka"]]],"34":["(Orang-orang yang) merupakan 'na`at' atau sifat (melanggar janji Allah) melanggar kewajiban yang ditugaskan Allah kepada mereka dalam Kitab-Kitab Suci berupa keimanan kepada Nabi Muhammad saw. (setelah teguhnya) setelah kukuhnya perjanjian itu, (dan memutus apa yang diperintahkan Allah dengannya untuk dihubungkan), yakni beriman dan menghubungkan silaturahmi dengan Nabi saw. serta lain-lainnya. Anak kalimat 'untuk dihubungkan' menjadi kata ganti dari 'dengannya', (dan membuat kerusakan di muka bumi) dengan melakukan maksiat serta menyimpang dari keimanan (merekalah) orang-orang yang mempunyai sifat seperti yang dilukiskan itu (orang-orang yang rugi) karena mereka dimasukkan ke dalam neraka untuk selama-lamanya.",[["ٱلَّذِينَ","Orang yang"],["يَنقُضُونَ","rehat"],["عَهْدَ","(the) Perjanjian"],["ٱللَّهِ","(milik) Allah"],["مِنۢ","daripada"],["بَعْدِ","selepas"],["مِيثَـٰقِهِۦ","pengesahannya"],["وَيَقْطَعُونَ","dan [mereka] memotong"],["مَآ","apa"],["أَمَرَ","telah memesan"],["ٱللَّهُ","Allah"],["بِهِۦٓ","ia"],["أَن","kepada"],["يُوصَلَ","disertai"],["وَيُفْسِدُونَ","dan [mereka] menyebarkan rasuah"],["فِى","dalam"],["ٱلْأَرْضِ ۚ","bumi"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["هُمُ","mereka"],["ٱلْخَـٰسِرُونَ","(adalah) orang-orang yang rugi"]]],"35":["(Mengapa kamu kafir) hai warga Mekah? (kepada Allah, padahal) sesungguhnya (tadinya kamu mati) yakni ketika masih menjadi mani dalam sulbi bapakmu (lalu kamu dihidupkan-Nya) dalam rahim ibumu dan di dunia dengan jalan meniupkan roh pada tubuhmu. Pertanyaan di sini untuk menyatakan keheranan atas kekafiran mereka padahal bukti-bukti cukup ada atau dapat juga sebagai celaan dan kecaman terhadap mereka, (kemudian dimatikan-Nya) ketika sampainya ajalmu (lalu dihidupkan-Nya kembali) pada saat berbangkit (kemudian kamu dikembalikan kepada-Nya) yakni setelah berbangkit itu lalu dibalas-Nya amal perbuatanmu. Sebagai alasan kemungkinan saat berbangkit, Allah berfirman,",[["كَيْفَ","Bagaimana"],["تَكْفُرُونَ","(boleh) kamu tidak beriman"],["بِٱللَّهِ","kepada Allah"],["وَكُنتُمْ","Semasa kamu"],["أَمْوَٰتًۭا","mati"],["فَأَحْيَـٰكُمْ ۖ","kemudian Dia menghidupkan kamu"],["ثُمَّ","kemudian"],["يُمِيتُكُمْ","Dia akan menyebabkan kamu mati"],["ثُمَّ","kemudian"],["يُحْيِيكُمْ","Dia akan memberi kamu kehidupan"],["ثُمَّ","kemudian"],["إِلَيْهِ","kepada-Nya"],["تُرْجَعُونَ","kamu akan dikembalikan"]]],"36":["(Dialah yang telah menciptakan bagimu segala yang terdapat di muka bumi) yaitu menciptakan bumi beserta isinya, (kesemuanya) agar kamu memperoleh manfaat dan mengambil perbandingan darinya, (kemudian Dia hendak menyengaja hendak menciptakan) artinya setelah menciptakan bumi tadi Dia bermaksud hendak menciptakan pula (langit, maka dijadikan-Nya langit itu) 'hunna' sebagai kata ganti benda yang dimaksud adalah langit itu. Maksudnya ialah dijadikan-Nya, sebagaimana didapati pada ayat yang lain, 'faqadhaahunna,' yang berarti maka ditetapkan-Nya mereka, (tujuh langit dan Dia Maha Mengetahui atas segala sesuatu) dikemukakan secara 'mujmal' ringkas atau secara mufasshal terinci, maksudnya, \"Tidakkah Allah yang mampu menciptakan semua itu dari mula pertama, padahal Dia lebih besar dan lebih hebat daripada kamu, akan mampu pula menghidupkan kamu kembali?\"",[["هُوَ","Dia"],["ٱلَّذِى","(ialah) Yang"],["خَلَقَ","dicipta"],["لَكُم","bagi kamu"],["مَّا","apa"],["فِى","(berada) dalam"],["ٱلْأَرْضِ","bumi"],["جَمِيعًۭا","semua"],["ثُمَّ","Lebih-lebih lagi"],["ٱسْتَوَىٰٓ","Dia menoleh"],["إِلَى","kepada"],["ٱلسَّمَآءِ","syurga itu"],["فَسَوَّىٰهُنَّ","dan membentuk mereka"],["سَبْعَ","tujuh"],["سَمَـٰوَٰتٍۢ ۚ","syurga"],["وَهُوَ","Dan Dia"],["بِكُلِّ","daripada setiap"],["شَىْءٍ","perkara"],["عَلِيمٌۭ","(adalah) Maha Mengetahui"]]],"37":["(Dan) ingatlah, hai Muhammad! (Ketika Tuhanmu berfirman kepada para malaikat, \"Sesungguhnya Aku hendak menjadikan seorang khalifah di muka bumi\") yang akan mewakili Aku dalam melaksanakan hukum-hukum atau peraturan-peraturan-Ku padanya, yaitu Adam. (Kata mereka, \"Kenapa hendak Engkau jadikan di bumi itu orang yang akan berbuat kerusakan padanya) yakni dengan berbuat maksiat (dan menumpahkan darah) artinya mengalirkan darah dengan jalan pembunuhan sebagaimana dilakukan oleh bangsa jin yang juga mendiami bumi? Tatkala mereka telah berbuat kerusakan, Allah mengirim malaikat kepada mereka, maka dibuanglah mereka ke pulau-pulau dan ke gunung-gunung (padahal kami selalu bertasbih) maksudnya selalu mengucapkan tasbih (dengan memuji-Mu) yakni dengan membaca 'subhaanallaah wabihamdih', artinya 'Maha suci Allah dan aku memuji-Nya'. (dan menyucikan-Mu) membersihkan-Mu dari hal-hal yang tidak layak bagi-Mu. Huruf lam pada 'laka' itu hanya sebagai tambahan saja, sedangkan kalimat semenjak 'padahal' berfungsi sebagai 'hal' atau menunjukkan keadaan dan maksudnya adalah, 'padahal kami lebih layak untuk diangkat sebagai khalifah itu!'\" (Allah berfirman,) (\"Sesungguhnya Aku mengetahui apa yang tidak kamu ketahui\") tentang maslahat atau kepentingan mengenai pengangkatan Adam dan bahwa di antara anak cucunya ada yang taat dan ada pula yang durhaka hingga terbukti dan tampaklah keadilan di antara mereka. Jawab mereka, \"Tuhan tidak pernah menciptakan makhluk yang lebih mulia dan lebih tahu dari kami, karena kami lebih dulu dan melihat apa yang tidak dilihatnya.\" Maka Allah Taala pun menciptakan Adam dari tanah atau lapisan bumi dengan mengambil dari setiap corak atau warnanya barang segenggam, lalu diaduk-Nya dengan bermacam-macam jenis air lalu dibentuk dan ditiupkan-Nya roh hingga menjadi makhluk yang dapat merasa, setelah sebelumnya hanya barang beku dan tidak bernyawa.",[["وَإِذْ","Dan apabila"],["قَالَ","berkata"],["رَبُّكَ","Tuhanmu"],["لِلْمَلَـٰٓئِكَةِ","kepada para malaikat"],["إِنِّى","Sesungguhnya aku (adalah)"],["جَاعِلٌۭ","pergi ke tempat"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["خَلِيفَةًۭ ۖ","seorang naib"],["قَالُوٓا۟","mereka berkata"],["أَتَجْعَلُ","Adakah kamu akan meletakkan"],["فِيهَا","di dalamnya"],["مَن","(satu) siapa"],["يُفْسِدُ","akan menyebarkan rasuah"],["فِيهَا","di dalamnya"],["وَيَسْفِكُ","dan akan menumpahkan"],["ٱلدِّمَآءَ","[the] darah"],["وَنَحْنُ","sedangkan kita"],["نُسَبِّحُ","[kami] memuliakan (Mu)"],["بِحَمْدِكَ","dengan pujian-Mu"],["وَنُقَدِّسُ","dan kami sucikan"],["لَكَ ۖ","[kepada] kamu"],["قَالَ","Dia berkata"],["إِنِّىٓ","Sesungguhnya aku"],["أَعْلَمُ","[Aku] tahu"],["مَا","apa"],["لَا","tidak"],["تَعْلَمُونَ","kamu tahu"]]],"38":["(Dan diajarkan-Nya kepada Adam nama-nama) maksudnya nama-nama benda (kesemuanya) dengan jalan memasukkan ke dalam kalbunya pengetahuan tentang benda-benda itu (kemudian dikemukakan-Nya mereka) maksudnya benda-benda tadi yang ternyata bukan saja benda-benda mati, tetapi juga makhluk-makhluk berakal, (kepada para malaikat, lalu Allah berfirman) untuk memojokkan mereka, (\"Beritahukanlah kepada-Ku) sebutkanlah (nama-nama mereka) yakni nama-nama benda itu (jika kamu memang benar.\") bahwa tidak ada yang lebih tahu daripada kamu di antara makhluk-makhluk yang Kuciptakan atau bahwa kamulah yang lebih berhak untuk menjadi khalifah. Sebagai 'jawab syarat' ditunjukkan oleh kalimat sebelumnya.",[["وَعَلَّمَ","Dan Dia mengajar"],["ءَادَمَ","Adam"],["ٱلْأَسْمَآءَ","nama-nama"],["كُلَّهَا","kesemuanya"],["ثُمَّ","Kemudian"],["عَرَضَهُمْ","Dia memaparkannya"],["عَلَى","kepada"],["ٱلْمَلَـٰٓئِكَةِ","para malaikat"],["فَقَالَ","lalu Dia berkata"],["أَنۢبِـُٔونِى","Maklumkan Aku"],["بِأَسْمَآءِ","daripada (the) nama"],["هَـٰٓؤُلَآءِ","(daripada) ini"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","jujur"]]],"39":["(Jawab mereka, \"Maha suci Engkau!) artinya tidak sepatutnya kami akan menyanggah kehendak dan rencana-Mu (Tak ada yang kami ketahui, kecuali sekadar yang telah Engkau ajarkan kepada kami) mengenai benda-benda tersebut. (Sesungguhnya Engkaulah) sebagai 'taukid' atau penguat bagi Engkau yang pertama, (Yang Maha Tahu lagi Maha Bijaksana.\") hingga tidak seorang pun yang lepas dari pengetahuan serta hikmah kebijaksanaan-Mu.",[["قَالُوا۟","Mereka berkata"],["سُبْحَـٰنَكَ","Maha Suci Engkau"],["لَا","Tidak"],["عِلْمَ","pengetahuan"],["لَنَآ","(adalah) untuk kita"],["إِلَّا","kecuali"],["مَا","apa"],["عَلَّمْتَنَآ ۖ","Kamu telah mengajar kami"],["إِنَّكَ","Sesungguhnya Engkau"],["أَنتَ","kamu"],["ٱلْعَلِيمُ","(adalah) Yang Maha Mengetahui"],["ٱلْحَكِيمُ","Yang Maha Bijaksana"]]],"40":["(Allah berfirman, \"Hai Adam! Beritahukanlah kepada mereka) maksudnya kepada para malaikat itu (nama mereka\") yakni benda-benda itu. Maka disebutnya satu persatu menurut nama masing-masing berikut hikmah diciptakannya oleh Allah. (Maka setelah diberitahukannya kepada mereka nama benda-benda itu, Allah berfirman) kepada mereka guna mencela mereka, (\"Bukankah sudah Kukatakan kepada kalian bahwa Aku mengetahui rahasia langit dan bumi) maksudnya mengetahui barang yang tersembunyi pada keduanya, (dan mengetahui apa yang kamu lahirkan) yaitu ucapan yang kamu keluarkan, yaitu, 'Kenapa hendak Engkau jadikan... dan seterusnya' (dan apa yang kamu sembunyikan.\") yaitu ucapan yang kamu sembunyikan, seperti \"Allah tidak pernah menciptakan makhluk yang lebih mulia dan lebih pandai dari kami.\"",[["قَالَ","Dia berkata"],["يَـٰٓـَٔادَمُ","Wahai Adam"],["أَنۢبِئْهُم","Maklumkan kepada mereka"],["بِأَسْمَآئِهِمْ ۖ","daripada nama mereka"],["فَلَمَّآ","Dan apabila"],["أَنۢبَأَهُم","dia telah memberitahu mereka"],["بِأَسْمَآئِهِمْ","daripada nama mereka"],["قَالَ","Dia berkata"],["أَلَمْ","tidak"],["أَقُل","aku cakap"],["لَّكُمْ","kepada kamu"],["إِنِّىٓ","Sesungguhnya aku"],["أَعْلَمُ","[Aku] tahu"],["غَيْبَ","(yang) ghaib"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["وَأَعْلَمُ","dan aku tahu"],["مَا","apa"],["تُبْدُونَ","kamu dedahkan"],["وَمَا","dan apa"],["كُنتُمْ","kamu [adalah]"],["تَكْتُمُونَ","menyembunyikan"]]],"41":["(Dan) ingatlah! (Ketika Kami berfirman kepada para malaikat, \"Sujudlah kalian kepada Adam!\") Maksudnya sujud sebagai penghormatan dengan cara membungkukkan badan, (maka mereka pun sujud, kecuali Iblis) yakni nenek moyang bangsa jin yang ada di antara para malaikat, (ia enggan) tak hendak sujud (dan menyombongkan diri) dengan mengatakan bahwa ia lebih mulia daripada Adam (dan Iblis termasuk golongan yang kafir) dalam ilmu Allah Taala.",[["وَإِذْ","Dan apabila"],["قُلْنَا","Kami berkata"],["لِلْمَلَـٰٓئِكَةِ","kepada para malaikat"],["ٱسْجُدُوا۟","Sujud"],["لِـَٔادَمَ","kepada Adam"],["فَسَجَدُوٓا۟","[maka] mereka sujud"],["إِلَّآ","kecuali"],["إِبْلِيسَ","Iblis"],["أَبَىٰ","Dia menolak"],["وَٱسْتَكْبَرَ","dan sombong"],["وَكَانَ","dan menjadi"],["مِنَ","daripada"],["ٱلْكَـٰفِرِينَ","orang kafir"]]],"42":["(Dan Kami berfirman, \"Hai Adam! Berdiamlah kamu) yakni kamu sendiri 'kamu' yang kedua berfungsi sebagai penguat bagi yang pertama dan dihubungkan dengannya yang ditampilkan sebagai dhamir atau kata ganti yang tersembunyi (bersama istrimu) yakni Hawa yang diciptakan dari tulang rusuk Adam yang sebelah kiri (dalam surga ini dan makanlah di antara makanan-makanannya) (yang banyak) dan tidak dilarang (di mana saja kamu sukai, tetapi janganlah kamu dekati pohon ini) pohon anggur atau batang gandum ini atau lain-lainnya, maksudnya jangan memakan buahnya (hingga kamu menjadi orang-orang yang lalim.\") atau durhaka.",[["وَقُلْنَا","Dan Kami berfirman"],["يَـٰٓـَٔادَمُ","Wahai Adam"],["ٱسْكُنْ","Tinggal"],["أَنتَ","kamu"],["وَزَوْجُكَ","dan pasangan kamu"],["ٱلْجَنَّةَ","(dalam) Syurga"],["وَكُلَا","dan [kamu berdua] makan"],["مِنْهَا","daripadanya"],["رَغَدًا","secara bebas"],["حَيْثُ","(dari) di mana sahaja"],["شِئْتُمَا","kamu [berdua] mahu"],["وَلَا","Tetapi jangan"],["تَقْرَبَا","[kamu berdua] mendekati"],["هَـٰذِهِ","ini"],["ٱلشَّجَرَةَ","[the] pokok"],["فَتَكُونَا","supaya kamu [berdua] menjadi"],["مِنَ","daripada"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"43":["(Lalu keduanya digelincirkan oleh setan) oleh Iblis dan menurut suatu qiraat 'fa-azaalahumaa', artinya maka Iblis pun menyingkirkan keduanya (daripadanya), maksudnya dari dalam surga dengan memperdayakan serta mengatakan kepada mereka, \"Maukah kalian saya tunjukkan suatu macam pohon kekal yang akan mengekalkan kehidupan kalian? Itulah dia syajaratul khuldi atau pohon keabadian?\" Ia tidak lupa bersumpah atas nama Allah bahwa mereka hanyalah hendak menyampaikan nasihat dan anjuran baik belaka. Maka Adam dan Hawa pun memakan buah itu, (dan Allah mengeluarkan mereka dari keadaan yang mereka alami semula), yakni dari nikmat surga (dan firman Kami, \"Turunlah kalian!\") maksudnya ke bumi, yakni kalian berdua bersama anak cucu kalian itu (menjadi musuh bagi yang lain) disebabkan penganiayaan sebagian kalian terhadap lainnya, (dan bagi kalian tersedia tempat kediaman di bumi), artinya tempat menetap (dan kesenangan) berupa hasil tumbuh-tumbuhan yang kalian senangi dan dapat kalian nikmati (sampai waktu tertentu) maksudnya hingga saat datangnya ajal kalian nanti.",[["فَأَزَلَّهُمَا","Kemudian membuat [keduanya] tergelincir"],["ٱلشَّيْطَـٰنُ","syaitan"],["عَنْهَا","daripadanya"],["فَأَخْرَجَهُمَا","dan dia mengeluarkan [kedua-duanya] keluar"],["مِمَّا","daripada apa"],["كَانَا","mereka [kedua-duanya]."],["فِيهِ ۖ","di dalamnya"],["وَقُلْنَا","Dan Kami berfirman"],["ٱهْبِطُوا۟","Turun (kamu semua)"],["بَعْضُكُمْ","sebahagian daripada kamu"],["لِبَعْضٍ","kepada orang lain"],["عَدُوٌّۭ ۖ","(sebagai) musuh"],["وَلَكُمْ","dan untuk kamu"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["مُسْتَقَرٌّۭ","(adalah) tempat kediaman"],["وَمَتَـٰعٌ","dan peruntukan"],["إِلَىٰ","bagi"],["حِينٍۢ","tempoh"]]],"44":["(Kemudian Adam menerima beberapa kalimat dari Tuhannya), yakni dengan diilhamkan-Nya kepadanya, menurut suatu qiraat 'Adama' dibaca nashab, sedangkan 'kalimatun' dibaca rafa`, sehingga arti kalimat menjadi, \"maka datanglah kepada Adam kalimat dari Tuhannya\", yakni yang berbunyi \"rabbanaa zhalamnaa anfusanaa\", artinya \"Ya Tuhan kami, kami telah berbuat aniaya kepada diri kami... dan seterusnya\". Maka Adam pun menyampaikan doanya dengan ayat tersebut. (maka Allah menerima tobatnya), artinya mengampuni dosanya (Sesungguhnya Dia Maha Penerima tobat) terhadap hamba-hamba-Nya (lagi Maha Penyayang) terhadap mereka.",[["فَتَلَقَّىٰٓ","Kemudian diterima"],["ءَادَمُ","Adam"],["مِن","daripada"],["رَّبِّهِۦ","Tuhannya"],["كَلِمَـٰتٍۢ","perkataan"],["فَتَابَ","Maka berpalinglah (Tuhannya)."],["عَلَيْهِ ۚ","terhadapnya"],["إِنَّهُۥ","Sesungguhnya Dia"],["هُوَ","Dia"],["ٱلتَّوَّابُ","(ialah) yang sentiasa kembali (kepada rahmat)"],["ٱلرَّحِيمُ","Yang Maha Mengasihani"]]],"45":["(Kami berfirman, \"Turunlah kalian daripadanya\") maksudnya dari surga (semuanya) diulanginya dan dihubungkan-Nya dengan kalimat yang mula-mula tadi (kemudian jika) asalnya dari 'in maa' yang diidgamkan menjadi 'immaa' yang berarti jika; 'in' huruf syarat dan 'maa' sebagai tambahan. (datang petunjuk-Ku kepada kalian) berupa Kitab dan rasul, (maka barang siapa yang mengikuti petunjuk-Ku) lalu ia beriman kepada-Ku dan beramal serta taat kepada-Ku (niscaya tak ada kekhawatiran atas mereka dan tidak pula mereka berduka cita), yakni di akhirat kelak, karena mereka akan masuk surga.",[["قُلْنَا","Kami berkata"],["ٱهْبِطُوا۟","turunlah"],["مِنْهَا","daripadanya"],["جَمِيعًۭا ۖ","semua (kamu)"],["فَإِمَّا","dan apabila"],["يَأْتِيَنَّكُم","datang kepada kamu"],["مِّنِّى","daripada Aku"],["هُدًۭى","Bimbingan"],["فَمَن","maka sesiapa"],["تَبِعَ","mengikuti"],["هُدَاىَ","Bimbingan Aku"],["فَلَا","[maka] tidak"],["خَوْفٌ","bertakwa"],["عَلَيْهِمْ","(akan) pada mereka"],["وَلَا","dan bukan"],["هُمْ","mereka"],["يَحْزَنُونَ","akan bersedih"]]],"46":["(Adapun orang-orang yang kafir dan mendustakan ayat-ayat Kami) mendustakan kitab-kitab suci Kami (mereka itu penghuni neraka, mereka kekal di dalamnya) mereka tetap tinggal di sana untuk selama-lamanya, tidak akan mati dan tidak pula akan keluar.",[["وَٱلَّذِينَ","Dan mereka"],["كَفَرُوا۟","yang tidak beriman[d]"],["وَكَذَّبُوا۟","dan menafikan"],["بِـَٔايَـٰتِنَآ","Tanda-Tanda Kami"],["أُو۟لَـٰٓئِكَ","mereka"],["أَصْحَـٰبُ","(adalah) para sahabat"],["ٱلنَّارِ ۖ","(dari) api"],["هُمْ","mereka"],["فِيهَا","di dalamnya"],["خَـٰلِدُونَ","(akan) kekal selama-lamanya"]]],"47":["(Hai Bani Israel!) maksudnya ialah anak cucu Yakub (Ingatlah akan nikmat karunia-Ku yang telah Kuberikan kepada kalian) maksudnya kepada nenek moyang kalian, berupa menyelamatkan kalian dari kejaran Firaun, membelah lautan, menaungkan awan dan lain-lain, yaitu mensyukurinya dengan jalan taat kepada-Ku, (dan penuhilah janji kalian kepada-Ku) yang telah kalian janjikan dulu, berupa keimanan kepada Muhammad (niscaya Kupenuhi pula janji-Ku kepada kalian) berupa pemberian pahala dan masuk surga (dan hanya kepada-Kulah kalian harus takut) hingga kalian tidak berani menyalahi janji itu, dan kalian tidak perlu takut kepada pihak lain.",[["يَـٰبَنِىٓ","Wahai Kanak-kanak"],["إِسْرَٰٓءِيلَ","(dari) Israel"],["ٱذْكُرُوا۟","Ingat"],["نِعْمَتِىَ","Nikmat Aku"],["ٱلَّتِىٓ","yang"],["أَنْعَمْتُ","aku kurniakan"],["عَلَيْكُمْ","ke atas kamu"],["وَأَوْفُوا۟","dan penuhi"],["بِعَهْدِىٓ","Perjanjian-Ku"],["أُوفِ","aku akan tunaikan"],["بِعَهْدِكُمْ","perjanjian kamu"],["وَإِيَّـٰىَ","dan Aku Sendiri"],["فَٱرْهَبُونِ","takut [Aku]"]]],"48":["(Dan berimanlah kalian pada apa yang Kuturunkan), yakni Alquran (yang membenarkan apa yang ada beserta kalian), yaitu Taurat berupa kesamaan dalam ketauhidan kenabian Muhammad (dan janganlah kalian menjadi orang yang pertama kafir kepadanya), yakni dari golongan Ahlul Kitab karena orang-orang yang di belakang itu hanya akan mengikuti sikap dan tindakan kalian, sehingga dosa kekafiran mereka akan terpikul di atas pundak kalian (dan janganlah kalian jual) janganlah kalian tukar (ayat-ayat-Ku) yang terdapat dalam Kitab Suci kalian tentang sifat-sifat dan ciri-ciri Muhammad (dengan harga yang rendah) dengan pengganti yang rendah nilainya berupa harta dunia. Maksudnya janganlah kalian sembunyikan karena khawatir tidak akan memperoleh lagi keuntungan-keuntungan yang kalian dapatkan selama ini dari nenek moyang kalian (dan hanya kepada-Kulah kalian harus bertakwa) maksudnya harus takut dalam hal itu dan bukan kepada selain-Ku.",[["وَءَامِنُوا۟","Dan beriman"],["بِمَآ","pada apa"],["أَنزَلْتُ","Aku telah menurunkan"],["مُصَدِّقًۭا","mengesahkan"],["لِّمَا","itu yang"],["مَعَكُمْ","(ada) bersama kamu"],["وَلَا","dan jangan"],["تَكُونُوٓا۟","jadilah"],["أَوَّلَ","(yang) pertama"],["كَافِرٍۭ","orang kafir"],["بِهِۦ ۖ","daripadanya"],["وَلَا","Dan jangan"],["تَشْتَرُوا۟","pertukaran"],["بِـَٔايَـٰتِى","Tanda Aku (untuk)"],["ثَمَنًۭا","satu harga"],["قَلِيلًۭا","kecil"],["وَإِيَّـٰىَ","dan Aku Sendiri"],["فَٱتَّقُونِ","takut [Aku]"]]],"49":["(Dan janganlah kalian campur aduk) (barang yang hak) yang telah Kuturunkan kepada kalian (dengan yang batil) yang kamu ada-adakan (dan) jangan pula (kalian sembunyikan yang hak itu) berupa sifat dan ciri-ciri Muhammad (sedangkan kalian mengetahui) bahwa ia hak adanya.",[["وَلَا","Dan jangan"],["تَلْبِسُوا۟","campurkan"],["ٱلْحَقَّ","Kebenaran"],["بِٱلْبَـٰطِلِ","dengan kebatilan"],["وَتَكْتُمُوا۟","dan menyembunyikan"],["ٱلْحَقَّ","Kebenaran"],["وَأَنتُمْ","sedangkan kamu"],["تَعْلَمُونَ","[kamu] tahu"]]],"50":["(Dan dirikanlah salat, bayarkan zakat dan rukuklah bersama orang-orang yang rukuk) artinya salatlah bersama Muhammad dan para sahabatnya. Lalu Allah Taala menunjukkan kepada para ulama mereka yang pernah memesankan kepada kaum kerabat mereka yang masuk Islam, \"Tetaplah kalian dalam agama Muhammad, karena ia adalah agama yang benar!\"",[["وَأَقِيمُوا۟","Dan dirikanlah"],["ٱلصَّلَوٰةَ","solat"],["وَءَاتُوا۟","dan memberi"],["ٱلزَّكَوٰةَ","zakat"],["وَٱرْكَعُوا۟","dan sujud"],["مَعَ","dengan"],["ٱلرَّٰكِعِينَ","mereka yang sujud"]]],"51":["(Mengapa kamu menyuruh orang lain berbuat kebaikan), yaitu beriman pada kerasulan Muhammad (sedang kamu melupakan dirimu sendiri) hingga kamu mengabaikannya dan tak mau beriman kepadanya (padahal kamu membaca Kitab), yakni Taurat, di dalamnya tercantum ancaman atau siksaan terhadap orang yang tidak sesuai perkataan dengan perbuatannya! (Tidaklah kamu pikirkan?) akan akibat jelek perbuatanmu agar kamu insaf? Yang menjadi bahan pertanyaan dan kecaman ialah kalimat \"sedang kamu melupakan..... dan seterusnya\".",[["۞ أَتَأْمُرُونَ","Adakah kamu memesan"],["ٱلنَّاسَ","[orang]"],["بِٱلْبِرِّ","[the] kebenaran"],["وَتَنسَوْنَ","dan kamu lupa"],["أَنفُسَكُمْ","kamu sendiri"],["وَأَنتُمْ","sedangkan kamu"],["تَتْلُونَ","[kamu] mengaji"],["ٱلْكِتَـٰبَ ۚ","Kitab"],["أَفَلَا","Kemudian, tidak akan"],["تَعْقِلُونَ","kamu menggunakan alasan"]]],"52":["(Mintalah pertolongan) dalam menghadapi urusan atau kesulitan-kesulitanmu (dengan jalan bersabar) menahan diri dari hal-hal yang tidak baik (dengan salat). Khusus disebutkan di sini untuk menyatakan bagaimana pentingnya salat itu. Dalam sebuah hadis disebutkan bahwa jika Nabi saw. hatinya risau disebabkan sesuatu masalah, maka beliau segera melakukan salat. Ada pula yang mengatakan bahwa perkataan ini ditujukan kepada orang-orang Yahudi yang terhalang beriman disebabkan ketamakan dan ingin kedudukan. Maka mereka disuruh bersabar yang maksudnya ialah berpuasa, karena berpuasa dapat melenyapkan itu. Salat, karena dapat menimbulkan kekhusyukan dan membasmi ketakaburan. (Dan sesungguhnya ia) maksudnya salat (amat berat) akan terasa berat (kecuali bagi orang-orang yang khusyuk) yang cenderung kepada berbuat taat.",[["وَٱسْتَعِينُوا۟","Dan minta pertolongan"],["بِٱلصَّبْرِ","melalui kesabaran"],["وَٱلصَّلَوٰةِ ۚ","dan doa"],["وَإِنَّهَا","dan sesungguhnya, ia"],["لَكَبِيرَةٌ","(adalah) pasti sukar"],["إِلَّا","kecuali"],["عَلَى","pada"],["ٱلْخَـٰشِعِينَ","yang merendah diri"]]],"53":["(Orang-orang yang yakin) (bahwa mereka akan menemui Tuhan mereka) ketika berbangkit (dan bahwa mereka akan kembali kepada-Nya), yaitu di akhirat dan bahwa Dia akan membalas segala perbuatan mereka.",[["ٱلَّذِينَ","Orang yang"],["يَظُنُّونَ","beriman"],["أَنَّهُم","bahawa mereka"],["مُّلَـٰقُوا۟","akan bertemu"],["رَبِّهِمْ","Tuhan mereka"],["وَأَنَّهُمْ","dan bahawa mereka"],["إِلَيْهِ","kepada-Nya"],["رَٰجِعُونَ","akan kembali"]]],"54":["(Hai Bani Israel! Ingatlah akan nikmat-Ku yang telah Kuanugerahkan kepadamu), yaitu mensyukurinya dengan jalan menaati-Ku (dan ingatlah pula bahwa Aku telah mengistimewakan kamu) maksudnya nenek moyangmu (atas penduduk dunia) maksudnya penduduk di zaman mereka itu.",[["يَـٰبَنِىٓ","Wahai Kanak-kanak"],["إِسْرَٰٓءِيلَ","(dari) Israel"],["ٱذْكُرُوا۟","Ingat"],["نِعْمَتِىَ","Nikmat Aku"],["ٱلَّتِىٓ","yang"],["أَنْعَمْتُ","aku kurniakan"],["عَلَيْكُمْ","ke atas kamu"],["وَأَنِّى","dan bahawa aku"],["فَضَّلْتُكُمْ","[Aku] lebih suka kamu"],["عَلَى","atas"],["ٱلْعَـٰلَمِينَ","dunia"]]],"55":["(Dan takutlah olehmu) (suatu hari, yang pada hari itu tidak dapat membela) (seseorang atas orang lainnya walau sedikit pun) yakni pada hari kiamat (dan tidak diterima) ada yang membaca tuqbalu dengan ta dan ada pula yuqbalu dengan ya (daripadanya syafaat) artinya pada hari kiamat tidak ada perantara dan tak ada orang yang dapat dijadikan sebagai perantara (dan tidak pula tebusan) (dan tidaklah mereka akan ditolong) artinya dibebaskan dari azab Allah.",[["وَٱتَّقُوا۟","Dan ketakutan"],["يَوْمًۭا","sehari"],["لَّا","(akan) tidak"],["تَجْزِى","manfaat"],["نَفْسٌ","mana-mana jiwa"],["عَن","bagi"],["نَّفْسٍۢ","jiwa (yang lain)."],["شَيْـًۭٔا","sesuatu"],["وَلَا","dan bukan"],["يُقْبَلُ","akan diterima"],["مِنْهَا","daripadanya"],["شَفَـٰعَةٌۭ","sebarang syafaat"],["وَلَا","dan bukan"],["يُؤْخَذُ","akan diambil"],["مِنْهَا","daripadanya"],["عَدْلٌۭ","pampasan"],["وَلَا","dan bukan"],["هُمْ","mereka"],["يُنصَرُونَ","akan dibantu"]]],"56":["(Dan) ingatlah (ketika Kami membebaskan kamu) maksudnya nenek moyangmu, ucapan ini dan yang berikutnya ditujukan kepada generasi yang terdapat di masa nabi kita, mengenai nikmat karunia yang dilimpahkan kepada nenek moyang mereka itu, agar mereka ingat kepadanya dan beriman kepada Allah Taala (dari kaum keluarga Firaun yang merasakan kepadamu) maksudnya menimpakan (sejelek-jelek siksaan) artinya siksaan yang amat berat. Kalimat itu merupakan 'hal' bagi kata ganti orang yang terdapat pada 'membebaskan kamu'. (Mereka menyembelih) merupakan penjelasan bagi kalimat yang sebelumnya (anak-anak lelakimu) (dan membiarkan hidup) artinya tidak membunuh (anak-anak perempuanmu). Hal ini disebabkan ramalan tukang tenung bahwa akan ada seorang anak lelaki kelahiran Bani Israel yang akan menjadi penyebab lenyapnya kerajaan Firaun itu. (Dan hal yang demikian itu) yakni siksaan atau pembebasan (menjadi cobaan) ujian atau pemberian nikmat (yang amat besar dari Tuhanmu)?",[["وَإِذْ","Dan apabila"],["نَجَّيْنَـٰكُم","Kami selamatkan kamu"],["مِّنْ","daripada"],["ءَالِ","kaum"],["فِرْعَوْنَ","(daripada) Firaun"],["يَسُومُونَكُمْ","(yang) menganiaya kamu (dengan)"],["سُوٓءَ","ngeri"],["ٱلْعَذَابِ","azab"],["يُذَبِّحُونَ","penyembelihan"],["أَبْنَآءَكُمْ","anak lelaki kamu"],["وَيَسْتَحْيُونَ","dan membiarkan hidup"],["نِسَآءَكُمْ ۚ","wanita kamu"],["وَفِى","Dan dalam"],["ذَٰلِكُم","bahawa"],["بَلَآءٌۭ","(adalah) percubaan"],["مِّن","daripada"],["رَّبِّكُمْ","Tuhanmu"],["عَظِيمٌۭ","yang besar"]]],"57":["(Dan) ingatlah (ketika Kami pisah) Kami belah (demi karenamu) (lautan) sehingga kamu dapat masuk dan melintasinya ketika melarikan diri dari musuhmu (lalu Kami selamatkan kamu) dari bahaya tenggelam, (dan Kami tenggelamkan keluarga Firaun) beserta kaumnya (sedang kamu sendiri menyaksikan) hal itu, yaitu bertautnya lautan yang menyungkup mereka.",[["وَإِذْ","Dan apabila"],["فَرَقْنَا","Kami berpisah"],["بِكُمُ","bagi kamu"],["ٱلْبَحْرَ","laut"],["فَأَنجَيْنَـٰكُمْ","kemudian Kami selamatkan kamu"],["وَأَغْرَقْنَآ","dan Kami tenggelam"],["ءَالَ","kaum"],["فِرْعَوْنَ","(daripada) Firaun"],["وَأَنتُمْ","sedangkan kamu"],["تَنظُرُونَ","(sedang) mencari"]]],"58":["(Dan ingatlah ketika Kami menjanjikan) dalam sekian masa (kepada Musa selama empat puluh malam) maksudnya Kami janjikan akan memberinya Taurat setelah 40 malam untuk menjadi pedoman bagi kamu (lalu kamu ambil anak lembu) maksudnya patung anak lembu yang ditempa oleh Samiri menjadi tuhan (sepeninggalnya) artinya setelah ia pergi memenuhi perjanjian dengan Kami itu, (dan kamu adalah orang-orang aniaya) disebabkan menaruh sesuatu bukan pada tempatnya, yaitu mengambil anak lembu itu sebagai sembahan.",[["وَإِذْ","Dan apabila"],["وَٰعَدْنَا","Kami melantik"],["مُوسَىٰٓ","(untuk) Musa"],["أَرْبَعِينَ","empat puluh"],["لَيْلَةًۭ","malam-malam"],["ثُمَّ","Kemudian"],["ٱتَّخَذْتُمُ","kamu ambil"],["ٱلْعِجْلَ","anak lembu itu"],["مِنۢ","daripada"],["بَعْدِهِۦ","selepas dia"],["وَأَنتُمْ","dan kamu"],["ظَـٰلِمُونَ","(adalah) orang-orang yang zalim"]]],"59":["(Kemudian Kami maafkan kamu) Kami hapus dan ampuni kesalahanmu (setelah itu) setelah pengambilan patung menjadi tuhan (agar kamu bersyukur) dan menyadari nikmat karunia Kami kepadamu.",[["ثُمَّ","Kemudian"],["عَفَوْنَا","Kami memaafkan"],["عَنكُم","kamu"],["مِّنۢ","daripada"],["بَعْدِ","selepas"],["ذَٰلِكَ","bahawa"],["لَعَلَّكُمْ","supaya kamu"],["تَشْكُرُونَ","(bersyukur)."]]],"60":["(Dan ingatlah ketika Kami berikan kepada Musa Alkitab) yakni kitab Taurat (dan pemisah) merupakan 'athaf tafsir' hubungan sebagai penjelasan bagi Taurat yang menjadi pemisah di antara yang hak dengan yang batil, yang halal dengan yang haram (agar kamu peroleh petunjuk) dengannya dari kesesatan.",[["وَإِذْ","Dan apabila"],["ءَاتَيْنَا","Kami memberi"],["مُوسَى","Musa"],["ٱلْكِتَـٰبَ","Kitab"],["وَٱلْفُرْقَانَ","dan Kriteria"],["لَعَلَّكُمْ","mungkin kamu"],["تَهْتَدُونَ","(akan) mendapat petunjuk"]]],"61":["(Dan ketika Musa berkata kepada kaumnya) yang telah menyembah patung anak lembu itu (\"Hai kaumku! Sesungguhnya kamu telah menganiaya dirimu karena kamu telah mengambil anak lembu) sebagai sembahan, (maka bertobatlah kamu kepada Tuhanmu) yang telah menciptakanmu atas kesalahanmu tidak menyembah kepada-Nya, (maka bunuhlah dirimu) maksudnya hendaklah yang tidak bersalah di antaramu membunuh yang bersalah. (Demikian itu) yakni membunuh itu (lebih baik bagimu di sisi Tuhanmu) hingga dituntun-Nya kamu untuk melakukannya dan dikirim-Nya awan hitam agar sebagian kamu tidak melihat lainnya yang akan menyebabkan timbulnya rasa kasihan di antara kamu yang akan menghalangi pembunuhan ini. Maka berhasillah pembunuhan masal itu sehingga yang tewas di antara kamu tidak kurang dari tujuh puluh ribu orang banyaknya. (Maka Allah menerima tobatmu. Sesungguhnya Dia Maha Penerima Tobat lagi Maha Penyayang\").",[["وَإِذْ","Dan apabila"],["قَالَ","berkata"],["مُوسَىٰ","Musa"],["لِقَوْمِهِۦ","kepada umatnya"],["يَـٰقَوْمِ","Wahai kaumku"],["إِنَّكُمْ","Sesungguhnya kamu"],["ظَلَمْتُمْ","[kamu] telah berbuat salah"],["أَنفُسَكُم","kamu sendiri"],["بِٱتِّخَاذِكُمُ","dengan pengambilan kamu"],["ٱلْعِجْلَ","anak lembu itu"],["فَتُوبُوٓا۟","Maka bertaubatlah"],["إِلَىٰ","kepada"],["بَارِئِكُمْ","Penciptamu"],["فَٱقْتُلُوٓا۟","dan membunuh"],["أَنفُسَكُمْ","kamu sendiri"],["ذَٰلِكُمْ","Itu"],["خَيْرٌۭ","(lebih) baik"],["لَّكُمْ","bagi kamu"],["عِندَ","dengan"],["بَارِئِكُمْ","Penciptamu"],["فَتَابَ","Kemudian Dia berpaling"],["عَلَيْكُمْ ۚ","terhadap kamu"],["إِنَّهُۥ","Sesungguhnya Dia"],["هُوَ","Dia"],["ٱلتَّوَّابُ","(adalah) yang kembali"],["ٱلرَّحِيمُ","Yang Maha Mengasihani"]]],"62":["(Dan ketika kamu berkata) yaitu setelah kamu pergi bersama Musa untuk memohon ampun kepada Allah sebab menyembah patung anak lembu dan telah kamu dengar pula firman-Nya. (\"Hai Musa! Kami tidak akan beriman kepadamu sebelum kami melihat Allah secara terang!\") secara nyata. (Sebab itu kamu disambar petir) atau halilintar hingga kamu tewas (sedang kamu menyaksikannya) atas peristiwa yang menimpa dirimu itu.",[["وَإِذْ","Dan apabila"],["قُلْتُمْ","kamu kata"],["يَـٰمُوسَىٰ","Wahai Musa"],["لَن","tidak pernah"],["نُّؤْمِنَ","(akan) kami beriman"],["لَكَ","dalam kamu"],["حَتَّىٰ","sehingga"],["نَرَى","kita nampak"],["ٱللَّهَ","Allah"],["جَهْرَةًۭ","secara nyata"],["فَأَخَذَتْكُمُ","Jadi menangkap kamu"],["ٱلصَّـٰعِقَةُ","petir"],["وَأَنتُمْ","sedangkan kamu"],["تَنظُرُونَ","(sedang) mencari"]]],"63":["(Setelah itu Kami bangkitkan kamu) maksudnya Kami hidupkan kembali kamu, (setelah kematian kamu agar kamu bersyukur) atas nikmat karunia Kami itu.",[["ثُمَّ","Kemudian"],["بَعَثْنَـٰكُم","Kami menghidupkan kamu semula"],["مِّنۢ","daripada"],["بَعْدِ","selepas"],["مَوْتِكُمْ","kematian kamu"],["لَعَلَّكُمْ","supaya kamu"],["تَشْكُرُونَ","(bersyukur)."]]],"64":["(Dan Kami naungi kamu dengan awan), artinya Kami taruh awan tipis di atas kepalamu agar kamu terlindung dari panasnya cahaya matahari di padang Tih, (dan Kami turunkan padamu) di padang Tih itu (manna dan salwa) yakni makanan manis seperti madu dan daging burung sebangsa puyuh dan firman Kami, (\"Makanlah di antara makanan yang baik yang Kami karuniakan kepadamu.\") dan janganlah kamu simpan! Tetapi mereka mengingkari nikmat itu dan mereka menyimpannya. Maka Allah pun menghentikan rezeki itu atas mereka (dan tidaklah mereka menganiaya Kami) dengan perbuatan itu, (tetapi mereka menganiaya diri mereka sendiri) karena bencananya kembali kepada mereka juga.",[["وَظَلَّلْنَا","Dan Kami teduh"],["عَلَيْكُمُ","[atas] kamu"],["ٱلْغَمَامَ","(dengan) awan"],["وَأَنزَلْنَا","dan Kami turunkan"],["عَلَيْكُمُ","kepada kamu"],["ٱلْمَنَّ","[the] manna"],["وَٱلسَّلْوَىٰ ۖ","dan burung puyuh"],["كُلُوا۟","makan"],["مِن","daripada"],["طَيِّبَـٰتِ","(yang) perkara yang baik"],["مَا","bahawa"],["رَزَقْنَـٰكُمْ ۖ","Kami telah menyediakan kamu"],["وَمَا","Dan tidak"],["ظَلَمُونَا","mereka menzalimi Kami"],["وَلَـٰكِن","tetapi"],["كَانُوٓا۟","mereka adalah"],["أَنفُسَهُمْ","(kepada) diri mereka sendiri"],["يَظْلِمُونَ","melakukan kesalahan"]]],"65":["(Dan ingatlah ketika Kami berfirman,) kepada mereka setelah mereka keluar dari bukit Tih, (\"Masuklah kamu ke negeri ini\"), yakni Baitulmakdis atau Yerusalem dan ada pula yang mengatakannya 'Ariha' (Maka makanlah di antara makanannya yang baik lagi enak mana yang kamu sukai) tanpa ada larangan (dan masukilah pintu gerbangnya) (dalam keadaan bersujud) artinya menundukkan diri (dan ucapkanlah) sebagai permohonan, (\"Bebaskanlah kami dari dosa!\") (niscaya Kami ampuni) menurut suatu qiraat 'yughfar', sedangkan menurut suatu qiraat lainnya 'tughfar', keduanya kata kerja pasif yang berarti 'diampuni' (bagimu kesalahan-kesalahanmu dan akan Kami tambah pula pemberian Kami kepada orang-orang yang berbuat baik) maksudnya diampuni karena berlaku taat, diberi tambahan, yakni pahalanya.",[["وَإِذْ","Dan apabila"],["قُلْنَا","Kami berkata"],["ٱدْخُلُوا۟","Masuk"],["هَـٰذِهِ","ini"],["ٱلْقَرْيَةَ","bandar"],["فَكُلُوا۟","kemudian makan"],["مِنْهَا","daripada"],["حَيْثُ","di mana sahaja"],["شِئْتُمْ","kamu mahu[ed]"],["رَغَدًۭا","dengan banyaknya"],["وَٱدْخُلُوا۟","dan masuk"],["ٱلْبَابَ","pintu pagar"],["سُجَّدًۭا","sujud"],["وَقُولُوا۟","Dan katakan"],["حِطَّةٌۭ","Taubat"],["نَّغْفِرْ","Kami akan memaafkan"],["لَكُمْ","bagi kamu"],["خَطَـٰيَـٰكُمْ ۚ","dosa kamu"],["وَسَنَزِيدُ","Dan Kami akan menambah"],["ٱلْمُحْسِنِينَ","orang-orang yang berbuat baik (pahala)"]]],"66":["(Lalu orang-orang yang aniaya mengubah) di antara mereka (perintah yang tidak dititahkan kepada mereka) mereka mengatakan, habbatun fi sya`ratin, bahkan mereka memasukinya bukan dengan bersujud tetapi merangkak di atas pantat mereka. (Maka Kami timpakan atas orang-orang yang aniaya itu) di sini disebutkan \"atas orang-orang yang aniaya itu\", yang sebenarnya cukup dengan kata ganti 'mereka' saja, dengan maksud sebagai kecaman (siksa) berupa penyakit taun (dari langit disebabkan kefasikan mereka) disebabkan mereka melanggar ketaatan. Maka dalam waktu satu jam ada 70 ribu orang atau mendekati jumlah itu di antara mereka yang mati.",[["فَبَدَّلَ","Tetapi berubah"],["ٱلَّذِينَ","orang yang"],["ظَلَمُوا۟","dizalimi"],["قَوْلًا","(perkataan)."],["غَيْرَ","selain daripada"],["ٱلَّذِى","(itu) yang"],["قِيلَ","telah dikatakan"],["لَهُمْ","kepada mereka"],["فَأَنزَلْنَا","maka Kami turunkan"],["عَلَى","ke atas"],["ٱلَّذِينَ","orang yang"],["ظَلَمُوا۟","dizalimi"],["رِجْزًۭا","azab"],["مِّنَ","daripada"],["ٱلسَّمَآءِ","langit"],["بِمَا","kerana"],["كَانُوا۟","mereka adalah"],["يَفْسُقُونَ","membangkang menderhaka"]]],"67":["(Dan) ingatlah (ketika Musa memohon air) (untuk kaumnya) yakni ketika mereka telah kehausan di padang Tih (lalu firman Kami, \"Pukulkanlah tongkatmu ke atas batu itu!\") yaitu batu yang pernah membawa lari pakaiannya, bentuknya tipis persegi empat sebesar kepala manusia, batu lunak atau seperti keduanya lalu dipukulkannya (maka terpancarlah) terbelahlah batu itu lalu keluar air (daripadanya dua belas mata air) yaitu sebanyak jumlah suku Bani Israel (sesungguhnya telah mengetahui tiap-tiap suku) yakni tiap-tiap suku di antara mereka (tempat minum mereka) masing-masing hingga mereka tidak saling berebut. Lalu firman Kami kepada mereka, (\"Makan dan minumlah rezeki yang diberikan Allah dan janganlah kamu berbuat keonaran di muka bumi dengan melakukan pengrusakan!\") 'Mufsidiin' menjadi 'hal' yang memperkuat perbuatan pelaku '`atsiya' yang berarti berbuat keonaran.",[["۞ وَإِذِ","Dan apabila"],["ٱسْتَسْقَىٰ","meminta (untuk) air"],["مُوسَىٰ","Musa"],["لِقَوْمِهِۦ","untuk umatnya"],["فَقُلْنَا","[jadi] Kami berkata"],["ٱضْرِب","mogok"],["بِّعَصَاكَ","dengan kakitangan kamu"],["ٱلْحَجَرَ ۖ","batu itu"],["فَٱنفَجَرَتْ","Kemudian terpancut keluar"],["مِنْهُ","daripadanya"],["ٱثْنَتَا","(daripada)"],["عَشْرَةَ","dua belas"],["عَيْنًۭا ۖ","mata air"],["قَدْ","Sesungguhnya"],["عَلِمَ","tahu"],["كُلُّ","semua"],["أُنَاسٍۢ","kaum"],["مَّشْرَبَهُمْ ۖ","tempat minum mereka"],["كُلُوا۟","makan"],["وَٱشْرَبُوا۟","dan minum"],["مِن","daripada"],["رِّزْقِ","(the) peruntukan (of)"],["ٱللَّهِ","Allah"],["وَلَا","dan jangan"],["تَعْثَوْا۟","bertindak jahat"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["مُفْسِدِينَ","menyebarkan rasuah"]]],"68":["(Dan ketika kamu berkata, \"Hai Musa! Kami tidak bisa tahan dengan satu makanan saja!\") maksudnya satu macam saja, yaitu manna dan salwa. (Oleh sebab itu mohonkanlah untuk kami kepada Tuhanmu, agar Dia mengeluarkan bagi kami) sesuatu (dari apa yang ditumbuhkan bumi berupa) sebagai penjelasan (sayur-mayur, ketimun, bawang putih) (kacang adas dan bawang merah, maka jawabnya) yaitu jawab Musa kepada mereka, (\"Maukah kamu mengambil sesuatu yang lebih rendah atau lebih jelek sebagai pengganti) (dari yang lebih baik) atau lebih utama?\" Pertanyaan ini berarti penolakan, tetapi mereka tidak mau menarik permintaan itu hingga Musa pun berdoa kepada Allah, maka Allah Taala berfirman, (\"Turunlah kamu) pergilah (ke salah satu kota) di antara kota-kota (pastilah kamu akan memperoleh) di sana (apa yang kamu minta\") dari tumbuh-tumbuhan itu. (Lalu dipukulkan) ditimpakan (atas mereka kenistaan) kehinaan dan kenistaan (dan kemiskinan) yakni bekas-bekas dan pengaruh kemiskinan berupa sikap statis dan rendah diri yang akan selalu menyertai mereka walaupun mereka kaya, tak ubahnya bagai mata uang yang selalu menurut dan tidak akan lepas dari cetakannya, (dan kembalilah mereka) (membawa kemurkaan dari Allah, demikian itu), yakni pukulan dan kemurkaan Allah itu (disebabkan mereka) (mengingkari ayat-ayat Allah dan membunuh para nabi) seperti Nabi Zakaria dan Yahya (tanpa hak) hanya karena keaniayaan semata. (Demikian itu terjadi karena mereka selalu berbuat kedurhakaan dan karena mereka melanggar batas) artinya batas-batas peraturan hingga jatuh ke dalam maksiat. Kalimat pertama diulangnya untuk memperkuatnya.",[["وَإِذْ","Dan apabila"],["قُلْتُمْ","kamu kata"],["يَـٰمُوسَىٰ","Wahai Musa"],["لَن","tidak pernah (akan)"],["نَّصْبِرَ","kita tahan"],["عَلَىٰ","[pada]"],["طَعَامٍۢ","makanan"],["وَٰحِدٍۢ","(dari) satu (jenis)"],["فَٱدْعُ","jadi berdoalah"],["لَنَا","bagi kami"],["رَبَّكَ","(kepada) Tuhanmu"],["يُخْرِجْ","untuk melahirkan"],["لَنَا","bagi kami"],["مِمَّا","daripada apa"],["تُنۢبِتُ","tumbuh"],["ٱلْأَرْضُ","bumi"],["مِنۢ","daripada"],["بَقْلِهَا","herbanya"],["وَقِثَّآئِهَا","[dan] timunnya"],["وَفُومِهَا","[dan] bawang putihnya"],["وَعَدَسِهَا","[dan] lentilnya"],["وَبَصَلِهَا ۖ","dan bawangnya"],["قَالَ","Dia berkata"],["أَتَسْتَبْدِلُونَ","Nak tukar"],["ٱلَّذِى","itu yang"],["هُوَ","[ia]"],["أَدْنَىٰ","(adalah) lebih rendah"],["بِٱلَّذِى","untuk itu yang"],["هُوَ","[ia]"],["خَيْرٌ ۚ","(lebih) baik"],["ٱهْبِطُوا۟","turunlah"],["مِصْرًۭا","(ke) sebuah bandar"],["فَإِنَّ","jadi memang"],["لَكُم","bagi kamu"],["مَّا","(ialah) apa"],["سَأَلْتُمْ ۗ","kamu telah meminta (untuk)"],["وَضُرِبَتْ","Dan telah dipukul"],["عَلَيْهِمُ","ke atas mereka"],["ٱلذِّلَّةُ","penghinaan itu"],["وَٱلْمَسْكَنَةُ","dan kesengsaraan"],["وَبَآءُو","dan mereka menarik diri mereka sendiri"],["بِغَضَبٍۢ","kemarahan"],["مِّنَ","daripada"],["ٱللَّهِ ۗ","Allah"],["ذَٰلِكَ","Itu (adalah)"],["بِأَنَّهُمْ","kerana mereka"],["كَانُوا۟","dulu"],["يَكْفُرُونَ","kufur"],["بِـَٔايَـٰتِ","dalam (the) Tanda-tanda"],["ٱللَّهِ","(milik) Allah"],["وَيَقْتُلُونَ","dan membunuh"],["ٱلنَّبِيِّـۧنَ","para Nabi"],["بِغَيْرِ","tanpa (apa-apa)"],["ٱلْحَقِّ ۗ","[yang] betul"],["ذَٰلِكَ","Itu"],["بِمَا","(adalah) kerana"],["عَصَوا۟","mereka ingkar"],["وَّكَانُوا۟","dan mereka"],["يَعْتَدُونَ","melanggar"]]],"69":["(Sesungguhnya orang-orang yang beriman) kepada para nabi di masa lalu (dan orang-orang Yahudi) (orang-orang Kristen dan orang-orang Shabiin) yakni segolongan dari orang-orang Yahudi atau Nasrani (siapa saja yang beriman) di antara mereka (kepada Allah dan hari akhir) di masa nabi kita (serta mengerjakan amal saleh) yaitu syariatnya (mereka akan memperoleh pahala) sebagai ganjaran dari amal perbuatan mereka itu (di sisi Tuhan mereka, tak ada kekhawatiran terhadap mereka dan tidak pula mereka berduka cita). Dhamir atau kata ganti orang pada 'aamana', 'amila' dan sesudahnya hendaklah diartikan secara umum atau siapa saja.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَٱلَّذِينَ","dan orang yang"],["هَادُوا۟","menjadi Yahudi"],["وَٱلنَّصَـٰرَىٰ","dan orang Kristian"],["وَٱلصَّـٰبِـِٔينَ","dan golongan Sabian"],["مَنْ","yang"],["ءَامَنَ","beriman"],["بِٱللَّهِ","kepada Allah"],["وَٱلْيَوْمِ","dan Hari"],["ٱلْـَٔاخِرِ","[yang] Terakhir"],["وَعَمِلَ","dan lakukan"],["صَـٰلِحًۭا","amal soleh"],["فَلَهُمْ","jadi bagi mereka"],["أَجْرُهُمْ","ganjaran mereka"],["عِندَ","(adalah) dengan"],["رَبِّهِمْ","Tuhan mereka"],["وَلَا","dan tidak"],["خَوْفٌ","bertakwa"],["عَلَيْهِمْ","ke atas mereka"],["وَلَا","dan bukan"],["هُمْ","mereka"],["يَحْزَنُونَ","akan bersedih"]]],"70":["(Dan) ingatlah (ketika Kami mengambil ikrar darimu) yakni ikrar bahwa kamu akan melakukan ajaran-ajaran yang terdapat dalam Taurat. (dan) sesungguhnya (Kami angkat gunung Thursina ke atasmu) artinya Kami cabut dari dasarnya untuk ditimpakan kepadamu, yakni tatkala kamu tidak mau berikrar seraya Kami berfirman, (\"Peganglah dengan teguh apa yang Kami berikan kepadamu ini!) maksudnya secara giat dan sungguh-sungguh (dan ingatlah baik-baik apa yang ada di dalamnya) yakni dengan mengamalkannya (agar kamu termasuk orang-orang yang bertakwa.\") Artinya terpelihara dirimu dari api neraka dan perbuatan durhaka.",[["وَإِذْ","Dan apabila"],["أَخَذْنَا","Kami ambil"],["مِيثَـٰقَكُمْ","perjanjian kamu"],["وَرَفَعْنَا","dan Kami bangkitkan"],["فَوْقَكُمُ","atas kamu"],["ٱلطُّورَ","gunung itu"],["خُذُوا۟","tahan"],["مَآ","apa"],["ءَاتَيْنَـٰكُم","Kami telah memberi kamu"],["بِقُوَّةٍۢ","dengan kekuatan"],["وَٱذْكُرُوا۟","dan ingat"],["مَا","apa"],["فِيهِ","(ada) di dalamnya"],["لَعَلَّكُمْ","mungkin kamu"],["تَتَّقُونَ","(akan menjadi) soleh"]]],"71":["(Kemudian kamu berpaling) menyalahi ikrar (setelah itu) maksudnya setelah berikrar tadi (maka kalau tidak ada karunia Allah dan rahmat-Nya kepadamu) yaitu dengan menerima tobatnya atau menangguhkan siksa terhadapmu (niscayalah kamu akan termasuk orang-orang yang merugi) atau celaka.",[["ثُمَّ","Kemudian"],["تَوَلَّيْتُم","kamu berpaling"],["مِّنۢ","daripada"],["بَعْدِ","selepas"],["ذَٰلِكَ ۖ","bahawa"],["فَلَوْلَا","Jadi jika tidak"],["فَضْلُ","(untuk) Rahmat"],["ٱللَّهِ","(milik) Allah"],["عَلَيْكُمْ","ke atas kamu"],["وَرَحْمَتُهُۥ","dan RahmatNya"],["لَكُنتُم","pasti kamu akan menjadi"],["مِّنَ","daripada"],["ٱلْخَـٰسِرِينَ","yang rugi"]]],"72":["(Dan sesungguhnya) lam-nya 'lam qasam' menyatakan bersumpah artinya 'demi' (kamu telah mengetahui) (orang-orang yang melanggar) peraturan (di antaramu pada hari Sabtu) yakni dengan menangkap ikan padahal Kami telah melarangmu dari demikian; dan mereka ini ialah penduduk Eilat atau Ayilah (lalu Kami titahkan kepada mereka, \"Jadilah kalian kera yang hina!\") artinya yang terkucil. Apa yang dikehendaki Allah itu pun terlaksana dan setelah masa tiga hari mereka menemui kematian.",[["وَلَقَدْ","Dan sesungguhnya"],["عَلِمْتُمُ","kamu tahu"],["ٱلَّذِينَ","orang yang"],["ٱعْتَدَوْا۟","dilanggar"],["مِنكُمْ","antara kamu"],["فِى","dalam"],["ٱلسَّبْتِ","(perkara) Sabat"],["فَقُلْنَا","Maka Kami berkata"],["لَهُمْ","kepada mereka"],["كُونُوا۟","Jadilah"],["قِرَدَةً","beruk"],["خَـٰسِـِٔينَ","dihina"]]],"73":["(Maka Kami jadikan dia) maksudnya hukuman tersebut (sebagai peringatan) cermin perbandingan hingga mereka tidak melakukannya lagi (bagi umat-umat di masa itu dan bagi mereka yang datang kemudian) (serta menjadi pengajaran bagi orang-orang yang bertakwa) kepada Allah Taala. Dikhususkan bagi orang-orang ini, karena hanya merekalah yang dapat mengambil manfaat darinya sedangkan orang lain tidak.",[["فَجَعَلْنَـٰهَا","Jadi Kami berjaya"],["نَكَـٰلًۭا","hukuman pencegahan"],["لِّمَا","untuk mereka"],["بَيْنَ","(di) hadapan"],["يَدَيْهَا","(daripada) mereka"],["وَمَا","dan mereka"],["خَلْفَهَا","selepas mereka"],["وَمَوْعِظَةًۭ","dan teguran"],["لِّلْمُتَّقِينَ","bagi orang-orang yang takut (kepada Allah)"]]],"74":["(Dan) ingatlah (ketika Musa berkata kepada kaumnya,) yakni ketika ada di antara mereka itu seseorang yang terbunuh sedangkan mereka tidak tahu siapa pembunuhnya, lalu mereka minta kepada Musa untuk memohonkan kepada Allah agar Dia dapat memberitahukan siapa pembunuhnya itu. Maka dia memohon, lalu katanya, (\"Sesungguhnya Allah menyuruh kamu menyembelih seekor sapi betina.\" Jawab mereka, \"Apakah kamu hendak menjadikan kami sebagai bahan ejekan?\") artinya suruhan kamu itu akan menyebabkan kami menjadi sasaran olok-olok dan tertawaan orang. (Jawab Musa, \"Aku berlindung) maksudnya aku tidak sudi (kepada Allah) akan (menjadi golongan orang-orang yang jahil.\") yang suka berolok-olok. Tatkala mereka ketahui bahwa Musa bersungguh-sungguh.",[["وَإِذْ","Dan apabila"],["قَالَ","berkata"],["مُوسَىٰ","Musa"],["لِقَوْمِهِۦٓ","kepada umatnya"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["يَأْمُرُكُمْ","memerintahkan kamu"],["أَن","bahawa"],["تَذْبَحُوا۟","kamu sembelih"],["بَقَرَةًۭ ۖ","seekor lembu"],["قَالُوٓا۟","Mereka berkata"],["أَتَتَّخِذُنَا","Adakah kamu membawa kami"],["هُزُوًۭا ۖ","(dalam) ejekan"],["قَالَ","Dia berkata"],["أَعُوذُ","Aku mencari perlindungan"],["بِٱللَّهِ","kepada Allah"],["أَنْ","bahawa"],["أَكُونَ","aku jadi"],["مِنَ","antara"],["ٱلْجَـٰهِلِينَ","yang jahil"]]],"75":["(Mereka bertanya, \"Mohonkanlah kepada Tuhanmu agar Dia menjelaskan kepada kami, sapi betina yang manakah itu?\") maksudnya tentang usianya, apakah yang tua atau yang muda? (Jawab Musa, \"Allah berfirman bahwa sapi itu ialah sapi betina yang tidak tua) berusia lanjut (dan tidak pula muda) atau terlalu kecil, tetapi (pertengahan) (di antara demikian), yakni di antara tua dan muda tadi (maka lakukanlah apa yang diperintahkan kepadamu.\") yaitu supaya menyembelih sapi yang telah dijelaskan itu.",[["قَالُوا۟","Mereka berkata"],["ٱدْعُ","Berdoalah"],["لَنَا","bagi kami"],["رَبَّكَ","(kepada) Tuhanmu"],["يُبَيِّن","untuk membuat jelas"],["لَّنَا","kepada kami"],["مَا","apa"],["هِىَ ۚ","ia (adalah)"],["قَالَ","Dia berkata"],["إِنَّهُۥ","Sesungguhnya Dia"],["يَقُولُ","berkata"],["إِنَّهَا","[Memang] ia"],["بَقَرَةٌۭ","(ialah) seekor lembu"],["لَّا","tidak"],["فَارِضٌۭ","lama"],["وَلَا","dan bukan"],["بِكْرٌ","muda"],["عَوَانٌۢ","pertengahan umur"],["بَيْنَ","antara"],["ذَٰلِكَ ۖ","bahawa"],["فَٱفْعَلُوا۟","begitu juga"],["مَا","apa"],["تُؤْمَرُونَ","kamu diperintahkan"]]],"76":["(Kata mereka, \"Mohonkanlah kepada Tuhanmu untuk kami agar dijelaskan-Nya kepada kami apa warnanya!\" Jawab Musa, \"Allah berfirman bahwa sapi betina itu ialah sapi betina yang kuning, yakni yang kuning tua warnanya, maksudnya yang kuning pekat (yang menyenangkan orang-orang yang memandang.\") artinya menarik hati mereka disebabkan keelokannya.",[["قَالُوا۟","Mereka berkata"],["ٱدْعُ","Berdoalah"],["لَنَا","bagi kami"],["رَبَّكَ","(kepada) Tuhanmu"],["يُبَيِّن","untuk membuat jelas"],["لَّنَا","kepada kami"],["مَا","apa"],["لَوْنُهَا ۚ","(adalah) warnanya"],["قَالَ","Dia berkata"],["إِنَّهُۥ","Sesungguhnya Dia"],["يَقُولُ","berkata"],["إِنَّهَا","'[Memang] begitu"],["بَقَرَةٌۭ","seekor lembu"],["صَفْرَآءُ","kuning"],["فَاقِعٌۭ","terang"],["لَّوْنُهَا","(dalam) warnanya"],["تَسُرُّ","menggembirakan"],["ٱلنَّـٰظِرِينَ","(kepada) orang-orang yang melihatnya.'"]]],"77":["(Kata mereka, \"Mohonkanlah kepada Tuhanmu untuk kami agar dijelaskan-Nya bagi kami hakikat sapi betina itu) apakah yang dimanjakan ataukah yang dipekerjakan? (karena sesungguhnya sapi itu) yakni kalau jenisnya baru yang disebutkan sifatnya itu (masih samar bagi kami) karena banyaknya hingga kami tidak mengetahui mana yang dimaksud (dan sesungguhnya kami insya Allah akan memperoleh petunjuk.\") untuk mendapatkannya. Dalam sebuah hadis disebutkan bahwa sekiranya mereka tidak mengucapkan insya Allah, tidaklah akan dijelaskan kepada mereka untuk selama-lamanya.",[["قَالُوا۟","Mereka berkata"],["ٱدْعُ","Berdoalah"],["لَنَا","bagi kami"],["رَبَّكَ","(kepada) Tuhanmu"],["يُبَيِّن","untuk membuat jelas"],["لَّنَا","kepada kami"],["مَا","apa"],["هِىَ","ia (adalah)"],["إِنَّ","Sesungguhnya"],["ٱلْبَقَرَ","[the] lembu"],["تَشَـٰبَهَ","nampak serupa"],["عَلَيْنَا","kepada kami"],["وَإِنَّآ","Dan sesungguhnya kita"],["إِن","jika"],["شَآءَ","wasiat"],["ٱللَّهُ","Allah"],["لَمُهْتَدُونَ","Sesungguhnya merekalah orang-orang yang mendapat petunjuk"]]],"78":["(Kata Musa, \"Allah berfirman bahwa sapi betina itu ialah sapi betina yang belum pernah dipakai untuk bekerja) (membajak tanah) untuk ditanami. Kalimat belakang ini menjadi sifat bagi 'dipakai untuk bekerja' dan termasuk barang yang dinafikan. (dan tidak pula untuk mengairi tanaman) atau tanah yang dipersiapkan untuk ditanami tumbuh-tumbuhan (tidak bercacat) bebas dari aib dan bekas-bekas bekerja berat (tidak ada belangnya.\") tidak ada warna lain dari warna aslinya. (Kata mereka, \"Sekarang barulah kamu mengatakan kebenaran.\") Maksudnya memberikan penjelasan yang cukup jelas tentang sapi yang dimaksud. Mereka cari sapi tersebut dan kebetulan ditemukan pada seorang anak muda yang berbakti kepada ibunya, lalu mereka beli dengan emas sepenuh bungkusan yang terbuat dari kulit sapi itu. (Lalu mereka menyembelihnya dan hampir saja mereka tidak melaksanakannya) karena harganya yang tinggi. Dalam sebuah hadis disebutkan, seandainya mereka segera menyembelih seekor sapi betina yang ada tanpa banyak tanya, yang demikian itu akan mencukupi. Tetapi mereka menyusahkan diri mereka sendiri sehingga dipersulit oleh Allah.",[["قَالَ","Dia berkata"],["إِنَّهُۥ","Sesungguhnya Dia"],["يَقُولُ","berkata"],["إِنَّهَا","[Memang] ia"],["بَقَرَةٌۭ","(ialah) seekor lembu"],["لَّا","tidak"],["ذَلُولٌۭ","terlatih"],["تُثِيرُ","untuk membajak"],["ٱلْأَرْضَ","bumi"],["وَلَا","dan bukan"],["تَسْقِى","air"],["ٱلْحَرْثَ","padang"],["مُسَلَّمَةٌۭ","bunyi"],["لَّا","tidak"],["شِيَةَ","cela"],["فِيهَا ۚ","di dalamnya"],["قَالُوا۟","Mereka berkata"],["ٱلْـَٔـٰنَ","Sekarang"],["جِئْتَ","kamu telah datang"],["بِٱلْحَقِّ ۚ","dengan kebenaran"],["فَذَبَحُوهَا","Maka mereka menyembelihnya"],["وَمَا","dan bukan"],["كَادُوا۟","mereka berada dekat"],["يَفْعَلُونَ","(untuk) melakukan (itu)"]]],"79":["(Dan ketika kamu membunuh seorang manusia, lalu kamu tuduh-menuduh tentang hal itu) asalnya fatadaara'tum, lalu ta diidgamkan ke dal yang berarti bertengkar dan saling menuduh (sedangkan Allah menyingkapkan) atau memperlihatkan (apa yang kamu sembunyikan) tentang persoalan tersebut. Kalimat ini adalah suatu interupsi dan merupakan awal kisah",[["وَإِذْ","Dan apabila"],["قَتَلْتُمْ","kamu membunuh"],["نَفْسًۭا","seorang lelaki"],["فَٱدَّٰرَْٰٔتُمْ","kemudian kamu mempertikaikan"],["فِيهَا ۖ","berkenaan dengannya"],["وَٱللَّهُ","tetapi Allah"],["مُخْرِجٌۭ","(ialah) Yang telah melahirkan"],["مَّا","apa"],["كُنتُمْ","kamu dahulu"],["تَكْتُمُونَ","menyembunyikan"]]],"80":["(Lalu firman Kami, \"Pukullah dia) maksudnya mayat dari orang yang terbunuh tadi (dengan salah satu anggota badan sapi betina itu!\") Lalu mereka pukul dengan lidah atau pangkal ekornya sehingga ia pun hidup kembali dan mengatakan siapa pembunuhnya yang tiada lain dari dua orang saudara sepupunya yang disebutkan namanya masing-masing. Kemudian ia menjadi mayat kembali, maka kedua pembunuhnya tidak diperbolehkan untuk mendapatkan harta warisan, bahkan mereka pun dibunuh pula lalu firman Allah Taala, (\"Demikianlah) maksudnya caranya (Allah menghidupkan kembali orang-orang yang telah mati dan memperlihatkan kepadamu tanda-tanda-Nya) bukti-bukti kekuasaan-Nya (agar kamu memikirkan\") dan merenungkannya sehingga mengerti dan mengimani Allah yang kuasa menghidupkan seorang manusia yang telah meninggal juga sanggup menghidupkan berjuta-juta manusia lainnya.",[["فَقُلْنَا","Maka Kami berkata"],["ٱضْرِبُوهُ","Pukul dia"],["بِبَعْضِهَا ۚ","dengan sebahagian daripadanya"],["كَذَٰلِكَ","Macam ni"],["يُحْىِ","menghidupkan semula"],["ٱللَّهُ","Allah"],["ٱلْمَوْتَىٰ","yang mati"],["وَيُرِيكُمْ","dan menunjukkan kepada kamu"],["ءَايَـٰتِهِۦ","Tanda-tandaNya"],["لَعَلَّكُمْ","mungkin kamu boleh"],["تَعْقِلُونَ","gunakan akal"]]],"81":["(Kemudian hatimu menjadi keras) ditujukan kepada orang-orang Yahudi hingga tak dapat dimasuki kebenaran (setelah itu) yakni setelah peristiwa dihidupkannya orang yang telah mati dan kejadian-kejadian sebelumnya, (maka ia adalah seperti batu) dalam kerasnya (atau lebih keras lagi) daripada batu. (Padahal di antara batu-batu itu sesungguhnya ada yang mengalir anak-anak sungai daripadanya dan di antaranya ada pula yang terbelah) asalnya 'yatasyaqqaqu' lalu ta diidgamkan pada syin hingga menjadi 'yasysyaqqaqu' (lalu keluarlah air daripadanya dan sesungguhnya di antaranya ada pula yang jatuh meluncur) dari atas ke bawah (karena takut kepada Allah) sebaliknya hatimu tidak terpengaruh karenanya serta tidak pula menjadi lunak atau tunduk. (Dan Allah sekali-kali tidak lengah terhadap apa yang kamu kerjakan) hanya ditangguhkan-Nya menjatuhkan hukuman hingga saatnya nanti. Menurut satu qiraat bukan 'ta`maluun' tetapi 'ya`maluun', artinya 'yang mereka kerjakan,' sehingga berarti mengalihkan arah pembicaraan.",[["ثُمَّ","Kemudian"],["قَسَتْ","mengeras"],["قُلُوبُكُم","hati kamu"],["مِّنۢ","daripada"],["بَعْدِ","selepas"],["ذَٰلِكَ","bahawa"],["فَهِىَ","jadi mereka"],["كَٱلْحِجَارَةِ","(menjadi) seperti batu"],["أَوْ","atau"],["أَشَدُّ","lebih kuat"],["قَسْوَةًۭ ۚ","(dalam) kekerasan"],["وَإِنَّ","Dan sesungguhnya"],["مِنَ","daripada"],["ٱلْحِجَارَةِ","batu-batu itu"],["لَمَا","sudah pasti (ada beberapa) yang"],["يَتَفَجَّرُ","terpancut keluar"],["مِنْهُ","daripadanya"],["ٱلْأَنْهَـٰرُ ۚ","sungai-sungai"],["وَإِنَّ","dan sesungguhnya"],["مِنْهَا","daripada mereka"],["لَمَا","sudah pasti (ada beberapa) yang"],["يَشَّقَّقُ","berpecah"],["فَيَخْرُجُ","jadi keluar"],["مِنْهُ","daripadanya"],["ٱلْمَآءُ ۚ","air itu"],["وَإِنَّ","dan sesungguhnya"],["مِنْهَا","daripada mereka"],["لَمَا","sudah pasti (ada beberapa) yang"],["يَهْبِطُ","jatuh ke bawah"],["مِنْ","daripada"],["خَشْيَةِ","bertakwa"],["ٱللَّهِ ۗ","(milik) Allah"],["وَمَا","Dan tidak"],["ٱللَّهُ","(ialah) Allah"],["بِغَـٰفِلٍ","tak sedar"],["عَمَّا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"]]],"82":["(Apakah masih kamu harapkan) hai orang beriman (bahwa mereka akan beriman) yakni orang-orang Yahudi itu (kepadamu, sedangkan sebagian) atau satu golongan (di antara mereka) yakni pendeta-pendeta mereka (mendengar firman Allah) yaitu Taurat (lalu mengubahnya) (setelah mereka memahaminya) (padahal mereka mengetahui) bahwa sebenarnya mereka mengada-ada. Pertanyaan di sini berarti sanggahan terhadap orang-orang beriman hingga berarti, \"Tak usah kamu harapkan mereka akan beriman karena dulu mereka juga sudah kafir!\"",[["۞ أَفَتَطْمَعُونَ","Adakah kamu berharap"],["أَن","bahawa"],["يُؤْمِنُوا۟","mereka akan beriman"],["لَكُمْ","[untuk] kamu"],["وَقَدْ","sedangkan memang"],["كَانَ","(ada) telah"],["فَرِيقٌۭ","sebuah parti"],["مِّنْهُمْ","daripada mereka"],["يَسْمَعُونَ","(yang pernah) mendengar"],["كَلَـٰمَ","(the) perkataan"],["ٱللَّهِ","(milik) Allah"],["ثُمَّ","kemudian"],["يُحَرِّفُونَهُۥ","mereka memutarbelitkannya"],["مِنۢ","daripada"],["بَعْدِ","selepas"],["مَا","[apa]"],["عَقَلُوهُ","mereka memahaminya"],["وَهُمْ","sedangkan mereka"],["يَعْلَمُونَ","mengetahui"]]],"83":["(Dan jika mereka berjumpa) maksudnya jika orang-orang Yahudi dan orang-orang munafik itu bertemu dengan (orang-orang beriman, mereka mengatakan, \"Kami pun telah beriman\") bahwa Muhammad itu adalah seorang nabi yang telah diberitakan kedatangannya dalam kitab suci kami, (tetapi bila mereka telah kembali) atau berada (sesama mereka, maka kata mereka) yakni para pemimpin mereka yang bukan munafik kepada yang munafik itu, (\"Apakah kamu hendak menceritakan kepada mereka) maksudnya kepada orang-orang mukmin (tentang apa yang telah dibukakan Allah kepada kamu) artinya tentang hal-hal yang telah diberitahukan Allah kepadamu dalam Taurat mengenai sifat-sifat dan ciri-ciri Muhammad (sehingga dengan demikian mereka dapat mematahkan alasanmu) 'lam' di sini berarti 'mengakibatkan' (dengannya di sisi Tuhanmu) yakni di akhirat kelak, di mana mereka akan dapat mengajukan bukti penyelewenganmu, yaitu tak hendak mengikuti Muhammad padahal mengetahui kebenarannya. (Tidaklah kamu mengerti?\") bahwa mereka akan dapat mematahkan alasanmu jika kamu menyebut-nyebut soal itu? Dari itu hentikanlah tindakanmu itu!",[["وَإِذَا","Dan apabila"],["لَقُوا۟","mereka berjumpa"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["قَالُوٓا۟","mereka berkata"],["ءَامَنَّا","Kami telah beriman"],["وَإِذَا","Tetapi apabila"],["خَلَا","bertemu secara tertutup"],["بَعْضُهُمْ","sebahagian mereka"],["إِلَىٰ","dengan"],["بَعْضٍۢ","beberapa (yang lain)"],["قَالُوٓا۟","mereka berkata"],["أَتُحَدِّثُونَهُم","Adakah kamu memberitahu mereka"],["بِمَا","apa"],["فَتَحَ","mempunyai"],["ٱللَّهُ","Allah"],["عَلَيْكُمْ","kepada kamu"],["لِيُحَآجُّوكُم","supaya mereka berdebat dengan kamu"],["بِهِۦ","dengan itu"],["عِندَ","sebelum"],["رَبِّكُمْ ۚ","Tuhanmu"],["أَفَلَا","Maka janganlah (kamu)"],["تَعْقِلُونَ","faham"]]],"84":["(Tidakkah mereka ketahui) Pertanyaan di sini menunjukkan pengakuan, sehingga kalimat ini berarti bahwa mereka benar tidak mengetahui sedangkan wau yang terletak di depan menyatakan athaf atau adanya hubungan (bahwa Allah mengetahui apa yang mereka rahasiakan dan apa yang mereka lahirkan) tentang masalah-masalah tersebut hingga seharusnya mereka akan lebih hati-hati dan waspada.",[["أَوَلَا","Jangan"],["يَعْلَمُونَ","mereka tahu"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["يَعْلَمُ","mengetahui"],["مَا","apa"],["يُسِرُّونَ","mereka sembunyikan"],["وَمَا","dan apa"],["يُعْلِنُونَ","mereka mengisytiharkan"]]],"85":["(Dan di antara mereka) di antara orang-orang Yahudi itu (ada yang buta huruf) atau orang-orang awam yang (tidak mengetahui Alkitab) maksudnya Taurat (kecuali) (angan-angan) atau kebohongan belaka, yakni yang mereka dengar dari para pemimpin mereka lalu mereka terima dan percayai. (Dan tiadalah) (mereka) yakni dalam menentang kenabian Muhammad dan soal-soal lainnya yang mereka buat-buat itu (kecuali hanyalah menduga-duga belaka) yakni dugaan yang tidak berdasarkan ilmu.",[["وَمِنْهُمْ","Dan di antara mereka"],["أُمِّيُّونَ","(adalah) mereka yang tidak bersurat"],["لَا","(siapa) tidak"],["يَعْلَمُونَ","mengetahui"],["ٱلْكِتَـٰبَ","buku itu"],["إِلَّآ","kecuali"],["أَمَانِىَّ","angan-angan"],["وَإِنْ","dan bukan"],["هُمْ","mereka"],["إِلَّا","(buat apa-apa) kecuali"],["يَظُنُّونَ","meneka"]]],"86":["(Maka kecelakaan besarlah) atau siksaan berat (bagi orang-orang yang menulis Alkitab dengan tangan mereka sendiri) artinya membuat-buatnya menurut kemauan mereka (lalu mereka katakan, \"Ini dari Allah,\" dengan maksud untuk memperdagangkannya dengan harga murah) dengan tujuan untuk memperoleh keuntungan yang sedikit berupa harta dunia. Mereka ini ialah orang-orang Yahudi yang mengubah-ubah sifat-sifat nabi yang tercantum dalam Taurat, begitu pun ayat rajam dan lain-lain yang mereka tulis lain daripada yang dimaksud. (Maka siksaan beratlah bagi mereka karena apa yang ditulis oleh tangan mereka) disebabkan mereka mengada-ada yang tidak ada (dan siksaan beratlah bagi mereka, disebabkan apa yang mereka kerjakan) yakni melakukan penyelewengan dan kecurangan.",[["فَوَيْلٌۭ","jadi celaka"],["لِّلَّذِينَ","kepada mereka yang"],["يَكْتُبُونَ","menulis"],["ٱلْكِتَـٰبَ","buku itu"],["بِأَيْدِيهِمْ","dengan tangan (sendiri)."],["ثُمَّ","kemudian"],["يَقُولُونَ","mereka berkata"],["هَـٰذَا","Ini"],["مِنْ","(adalah)"],["عِندِ","daripada"],["ٱللَّهِ","Allah"],["لِيَشْتَرُوا۟","untuk tukar barang"],["بِهِۦ","dengannya"],["ثَمَنًۭا","(untuk) harga"],["قَلِيلًۭا ۖ","sedikit"],["فَوَيْلٌۭ","jadi celaka"],["لَّهُم","kepada mereka"],["مِّمَّا","bagi apa"],["كَتَبَتْ","telah menulis"],["أَيْدِيهِمْ","tangan mereka"],["وَوَيْلٌۭ","dan celaka"],["لَّهُم","kepada mereka"],["مِّمَّا","bagi apa"],["يَكْسِبُونَ","mereka perolehi"]]],"87":["(Dan mereka berkata) yakni tatkala Nabi mengancam mereka dengan neraka, (\"Kami sekali-kali takkan disentuh) tidak akan ditimpa sama sekali (oleh api neraka, kecuali selama hari-hari yang berbilang\") maksudnya selama beberapa hari saja, yaitu selama 40 hari yakni selama waktu nenek moyang mereka menyembah patung lembu, kemudian siksaan itu akan berhenti. (Katakanlah) kepada mereka hai Muhammad, (\"Apakah kamu telah menerima) hamzah washalnya dibuang karena cukup dengan adanya hamzah istifham (janji dari Allah) atau ikrar mengenai hal tersebut? (Sehingga Allah tidak akan menyalahi janji-Nya?) Tidak, bukan? (Ataukah) bahkan (kamu hanya mengatakan terhadap Allah apa yang tidak kamu ketahui\").",[["وَقَالُوا۟","Dan mereka berkata"],["لَن","tidak pernah"],["تَمَسَّنَا","akan menyentuh kita"],["ٱلنَّارُ","neraka"],["إِلَّآ","kecuali"],["أَيَّامًۭا","(selama) hari"],["مَّعْدُودَةًۭ ۚ","bernombor"],["قُلْ","Katakanlah"],["أَتَّخَذْتُمْ","Adakah kamu telah mengambil"],["عِندَ","daripada"],["ٱللَّهِ","Allah"],["عَهْدًۭا","sebuah perjanjian"],["فَلَن","jadi jangan sekali-kali"],["يُخْلِفَ","akan pecah"],["ٱللَّهُ","Allah"],["عَهْدَهُۥٓ ۖ","PerjanjianNya"],["أَمْ","Atau"],["تَقُولُونَ","(adakah) kamu katakan"],["عَلَى","terhadap"],["ٱللَّهِ","Allah"],["مَا","apa"],["لَا","tidak"],["تَعْلَمُونَ","kamu tahu"]]],"88":["(Tidak demikian yang sebenarnya) tetapi kamu pasti akan masuk neraka dan kekal di dalamnya. (Barang siapa yang berbuat kejahatan) atau kemusyrikan (dan ia dilingkungi oleh dosanya) dapat secara tunggal dan dapat pula secara jamak, maksudnya dosanya itu telah meliputi dan melingkunginya dari segala penjuru disebabkan kematiannya dalam keadaan musyrik (mereka itulah penghuni neraka, mereka kekal di dalamnya). Di sini dipakai jamak, dengan menitikberatkan arti 'man' atau 'barang siapa'.",[["بَلَىٰ","ya"],["مَن","sesiapa sahaja"],["كَسَبَ","diperolehi"],["سَيِّئَةًۭ","jahat"],["وَأَحَـٰطَتْ","dan mengelilinginya"],["بِهِۦ","dengan"],["خَطِيٓـَٔتُهُۥ","dosanya"],["فَأُو۟لَـٰٓئِكَ","[jadi] mereka"],["أَصْحَـٰبُ","(adalah) para sahabat"],["ٱلنَّارِ ۖ","(dari) api"],["هُمْ","mereka"],["فِيهَا","di dalamnya"],["خَـٰلِدُونَ","(akan) kekal selama-lamanya"]]],"89":["(Sebaliknya orang-orang yang beriman dan beramal saleh mereka itu penduduk surga, kekal mereka di dalamnya.)",[["وَٱلَّذِينَ","Dan orang yang"],["ءَامَنُوا۟","beriman"],["وَعَمِلُوا۟","dan lakukan"],["ٱلصَّـٰلِحَـٰتِ","amal soleh"],["أُو۟لَـٰٓئِكَ","mereka"],["أَصْحَـٰبُ","(adalah) para sahabat"],["ٱلْجَنَّةِ ۖ","(dari) Syurga"],["هُمْ","mereka"],["فِيهَا","di dalamnya"],["خَـٰلِدُونَ","(akan) kekal selama-lamanya"]]],"90":["(Dan) ingatlah (ketika Kami mengambil ikrar dari Bani Israel) maksudnya dalam Taurat, dan Kami katakan, (\"Janganlah kamu menyembah) ada yang membaca dengan 'ta' dan ada pula dengan 'ya', yaitu 'laa ya`buduuna', artinya mereka tidak akan menyembah (kecuali kepada Allah). Kalimat ini merupakan kalimat berita tetapi berarti larangan. Ada pula yang membaca 'laa ta`buduu', artinya 'janganlah kamu sembah!' (Dan) berbuat kebaikanlah! (kepada kedua orang tua dengan sebaik-baiknya) maksudnya berbakti selain itu juga (kaum kerabat) athaf pada al-waalidain (anak-anak yatim dan orang-orang miskin serta ucapkanlah kepada manusia) kata-kata (yang baik) misalnya menyuruh pada yang baik dan melarang dari yang mungkar, berkata jujur mengenai diri Muhammad dan ramah tamah terhadap sesama manusia. Menurut suatu qiraat 'husna' dengan 'ha' baris di depan dan 'sin' sukun yang merupakan mashdar atau kata benda dan dipergunakan sebagai sifat dengan maksud untuk menyatakan 'teramat' artinya teramat baik. (Dan dirikanlah salat serta bayarkan zakat!) Sesungguhnya kamu telah memberikan ikrar tersebut. (Kemudian kamu tidak memenuhi) janji itu. Di sini tidak disebut-sebut orang ketiga, yaitu nenek moyang mereka (kecuali sebagian kecil dari kamu, dan kamu juga berpaling.\") seperti halnya nenek moyangmu.",[["وَإِذْ","Dan apabila"],["أَخَذْنَا","Kami ambil"],["مِيثَـٰقَ","(the) perjanjian"],["بَنِىٓ","(daripada) Kanak-kanak"],["إِسْرَٰٓءِيلَ","(dari) Israel"],["لَا","Tidak"],["تَعْبُدُونَ","kamu akan menyembah"],["إِلَّا","kecuali"],["ٱللَّهَ","Allah"],["وَبِٱلْوَٰلِدَيْنِ","dan dengan ibu bapa"],["إِحْسَانًۭا","(jadi) baik"],["وَذِى","dan (dengan)"],["ٱلْقُرْبَىٰ","saudara mara"],["وَٱلْيَتَـٰمَىٰ","dan anak-anak yatim"],["وَٱلْمَسَـٰكِينِ","dan yang memerlukan"],["وَقُولُوا۟","dan bercakap"],["لِلنَّاسِ","kepada [orang]"],["حُسْنًۭا","kebaikan"],["وَأَقِيمُوا۟","dan mendirikan"],["ٱلصَّلَوٰةَ","solat"],["وَءَاتُوا۟","dan memberi"],["ٱلزَّكَوٰةَ","zakat tersebut"],["ثُمَّ","Kemudian"],["تَوَلَّيْتُمْ","kamu berpaling"],["إِلَّا","kecuali"],["قَلِيلًۭا","beberapa"],["مِّنكُمْ","daripada kamu"],["وَأَنتُم","dan kamu (adalah)"],["مُّعْرِضُونَ","menolak"]]],"91":["(Dan ingatlah ketika Kami menerima perjanjian pula darimu) dan firman Kami, (\"Kamu tidak akan menumpahkan darahmu) artinya mengalirkannya dengan berbunuhan sesamamu (dan tidak akan mengeluarkan dirimu dari kampung halamanmu) dari negerimu. (Kemudian kamu berikrar) akan menepati perjanjian tersebut (sedangkan kamu mempersaksikan.\") atas diri kamu sendiri.",[["وَإِذْ","Dan apabila"],["أَخَذْنَا","Kami ambil"],["مِيثَـٰقَكُمْ","perjanjian kamu"],["لَا","Tidak"],["تَسْفِكُونَ","adakah kamu akan menumpahkan"],["دِمَآءَكُمْ","darah kamu"],["وَلَا","dan bukan"],["تُخْرِجُونَ","(akan) mengusir"],["أَنفُسَكُم","kamu sendiri"],["مِّن","daripada"],["دِيَـٰرِكُمْ","rumah kamu"],["ثُمَّ","kemudian"],["أَقْرَرْتُمْ","kamu mengesahkan"],["وَأَنتُمْ","sedangkan kamu"],["تَشْهَدُونَ","(sedang) menyaksikan"]]],"92":["(Kemudian kamu) hai (Bani Israel, kamu bunuh dirimu) dengan berbunuhan sesamamu (dan kamu usir sebagian kamu dari kampung halaman mereka, kamu bertolong-tolongan) ta asalnya diidgamkan pada zha sehingga dibaca 'tazhzhaaharuuna', tetapi pada satu qiraat diringankan dengan membuangnya sehingga bacaannya menjadi 'tazhaaharuuna' dengan membuang zha yang berarti tolong-menolong (terhadap mereka dengan berbuat dosa) maksiat (dan permusuhan) atau penganiayaan. (Tetapi jika mereka datang kepadamu sebagai orang-orang tawanan) pada satu qiraat tercantum 'asra' (kamu tebus mereka) ada pula yang membaca 'tafduuhum', artinya kamu bebaskan mereka dari tawanan dengan harta atau lainnya dan ini termasuk kebiasaan yang berlaku di kalangan orang-orang Yahudi (padahal dia) artinya kenyataannya (mengusir mereka itu diharamkan bagimu). Kalimat ini berhubungan dengan firman-Nya, \"dan kamu usir,\" sedangkan kalimat-kalimat yang terdapat di antara keduanya merupakan 'jumlah mu`taridhah' atau interupsi, artinya sebagaimana diharamkannya mengabaikan tebusan. Selama ini suku Quraizhah mengadakan persekutuan dengan Aus, sedangkan Nadhir dengan Khajraj. Setiap suku ikut berperang bersama sekutu mereka, bahkan sampai menghancurkan dan mengusir pihak lawan walaupun sama-sama Yahudi. Tetapi jika Yahudi pihak lawan itu tertawan, maka mereka tebus. Jika ditanyakan kepada mereka, kenapa kamu perangi dan kamu tebus mereka, maka jawab mereka, \"Karena kami diminta mereka untuk memberikan tebusan.\" Jika ditanyakan, \"Kenapa pula kamu perangi mereka?\" Jawab mereka, \"Karena kami merasa malu jika sekutu-sekutu kami menderita kekalahan!\" Firman Allah Taala, (\"Apakah kamu beriman pada sebagian Alkitab) yakni soal menebus tawanan (dan ingkar terhadap sebagian yang lain) agar tidak membunuh, tidak mengusir dan tidak bantu-membantu berbuat dosa dan penganiayaan. (Tidak ada balasan bagi orang yang berbuat demikian di antaramu kecuali kehinaan) atau kenistaan (dalam kehidupan dunia) kehinaan ini telah dialami oleh Bani Quraizhah dengan dibunuh dan dibasminya golongan laki-laki mereka, dan juga oleh Bani Nadhir yang diusir ke Syam dan diwajibkan membayar upeti. (Dan pada hari kiamat mereka dikembalikan pada siksaan yang amat berat dan Allah tidak lengah dari apa yang kamu kerjakan). Ada yang membaca dengan ta dan ada pula yang dengan ya.",[["ثُمَّ","Kemudian"],["أَنتُمْ","kamu"],["هَـٰٓؤُلَآءِ","(adalah) mereka"],["تَقْتُلُونَ","(siapa) membunuh"],["أَنفُسَكُمْ","kamu sendiri"],["وَتُخْرِجُونَ","dan mengusir"],["فَرِيقًۭا","sebuah parti"],["مِّنكُم","daripada kamu"],["مِّن","daripada"],["دِيَـٰرِهِمْ","rumah mereka"],["تَظَـٰهَرُونَ","kamu menyokong satu sama lain"],["عَلَيْهِم","terhadap mereka"],["بِٱلْإِثْمِ","dalam dosa"],["وَٱلْعُدْوَٰنِ","dan pelanggaran"],["وَإِن","Dan jika"],["يَأْتُوكُمْ","mereka datang kepada kamu"],["أُسَـٰرَىٰ","(sebagai) tawanan"],["تُفَـٰدُوهُمْ","kamu tebus mereka"],["وَهُوَ","semasa itu"],["مُحَرَّمٌ","(telah) dilarang"],["عَلَيْكُمْ","kepada kamu"],["إِخْرَاجُهُمْ ۚ","pengusiran mereka"],["أَفَتُؤْمِنُونَ","Jadi adakah kamu beriman"],["بِبَعْضِ","sebahagian (daripada)"],["ٱلْكِتَـٰبِ","Kitab"],["وَتَكْفُرُونَ","dan tidak beriman"],["بِبَعْضٍۢ ۚ","sebahagiannya"],["فَمَا","Kemudian apa"],["جَزَآءُ","(sepatutnya) balasan"],["مَن","(untuk yang satu) yang"],["يَفْعَلُ","tidak"],["ذَٰلِكَ","bahawa"],["مِنكُمْ","antara kamu"],["إِلَّا","kecuali"],["خِزْىٌۭ","aib"],["فِى","dalam"],["ٱلْحَيَوٰةِ","kehidupan"],["ٱلدُّنْيَا ۖ","dunia"],["وَيَوْمَ","dan (pada) Hari"],["ٱلْقِيَـٰمَةِ","tentang [kebangkitan]"],["يُرَدُّونَ","mereka akan dihantar balik"],["إِلَىٰٓ","kepada"],["أَشَدِّ","(yang) paling parah"],["ٱلْعَذَابِ ۗ","hukuman"],["وَمَا","Dan tidak"],["ٱللَّهُ","(ialah) Allah"],["بِغَـٰفِلٍ","tak sedar"],["عَمَّا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"]]],"93":["(Merekalah orang-orang yang membeli kehidupan dunia dengan kehidupan akhirat) artinya lebih mengutamakan dunia daripada akhirat (maka tidaklah akan diringankan siksa terhadap mereka dan tidaklah mereka akan beroleh bantuan\") untuk menghindarkan siksaan itu.",[["أُو۟لَـٰٓئِكَ","Mereka itu"],["ٱلَّذِينَ","(adalah) orang-orang yang"],["ٱشْتَرَوُا۟","dibeli"],["ٱلْحَيَوٰةَ","kehidupan"],["ٱلدُّنْيَا","dunia"],["بِٱلْـَٔاخِرَةِ ۖ","untuk akhirat"],["فَلَا","jadi tidak"],["يُخَفَّفُ","akan diringankan"],["عَنْهُمُ","bagi mereka"],["ٱلْعَذَابُ","azab"],["وَلَا","dan bukan"],["هُمْ","mereka"],["يُنصَرُونَ","akan dibantu"]]],"94":["(Sesungguhnya Kami telah mendatangkan Alkitab kepada Musa) yakni Taurat, (lalu Kami susul setelah itu dengan para rasul) secara berturut-turut, artinya Kami kirim seorang rasul sesudah yang lain, (dan Kami berikan kepada Isa putra Maryam bukti-bukti kebenaran) yakni mukjizat menghidupkan mayat, menyembuhkan orang yang buta dan berpenyakit kusta. (Dan Kami perkuat ia dengan Roh Kudus) merupakan 'idhafat maushuf pada sifat' maksudnya ialah Roh yang disucikan yakni Jibril, sehingga karena kesuciannya ikut mengiringkannya ke mana pergi. Namun kamu tidak juga hendak mengikuti jalan yang benar! (Apakah setiap datang kepadamu seorang rasul dengan membawa apa yang tidak diingini) atau disukai (dirimu) berupa kebenaran (kamu menjadi takabur) atau menyombongkan diri, tak mau mengikutinya. Kalimat ini merupakan jawaban bagi 'setiap', dan dialah yang menjadi sasaran pertanyaan, sedangkan tujuannya tidak lain dari celaan dan kecaman, (maka sebagian) di antara mereka (kamu dustakan) seperti Nabi Isa (dan sebagian lagi kamu bunuh) kata kerja 'mudhari'' atau masa sekarang untuk menunjukkan peristiwa di masa lampau, artinya telah kamu bunuh Zakaria dan Yahya.",[["وَلَقَدْ","Dan sesungguhnya"],["ءَاتَيْنَا","Kami memberi"],["مُوسَى","Musa"],["ٱلْكِتَـٰبَ","Kitab"],["وَقَفَّيْنَا","dan Kami ikuti"],["مِنۢ","daripada"],["بَعْدِهِۦ","selepas dia"],["بِٱلرُّسُلِ ۖ","dengan para Rasul"],["وَءَاتَيْنَا","Dan Kami berikan"],["عِيسَى","Isa"],["ٱبْنَ","(si) anak lelaki"],["مَرْيَمَ","(dari) Maryam"],["ٱلْبَيِّنَـٰتِ","tanda-tanda yang jelas"],["وَأَيَّدْنَـٰهُ","dan Kami menyokongnya"],["بِرُوحِ","(dengan)"],["ٱلْقُدُسِ ۗ","Roh Kudus"],["أَفَكُلَّمَا","Adakah (tidak) begitu (begitu) apabila-apabila"],["جَآءَكُمْ","datang kepada kamu"],["رَسُولٌۢ","seorang Rasul"],["بِمَا","dengan apa"],["لَا","tidak"],["تَهْوَىٰٓ","keinginan"],["أَنفُسُكُمُ","kamu sendiri"],["ٱسْتَكْبَرْتُمْ","kamu bertindak sombong"],["فَفَرِيقًۭا","Jadi pesta"],["كَذَّبْتُمْ","kamu menafikan"],["وَفَرِيقًۭا","dan pesta"],["تَقْتُلُونَ","kamu membunuh (ed)"]]],"95":["(Dan mereka berkata) kepada nabi untuk berolok-olok, (\"Hati kami tertutup\") jamak dari 'aghlaf' yang berarti dibungkus tertutup rapat, sehingga tak dapat mendengar apa yang dikatakan orang. Firman Allah Taala, (\"Tetapi) menegaskan kenyataan sebenarnya (Allah telah mengutuk mereka) menjauhkan mereka dari rahmat-Nya dengan menolak permohonan mereka sehingga mereka menjadi putus asa (disebabkan kekafiran mereka) jadi bukanlah karena cacat pada hati mereka, (maka hanya sedikit sekali mereka yang beriman\"). 'Maa' merupakan tambahan untuk menunjukkan teramat sedikitnya mereka yang beriman itu.",[["وَقَالُوا۟","Dan mereka berkata"],["قُلُوبُنَا","hati kita"],["غُلْفٌۢ ۚ","(adalah) dibungkus"],["بَل","Bahkan"],["لَّعَنَهُمُ","telah mengutuk mereka"],["ٱللَّهُ","Allah"],["بِكُفْرِهِمْ","kerana kekufuran mereka"],["فَقَلِيلًۭا","sangat sedikit"],["مَّا","(ialah) apa"],["يُؤْمِنُونَ","mereka beriman"]]],"96":["(Dan tatkala datang kepada mereka Alquran dari Allah yang membenarkan apa yang ada pada mereka) yakni Taurat (padahal sebelumnya mereka) maksudnya sebelum datangnya Alquran itu (memohon pertolongan) agar beroleh kemenangan (atas orang-orang yang kafir) dengan mengucapkan, \"Ya Allah, tolonglah kami dengan nabi yang akan dibangkitkan di akhir zaman.\" (Maka setelah datang kepada mereka apa yang telah mereka ketahui) yaitu berupa kebenaran dengan diutusnya Nabi Muhammad itu (mereka lalu ingkar kepadanya) disebabkan kedengkian dan takut kehilangan pengaruh. Jawaban bagi 'lammaa' atau 'tatkala' yang pertama, ditunjukkan oleh jawaban 'lammaa' yang kedua (maka laknat Allahlah atas orang-orang yang kafir itu).",[["وَلَمَّا","Dan apabila"],["جَآءَهُمْ","datang kepada mereka"],["كِتَـٰبٌۭ","sebuah Buku"],["مِّنْ","daripada"],["عِندِ","daripada"],["ٱللَّهِ","Allah"],["مُصَدِّقٌۭ","mengesahkan"],["لِّمَا","apa (ada)"],["مَعَهُمْ","bersama mereka"],["وَكَانُوا۟","padahal mereka dulu"],["مِن","daripada"],["قَبْلُ","sebelum"],["يَسْتَفْتِحُونَ","(itu), berdoa untuk kemenangan"],["عَلَى","atas"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","tidak beriman"],["فَلَمَّا","kemudian apabila"],["جَآءَهُم","datang kepada mereka"],["مَّا","apa"],["عَرَفُوا۟","mereka mengenali"],["كَفَرُوا۟","mereka kafir"],["بِهِۦ ۚ","di dalamnya"],["فَلَعْنَةُ","Maka (kutukan) itu"],["ٱللَّهِ","(milik) Allah"],["عَلَى","(berada) di atas"],["ٱلْكَـٰفِرِينَ","orang kafir"]]],"97":["(Alangkah buruknya perbuatan mereka menjual) (diri mereka sendiri) maksudnya bagian pahala mereka. 'Ma' pada kata-kata 'bi'samaa' adalah kata 'nakirah' atau 'tidak tentu' (indefinit) dan berarti 'sesuatu', merupakan 'tamyiz' bagi pelaku kata kerja 'bi'sa' yang dikhususkan untuk celaan. (bahwa mereka kafir) artinya dengan kekafiran mereka (terhadap apa yang diturunkan Allah) berupa Alquran (disebabkan kedengkian) berfungsi sebagai 'maf`ul liajlih' menunjukkan motif bagi kekafiran mereka itu. (bahwa Allah menurunkan) ada yang membaca 'yunzila' dan ada pula 'yunazzila' (karunia-Nya) maksudnya wahyu (kepada siapa yang dikehendaki-Nya) untuk menjadi rasul (di antara hamba-hamba-Nya. Karena itu mereka kembali) (dengan kemurkaan) dari Allah disebabkan kekafiran mereka terhadap wahyu yang diturunkan itu. Celaan ini menyatakan betapa besarnya kesalahan yang mereka perbuat (di atas kemurkaan) artinya yang bertimpa-timpa yakni setelah kemurkaan yang selayaknya mereka terima sebelum itu, dengan menyia-nyiakan kitab Taurat serta menolak Nabi Isa. (Dan bagi orang-orang kafir disediakan siksaan yang menghinakan).",[["بِئْسَمَا","Jahat (ialah) itu"],["ٱشْتَرَوْا۟","(untuk) yang telah mereka jual"],["بِهِۦٓ","dengan"],["أَنفُسَهُمْ","diri mereka"],["أَن","bahawa"],["يَكْفُرُوا۟","mereka tidak beriman"],["بِمَآ","pada apa"],["أَنزَلَ","telah mendedahkan"],["ٱللَّهُ","Allah"],["بَغْيًا","berdendam"],["أَن","bahawa"],["يُنَزِّلَ","menghantar turun"],["ٱللَّهُ","Allah"],["مِن","daripada"],["فَضْلِهِۦ","RahmatNya"],["عَلَىٰ","pada"],["مَن","yang"],["يَشَآءُ","Dia kehendaki"],["مِنْ","daripada"],["عِبَادِهِۦ ۖ","hambaNya"],["فَبَآءُو","Maka mereka telah menarik (pada diri mereka sendiri)"],["بِغَضَبٍ","kemarahan"],["عَلَىٰ","ke atas"],["غَضَبٍۢ ۚ","kemarahan"],["وَلِلْكَـٰفِرِينَ","Dan bagi orang-orang kafir"],["عَذَابٌۭ","(ialah) azab"],["مُّهِينٌۭ","memalukan"]]],"98":["(Dan apabila dikatakan kepada mereka, \"Berimanlah kamu kepada apa yang diturunkan Allah!\") yakni Alquran dan lain-lain (Mereka berkata, \"Kami beriman kepada apa yang diturunkan kepada kami.\") yakni Taurat. Maka firman Allah Taala, (Sedangkan mereka kafir) 'wau' di sini menunjukkan 'hal' sehingga berarti 'sedangkan' (terhadap yang turun di belakangnya) atau selain dari itu seperti Alquran (padahal Alquran itulah yang hak) kalimat ini menjadi 'hal' (membenarkan) menjadi 'hal' yang kedua yang memperkuat (apa yang ada pada mereka. Katakanlah,) kepada mereka (\"Kenapa kamu bunuh) (nabi-nabi Allah dulu, jika kamu benar-benar beriman?\") pada Taurat, di mana padanya terdapat larangan membunuh mereka. Pertanyaan ini ditujukan kepada orang-orang Yahudi yang ada di masa nabi kita mengenai perbuatan nenek moyang mereka yang nyata-nyata mereka setujui.",[["وَإِذَا","Dan apabila"],["قِيلَ","dikatakan"],["لَهُمْ","kepada mereka"],["ءَامِنُوا۟","Percayalah"],["بِمَآ","pada apa"],["أَنزَلَ","telah mendedahkan"],["ٱللَّهُ","Allah"],["قَالُوا۟","mereka berkata"],["نُؤْمِنُ","Kami beriman"],["بِمَآ","pada apa"],["أُنزِلَ","telah didedahkan"],["عَلَيْنَا","kepada kami"],["وَيَكْفُرُونَ","Dan mereka kafir"],["بِمَا","pada apa"],["وَرَآءَهُۥ","(adalah) selainnya"],["وَهُوَ","semasa itu"],["ٱلْحَقُّ","(adalah) kebenaran"],["مُصَدِّقًۭا","mengesahkan"],["لِّمَا","apa"],["مَعَهُمْ ۗ","(ada) bersama mereka"],["قُلْ","Katakanlah"],["فَلِمَ","Lalu kenapa"],["تَقْتُلُونَ","(adakah) kamu membunuh"],["أَنۢبِيَآءَ","(para) Nabi"],["ٱللَّهِ","(milik) Allah"],["مِن","daripada"],["قَبْلُ","sebelum"],["إِن","jika"],["كُنتُم","kamu dahulu"],["مُّؤْمِنِينَ","orang yang beriman"]]],"99":["(Dan sesungguhnya telah datang kepada kamu sekalian Musa dengan membawa bukti-bukti kebenaran) maksudnya mukjizat seperti tongkat, tangan dan terbelahnya lautan (kemudian kamu ambil anak sapi) sebagai sembahan (sesudahnya) maksudnya sesudah kepergiannya ke mikat (bahkan kamu adalah orang-orang yang aniaya.) Karena telah menjadikan anak sapi sebagai sembahan.",[["۞ وَلَقَدْ","Dan sesungguhnya"],["جَآءَكُم","datang kepada kamu"],["مُّوسَىٰ","Musa"],["بِٱلْبَيِّنَـٰتِ","dengan tanda-tanda yang jelas"],["ثُمَّ","kemudian"],["ٱتَّخَذْتُمُ","kamu ambil"],["ٱلْعِجْلَ","anak lembu itu"],["مِنۢ","daripada"],["بَعْدِهِۦ","selepas dia"],["وَأَنتُمْ","dan kamu"],["ظَـٰلِمُونَ","(adalah) orang-orang yang zalim"]]],"100":["(Dan ketika Kami mengambil ikrar darimu) untuk mengamalkan apa yang terdapat dalam Taurat (dan) sungguh (Kami angkat bukit di atasmu) maksudnya bukit Sinai, yakni untuk dijatuhkan di atasmu karena kamu menolak untuk berikrar itu, seraya Kami berfirman, (\"Peganglah apa yang Kami berikan padamu) maksudnya taatilah dengan serius dan bersungguh-sungguh (dan dengarkanlah!\") Apa yang akan dititahkan kepadamu dengan patuh (Mereka menjawab, \"Kami dengar) firman-Mu (tetapi tak hendak kami patuhi.\") perintah-Mu itu (dan diminumkan ke dalam hati mereka anak sapi) artinya diresapkan ke dalam hati mereka itu kecintaan menyembah anak sapi tak ubah bagai meresapnya minuman (karena kekafiran mereka. Katakanlah) kepada mereka, (\"Teramat jahatlah apa) maksudnya sesuatu (yang diperintahkan oleh keimananmu) terhadap Taurat itu, yaitu pemujaan anak sapi (jika kamu benar-benar beriman.\") kepadanya sebagai pengakuanmu itu! Maksud ayat, sebenarnya kamu tidak beriman, karena beriman yang sesungguhnya tidak mungkin menyuruh orang untuk menyembah anak sapi. Yang diceritakan di sini nenek moyang mereka, tetapi yang dituju ialah mereka sendiri seolah-olah Allah berfirman, \"Demikian pula halnya kamu tidak beriman pada Taurat, karena kamu mendustakan Muhammad, padahal keimanan pada kitab suci itu tak mungkin akan berakibat mendustakannya!\"",[["وَإِذْ","Dan apabila"],["أَخَذْنَا","Kami ambil"],["مِيثَـٰقَكُمْ","perjanjian kamu"],["وَرَفَعْنَا","dan Kami bangkitkan"],["فَوْقَكُمُ","atas kamu"],["ٱلطُّورَ","gunung itu"],["خُذُوا۟","tahan"],["مَآ","apa"],["ءَاتَيْنَـٰكُم","Kami memberi kamu"],["بِقُوَّةٍۢ","dengan ketegasan"],["وَٱسْمَعُوا۟ ۖ","dan dengar"],["قَالُوا۟","Mereka berkata"],["سَمِعْنَا","Kami dengar"],["وَعَصَيْنَا","dan kami ingkar"],["وَأُشْرِبُوا۟","Dan mereka diberi minum"],["فِى","dalam"],["قُلُوبِهِمُ","hati mereka"],["ٱلْعِجْلَ","(cinta) anak lembu"],["بِكُفْرِهِمْ ۚ","kerana kekufuran mereka"],["قُلْ","Katakanlah"],["بِئْسَمَا","Jahat (ialah) itu"],["يَأْمُرُكُم","menyuruh kamu (melakukannya)."],["بِهِۦٓ","dengan"],["إِيمَـٰنُكُمْ","iman kamu"],["إِن","jika"],["كُنتُم","kamu"],["مُّؤْمِنِينَ","orang yang beriman"]]],"101":["(Katakanlah) kepada mereka, (\"Jika kampung akhirat itu untukmu) maksudnya surga (khusus di sisi Allah) hanya untuk kamu (bukan untuk orang lain) seperti pengakuanmu (maka inginilah kematian jika kamu memang benar!\") Dalam mengingini kematian itu bergantung dua syarat dengan ketentuan; yang pertama dikaitkan pada yang kedua, maksudnya, jika pengakuanmu benar bahwa surga itu hanya milikmu khusus, sedangkan menurut kebiasaan, seseorang ingin segera menemukan miliknya itu dan jalan untuk mendapatkan tiada lain hanya kematian, maka inginilah segera kematian itu olehmu!",[["قُلْ","Katakanlah"],["إِن","Jika"],["كَانَتْ","ialah"],["لَكُمُ","bagi kamu"],["ٱلدَّارُ","rumah itu"],["ٱلْـَٔاخِرَةُ","(dari) Akhirat"],["عِندَ","dengan"],["ٱللَّهِ","Allah"],["خَالِصَةًۭ","secara eksklusif"],["مِّن","daripada"],["دُونِ","tidak termasuk"],["ٱلنَّاسِ","umat manusia"],["فَتَمَنَّوُا۟","maka berhajat"],["ٱلْمَوْتَ","(untuk) kematian"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","jujur"]]],"102":["(Dan mereka sekali-kali tak akan menginginkan kematian itu disebabkan kesalahan-kesalahan yang telah diperbuat oleh tangan mereka) berupa kekafiran kepada nabi sebagai akibat dari mendustakannya (dan Allah Maha Mengetahui terhadap orang-orang yang aniaya) yaitu orang-orang yang kafir, karenanya Allah pasti akan membalas mereka.",[["وَلَن","Dan tidak pernah (akan)"],["يَتَمَنَّوْهُ","mereka inginkannya"],["أَبَدًۢا","pernah"],["بِمَا","kerana"],["قَدَّمَتْ","(apa yang) dihantar ke hadapan"],["أَيْدِيهِمْ ۗ","tangan mereka"],["وَٱللَّهُ","Dan Allah"],["عَلِيمٌۢ","Maha Mengetahui"],["بِٱلظَّـٰلِمِينَ","daripada orang-orang yang zalim"]]],"103":["(Dan demi sesungguhnya, akan kamu jumpai mereka itu) 'lam' menunjukkan sumpah (setamak-tamak manusia atas kehidupan dunia dan) lebih tamak lagi (dari orang-orang musyrik) yakni yang mengingkari hari berbangkit. Mereka tahu bahwa tempat kediaman mereka itu neraka; berbeda halnya dengan orang-orang musyrik yang mengingkari adanya hari akhirat itu. (Masing-masing mereka menginginkan) atau mengharapkan (agar diberi umur seribu tahun) 'lau' mashdariyah sama artinya dengan 'an' atau 'agar' dan dengan 'shilah-nya' ditakwilkan sebagai 'mashdar' atau 'kata benda', menjadi 'maf`ul bih' atau 'obyek penderita' dari 'yawaddu'. (Dan tidaklah dia) maksudnya masing-masing dari mereka (akan menjauhkannya) menyelamatkan dirinya (dari siksa) maksudnya neraka (karena ia diberi umur panjang itu). 'An' bersama shilahnya ini menjadi 'fa`il' atau 'pelaku' dari 'muzahzihihi'. (Dan Allah Maha Melihat akan apa yang mereka kerjakan) karena itu Allah akan membalasnya. Ada yang membaca dengan ya dan ada pula dengan ta. Ibnu Shuriya bertanya kepada Nabi saw. atau Umar, \"Siapakah di antara malaikat yang menyampaikan wahyu?\" Jawabnya, 'Jibril.' Kata Ibnu Shuriya, \"Dia musuh kami yang selalu mendatangkan siksa atau kesengsaraan. Kalau saja Mikail, tentu kami akan beriman, karena dia yang membawa kemakmuran dan kedamaian.\" Lalu turunlah ayat berikutnya,",[["وَلَتَجِدَنَّهُمْ","Dan pasti kamu akan menemui mereka"],["أَحْرَصَ","(yang) paling tamak"],["ٱلنَّاسِ","(dari) manusia"],["عَلَىٰ","bagi"],["حَيَوٰةٍۢ","kehidupan"],["وَمِنَ","dan (lebih tamak) daripada"],["ٱلَّذِينَ","orang yang"],["أَشْرَكُوا۟ ۚ","mempersekutukan [d] (dengan Allah)"],["يَوَدُّ","suka"],["أَحَدُهُمْ","(setiap) seorang daripada mereka"],["لَوْ","jika"],["يُعَمَّرُ","dia boleh diberikan kehidupan"],["أَلْفَ","(dari) seribu"],["سَنَةٍۢ","tahun"],["وَمَا","Tetapi tidak"],["هُوَ","ia"],["بِمُزَحْزِحِهِۦ","(akan) mengeluarkannya"],["مِنَ","daripada"],["ٱلْعَذَابِ","azab"],["أَن","bahawa"],["يُعَمَّرَ ۗ","dia harus diberikan kehidupan"],["وَٱللَّهُ","Dan Allah"],["بَصِيرٌۢ","(ialah) Maha Melihat"],["بِمَا","tentang apa"],["يَعْمَلُونَ","mereka lakukan"]]],"104":["(Katakanlah) kepada mereka, (\"Barang siapa yang menjadi musuh Jibril) maka silakan ia binasa dengan kebenciannya itu! (Maka sesungguhnya Jibril itu menurunkannya) maksudnya Alquran (ke dalam hatimu dengan seizin) atau perintah (Allah, membenarkan apa-apa yang berada di hadapannya) yaitu kitab-kitab suci yang turun sebelumnya (dan menjadi petunjuk) dari kesesatan (serta berita gembira) berupa surga (bagi orang-orang yang beriman).",[["قُلْ","Katakanlah"],["مَن","Siapa pun"],["كَانَ","ialah"],["عَدُوًّۭا","seorang musuh"],["لِّجِبْرِيلَ","kepada Jibril"],["فَإِنَّهُۥ","maka sesungguhnya dia"],["نَزَّلَهُۥ","menurunkannya"],["عَلَىٰ","pada"],["قَلْبِكَ","hati kamu"],["بِإِذْنِ","dengan izin (yang)"],["ٱللَّهِ","(milik) Allah"],["مُصَدِّقًۭا","mengesahkan"],["لِّمَا","apa"],["بَيْنَ","(adalah)"],["يَدَيْهِ","sebelum itu"],["وَهُدًۭى","dan hidayah"],["وَبُشْرَىٰ","dan berita gembira"],["لِلْمُؤْمِنِينَ","untuk orang yang beriman"]]],"105":["(Barang siapa yang menjadi musuh Allah, malaikat-malaikat-Nya, rasul-rasul-Nya dan Jibril) ada yang membaca Jibriil ada pula yang membaca Jabriil atau Jabrail (dan Mikail) diathaf atau dihubungkan kepada malaikat dari jenis mengathafkan yang khas kepada yang umum. Ada pula yang membaca Mikail yaitu dengan hamzah serta ya dan ada pula Mikail dengan tambahan hamzah saja, (maka sesungguhnya Allah menjadi musuh bagi orang-orang yang kafir\"). Orang itu ditempatkan pada suatu posisi untuk menyatakan keadaannya.",[["مَن","Siapa pun"],["كَانَ","ialah"],["عَدُوًّۭا","seorang musuh"],["لِّلَّهِ","(kepada) Allah"],["وَمَلَـٰٓئِكَتِهِۦ","dan MalaikatNya"],["وَرُسُلِهِۦ","dan Rasul-rasulNya"],["وَجِبْرِيلَ","dan Jibril"],["وَمِيكَىٰلَ","dan Meekael"],["فَإِنَّ","maka sesungguhnya"],["ٱللَّهَ","Allah"],["عَدُوٌّۭ","(adalah) musuh"],["لِّلْكَـٰفِرِينَ","kepada orang-orang kafir"]]],"106":["(Dan sungguh, telah kami turunkan kepadamu) hai Muhammad (ayat-ayat yang jelas) atau terang, menjadi 'hal' sebagai sanggahan terhadap ucapan Ibnu Shuriya yang mengatakan kepada Nabi saw., \"Kamu datang kepada kami tanpa membawa sesuatu apa pun!\" (Dan tak ada yang ingkar kepadanya kecuali orang-orang yang fasik)",[["وَلَقَدْ","Dan sesungguhnya"],["أَنزَلْنَآ","Kami mendedahkan"],["إِلَيْكَ","kepada kamu"],["ءَايَـٰتٍۭ","ayat-ayat"],["بَيِّنَـٰتٍۢ ۖ","yang nyata"],["وَمَا","dan bukan"],["يَكْفُرُ","tidak beriman"],["بِهَآ","dalam diri mereka"],["إِلَّا","kecuali"],["ٱلْفَـٰسِقُونَ","yang durhaka"]]],"107":["(Patutkah) mereka ingkar kepadanya (dan setiap mereka menjanjikan) kepada Allah (suatu janji) akan beriman kepada nabi jika telah dibangkitkan atau menjanjikan kepada nabi tidak akan membantu orang-orang yang musyrik untuk menentangnya (melemparkannya) yakni menjauhkannya (segolongan di antara mereka) yaitu dengan cara melanggarnya. Kalimat ini merupakan jawab dari 'kullamaa' atau setiap dan yang menjadi pertanyaan serta sanggahan (bahkan) lebih dari itu lagi (sebagian besar dari mereka tidak beriman).",[["أَوَكُلَّمَا","Dan adakah (bukan itu) apabila-apabila masa"],["عَـٰهَدُوا۟","mereka ambil"],["عَهْدًۭا","sebuah perjanjian"],["نَّبَذَهُۥ","membuangnya"],["فَرِيقٌۭ","sebuah parti"],["مِّنْهُم ۚ","daripada mereka"],["بَلْ","Bahkan"],["أَكْثَرُهُمْ","kebanyakan mereka"],["لَا","jangan"],["يُؤْمِنُونَ","beriman"]]],"108":["(Dan tatkala datang kepada mereka seorang rasul dari sisi Allah) yakni Muhammad saw. (yang membenarkan kitab yang ada pada mereka, sebagian dari orang-orang yang diberi kitab melemparkan kitab Allah) yakni Taurat (ke belakang punggung mereka) artinya mereka tidak mau mengamalkan isinya berupa keimanan kepada rasul dan lain-lain (seolah-olah mereka tidak mengetahui) akan isinya bahwa beliau adalah nabi yang sebenarnya atau bahwa Taurat itu adalah kitab Allah.",[["وَلَمَّا","Dan apabila"],["جَآءَهُمْ","datang kepada mereka"],["رَسُولٌۭ","seorang Rasul"],["مِّنْ","(daripada)"],["عِندِ","daripada"],["ٱللَّهِ","Allah"],["مُصَدِّقٌۭ","mengesahkan"],["لِّمَا","apa"],["مَعَهُمْ","(ada) bersama mereka"],["نَبَذَ","dibuang"],["فَرِيقٌۭ","sebuah parti"],["مِّنَ","daripada"],["ٱلَّذِينَ","orang yang"],["أُوتُوا۟","telah diberikan"],["ٱلْكِتَـٰبَ","Kitab"],["كِتَـٰبَ","(the) Buku"],["ٱللَّهِ","(milik) Allah"],["وَرَآءَ","belakang"],["ظُهُورِهِمْ","belakang mereka"],["كَأَنَّهُمْ","seolah-olah mereka"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"]]],"109":["(Dan mereka mengikuti) diathafkan pada 'nabadza' (apa yang dibaca) dulu (oleh setan-setan pada) masa (kerajaan Sulaiman) berupa buku-buku sihir yang mereka pendam di bawah singgasananya ketika kerajaannya runtuh. Atau mungkin juga setan-setan itu mencari dengar lalu mencampurkan ke buku-buku itu kebohongan-kebohongan dan memberikannya kepada tukang-tukang tenung yang membukukannya sehingga tersebar berita bahwa jin mengajarkan hal-hal gaib. Sulaiman pun mengumpulkan buku-buku itu lalu menguburkannya. Tatkala ia mangkat, setan-setan pun menunjukkannya kepada manusia dan ketika mereka bongkar ternyata di dalamnya ada ilmu sihir. Kata mereka, \"Kerajaan kamu berdirinya adalah dengan ini!\" Lalu mereka pelajari ilmu sihir itu dan mereka tolak buku-buku nabi-nabi mereka. Ketika orang-orang Yahudi mengatakan, \"Lihat itu Muhammad, disebutkannya Sulaiman itu seorang nabi, padahal ia tidak lebih dari seorang tukang sihir\", maka Allah pun berfirman untuk membuktikan kebenaran Sulaiman dan menyangkal orang-orang Yahudi itu, (padahal Sulaiman tidaklah kafir) maksudnya ia tidak melakukan sihir, sebab sihir adalah perbuatan kafir (hanya) ada yang membaca 'lakinna' dan ada yang membaca 'lakin' (setan-setanlah yang kafir. Mereka mengajarkan sihir kepada manusia). Kalimat ini menjadi hal bagi kata ganti yang terdapat pada 'kafaruu' (dan) mengajarkan pula kepada mereka (apa yang diturunkan kepada dua malaikat) artinya ilmu sihir yang diilhamkan kepada mereka. Ada pula yang membaca 'al-malikain' dengan lam berbaris bawah sehingga berarti dua orang raja, yaitu yang berada (di Babilon) suatu negeri di tanah subur Irak. (Harut dan Marut) merupakan 'badal' atau nama dan kata ganti dari kedua malaikat itu, atau athaf bayan, artinya hubungan yang memberi penjelasan. Menurut Ibnu Abbas, kedua mereka itu adalah tukang sihir yang mengajarkan ilmu sihir dan ada pula yang mengatakan bahwa mereka adalah dua orang malaikat yang sengaja diturunkan Allah untuk menyebarkannya sebagai ujian dari Allah terhadap umat manusia. (Sedangkan keduanya tidaklah mengajarkan kepada) 'min' merupakan tambahan (seorang pun sebelum mengatakan) atau menyampaikan nasihat lebih dahulu (\"Sesungguhnya kami ini hanya cobaan) ujian dari Allah terhadap manusia dengan mengajarkannya, siapa yang mempelajarinya, ia jatuh kafir dan siapa yang meninggalkannya ia mukmin, (sebab itu janganlah kamu kafir!\") Jika ia masih mendesak untuk mempelajarinya barulah mereka mengajarkannya. (Maka mereka mempelajari dari kedua malaikat itu apa yang dapat menceraikan antara seorang laki-laki dengan istrinya) misalnya dengan membangkitkan marah dan kebencian satu pihak terhadap lainnya. (Dan tidaklah mereka) yakni ahli-ahli sihir itu (dapat memberi mudarat dengannya) maksudnya dengan ilmu sihir itu (dari) 'min' di sini hanya sebagai tambahan (kepada seorang pun kecuali dengan izin Allah) atau kehendak-Nya (Dan mereka pelajari apa yang memberi mudarat kepada mereka), yakni di akhirat (dan yang tidak memberi manfaat) yakni sihir. (Dan sesungguhnya) 'lam' menunjukkan sumpah (mereka sebenarnya tahu) yakni orang-orang Yahudi itu sebenarnya yakin (bahwa barang siapa) 'lam' merupakan lam ibtida yang menghubungkan dengan kalimat sebelumnya, sedangkan 'man' isim maushul (yang menukarnya) atau menggantinya (sihir) dengan Kitabullah, (tiadalah baginya bagian di akhirat) atau keberuntungan dalam surga, (dan amat buruklah sesuatu) maksudnya perbuatan mereka (menjual) menukarkan (diri mereka dengannya) yakni menjual kebahagiaannya di akhirat dengan mempelajari sihir karena telah pasti akan menjerumuskan mereka ke dalam neraka, (seandainya mereka menyadarinya) jika mereka benar-benar tahu atau menyadari hakikat siksaan yang akan mereka jalani di akhirat kelak, niscaya mereka tidak mau mempelajarinya.",[["وَٱتَّبَعُوا۟","Dan mereka mengikut"],["مَا","apa"],["تَتْلُوا۟","membaca (d)"],["ٱلشَّيَـٰطِينُ","syaitan"],["عَلَىٰ","atas"],["مُلْكِ","(kerajaan)."],["سُلَيْمَـٰنَ ۖ","(dari) Sulaiman"],["وَمَا","Dan tidak"],["كَفَرَ","kufur"],["سُلَيْمَـٰنُ","Sulaiman"],["وَلَـٰكِنَّ","[dan] tetapi"],["ٱلشَّيَـٰطِينَ","syaitan"],["كَفَرُوا۟","kufur"],["يُعَلِّمُونَ","mereka mengajar"],["ٱلنَّاسَ","manusia"],["ٱلسِّحْرَ","[the] sihir"],["وَمَآ","dan apa"],["أُنزِلَ","telah diturunkan"],["عَلَى","kepada"],["ٱلْمَلَكَيْنِ","dua malaikat itu"],["بِبَابِلَ","di Babylon"],["هَـٰرُوتَ","Harut"],["وَمَـٰرُوتَ ۚ","dan Marut"],["وَمَا","Dan tidak"],["يُعَلِّمَانِ","mereka berdua mengajar"],["مِنْ","sebarang"],["أَحَدٍ","satu"],["حَتَّىٰ","melainkan"],["يَقُولَآ","mereka [berdua] berkata"],["إِنَّمَا","Hanya"],["نَحْنُ","kita"],["فِتْنَةٌۭ","(adalah) percubaan"],["فَلَا","jadi (jangan)"],["تَكْفُرْ ۖ","kufur"],["فَيَتَعَلَّمُونَ","Tetapi mereka belajar"],["مِنْهُمَا","daripada mereka berdua"],["مَا","apa"],["يُفَرِّقُونَ","[mereka] menyebabkan perpisahan"],["بِهِۦ","dengannya"],["بَيْنَ","antara"],["ٱلْمَرْءِ","lelaki itu"],["وَزَوْجِهِۦ ۚ","dan pasangannya"],["وَمَا","Dan tidak"],["هُم","mereka (boleh)"],["بِضَآرِّينَ","sama sekali [jadilah mereka yang] membahayakan"],["بِهِۦ","dengannya"],["مِنْ","sebarang"],["أَحَدٍ","satu"],["إِلَّا","kecuali"],["بِإِذْنِ","dengan izin"],["ٱللَّهِ ۚ","(milik) Allah"],["وَيَتَعَلَّمُونَ","Dan mereka belajar"],["مَا","apa"],["يَضُرُّهُمْ","membahayakan mereka"],["وَلَا","dan bukan"],["يَنفَعُهُمْ ۚ","menguntungkan mereka"],["وَلَقَدْ","Dan sesungguhnya"],["عَلِمُوا۟","mereka tahu"],["لَمَنِ","bahawa sesiapa sahaja"],["ٱشْتَرَىٰهُ","membelinya"],["مَا","tidak"],["لَهُۥ","baginya"],["فِى","dalam"],["ٱلْـَٔاخِرَةِ","akhirat"],["مِنْ","sebarang"],["خَلَـٰقٍۢ ۚ","kongsi"],["وَلَبِئْسَ","Dan pastinya jahat"],["مَا","(ialah) apa"],["شَرَوْا۟","mereka menjual"],["بِهِۦٓ","dengannya"],["أَنفُسَهُمْ ۚ","diri mereka"],["لَوْ","jika"],["كَانُوا۟","mereka adalah"],["يَعْلَمُونَ","(untuk) mengetahui"]]],"110":["(Dan seandainya mereka) orang-orang Yahudi (beriman) terhadap Nabi dan Alquran (dan menjaga diri mereka) dari siksa Allah dengan meninggalkan maksiat, seperti sihir. Jawaban dari 'lau' ini dibuang. Atau tentulah mereka akan diberi pahala. Hal ini ditunjukkan oleh (maka sesungguhnya pahala) 'matsuubatun' menjadi mubtada, sedangkan 'lam' menunjukkan sumpah (di sisi Allah itu lebih baik) 'khairun' menjadi khabar, artinya 'lebih baik' yakni lebih baik dari hasil penjualan diri mereka itu (seandainya mereka mengetahuinya) seandainya mereka tahu bahwa pahala itu lebih baik, tentulah mereka tak akan mementingkan yang lain darinya.",[["وَلَوْ","Dan jika"],["أَنَّهُمْ","[bahawa] mereka"],["ءَامَنُوا۟","(telah) beriman"],["وَٱتَّقَوْا۟","dan takut (kepada Allah)"],["لَمَثُوبَةٌۭ","sesungguhnya pahalanya"],["مِّنْ","(daripada)"],["عِندِ","daripada"],["ٱللَّهِ","Allah"],["خَيْرٌۭ ۖ","(akan menjadi) lebih baik"],["لَّوْ","jika"],["كَانُوا۟","mereka adalah"],["يَعْلَمُونَ","(untuk) mengetahui"]]],"111":["(Hai orang-orang yang beriman, janganlah kamu katakan) kepada Nabi (raa`inaa) artinya perhatikanlah kami; 'raa'inaa' diambil dari kata 'muraa`ah', tetapi orang-orang Yahudi biasa mengatakan 'raa`unah' yang dalam bahasa mereka berarti 'teramat bodoh' sebagai ejekan kepada Nabi, maka orang-orang mukmin dilarang mengucapkan kata-kata itu, (dan katakanlah) yakni sebagai gantinya, (unzhurnaa) artinya lihatlah kami; (dan dengarlah olehmu) apa-apa yang dititahkan dengan kesediaan untuk mematuhinya (dan bagi orang-orang kafir disediakan siksaan pedih) yang menyakitkan sekali, yaitu neraka.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوا۟","beriman"],["لَا","Jangan"],["تَقُولُوا۟","berkata"],["رَٰعِنَا","Raina"],["وَقُولُوا۟","dan katakan"],["ٱنظُرْنَا","Unzurna"],["وَٱسْمَعُوا۟ ۗ","dan dengar"],["وَلِلْكَـٰفِرِينَ","Dan bagi orang-orang kafir"],["عَذَابٌ","(ialah) azab"],["أَلِيمٌۭ","yang pedih"]]],"112":["(Orang-orang kafir dan golongan Ahli Kitab dan orang-orang musyrik tidak menginginkan) orang-orang musyrik di sini ialah dari kalangan Arab, dihubungkan kepada Ahli Kitab, sedangkan 'min' atau 'dari' untuk penjelasan (diturunkannya kebaikan kepadamu) 'min' di sini hanya sebagai tambahan; sedangkan 'kebaikan' maksudnya ialah wahyu, (dari Tuhan) disebabkan iri hati atau dengki kepadamu. (Sedangkan Allah menentukan rahmat-Nya) atau kenabian-Nya (kepada siapa yang dikehendaki-Nya; dan Allah mempunyai karunia yang maha besar).",[["مَّا","Jangan"],["يَوَدُّ","suka"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["مِنْ","daripada"],["أَهْلِ","(the) Rakyat"],["ٱلْكِتَـٰبِ","Kitab"],["وَلَا","dan bukan"],["ٱلْمُشْرِكِينَ","orang-orang yang mempersekutukan (Allah)"],["أَن","bahawa"],["يُنَزَّلَ","(sepatutnya) diturunkan"],["عَلَيْكُم","kepada kamu"],["مِّنْ","sebarang"],["خَيْرٍۢ","kebaikan"],["مِّن","daripada"],["رَّبِّكُمْ ۗ","Tuhanmu"],["وَٱللَّهُ","Dan Allah"],["يَخْتَصُّ","memilih"],["بِرَحْمَتِهِۦ","kerana RahmatNya"],["مَن","yang"],["يَشَآءُ ۚ","Dia kehendaki"],["وَٱللَّهُ","Dan Allah"],["ذُو","(ialah) Pemilik"],["ٱلْفَضْلِ","(dari) [the] Bounty"],["ٱلْعَظِيمِ","[yang] Hebat"]]],"113":["Tatkala orang-orang kafir mengecam tentang nasakh/penghapusan atau pergantian hukum dan menuduh bahwa Muhammad menyuruh sahabat-sahabatnya untuk mengerjakan sesuatu pada hari ini lalu melarangnya esok, maka turunlah ayat, (Apa saja) disebut 'syarthiyah' yang membutuhkan jawaban (ayat yang Kami hapus) baik hukumnya itu pada mulanya turun bersama lafalnya atau tidak dan menurut satu qiraat 'nunsikh', artinya Kami titah kamu atau Jibril untuk menghapusnya (atau Kami tangguhkan) Kami undurkan sehingga hukumnya tidak turun dan bacaannya Kami tangguhkan di Lohmahfuz. Menurut satu qiraat tanpa hamzah, berasal dari kata-kata 'nisyaan' artinya 'lupa', sehingga artinya ialah Kami kikis atau hapus dari dalam kalbumu sehingga kamu melupakannya. Jawab syaratnya ialah (Kami datangkan yang lebih baik daripadanya) artinya lebih menguntungkan bagi hamba, baik dalam kemudahannya maupun dalam besar pahalanya (atau yang sebanding dengannya) dalam beban yang harus dipikul atau dalam ganjarannya. (Tidakkah kamu ketahui bahwa sesungguhnya Allah Maha Kuasa atas segala sesuatu?) Termasuk dalam kekuasaan-Nya itu nasakh, yaitu menghapus hukum dan mengubahnya, dan mengenai pertanyaan di sini maksudnya ialah untuk mengukuhkan.",[["۞ مَا","Apa"],["نَنسَخْ","Kita batalkan"],["مِنْ","(daripada)"],["ءَايَةٍ","satu tanda"],["أَوْ","atau"],["نُنسِهَا","[Kami] menyebabkan ia dilupakan"],["نَأْتِ","Kami bawa"],["بِخَيْرٍۢ","lebih baik"],["مِّنْهَآ","daripadanya"],["أَوْ","atau"],["مِثْلِهَآ ۗ","serupa (dengan)nya"],["أَلَمْ","Jangan"],["تَعْلَمْ","kamu tahu"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["عَلَىٰ","atas"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["قَدِيرٌ","(adalah) Maha Kuasa"]]],"114":["(Tidakkah kamu ketahui bahwa milik Allahlah kerajaan langit dan bumi) sehingga Dia dapat berbuat terhadap keduanya menurut yang dikehendaki-Nya. (Dan tiada bagimu selain Allah) (dari) hanya sebagai tambahan (seorang wali) seorang pelindung yang akan melindungimu (dan tidak pula seorang pembela) yang akan menghindarkan siksaan jika datang menimpa.",[["أَلَمْ","Jangan"],["تَعْلَمْ","kamu tahu"],["أَنَّ","bahawa"],["ٱللَّهَ","Allah"],["لَهُۥ","untuk Dia"],["مُلْكُ","(ialah) Kerajaan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۗ","dan bumi"],["وَمَا","Dan tidak"],["لَكُم","(adalah) untuk kamu"],["مِّن","daripada"],["دُونِ","selain"],["ٱللَّهِ","Allah"],["مِن","sebarang"],["وَلِىٍّۢ","pelindung"],["وَلَا","dan bukan"],["نَصِيرٍ","mana-mana pembantu"]]],"115":["Tatkala warga Mekah meminta kepada Nabi saw. agar kota mereka diperluas dan bukit Shafa dijadikan sebuah bukit emas turunlah, (Atau) apakah (kamu menghendaki untuk meminta kepada Rasulmu seperti yang diminta kepada Musa) maksudnya kaum Nabi Musa telah meminta kepadanya (dulu) seperti kata mereka, \"Perlihatkanlah Allah kepada kami secara nyata!\" Dan lain-lain. (Dan barang siapa yang menukar iman dengan kekafiran) artinya mengambil kekafiran sebagai ganti keimanan disebabkan tidak mau memperhatikan ayat-ayat yang jelas dan lebih memilih yang lainnya (maka sungguh ia telah sesat dari jalan yang benar) 'sawa' asalnya 'wasath', artinya pertengahan.",[["أَمْ","Atau"],["تُرِيدُونَ","(adakah) kamu mahu"],["أَن","bahawa"],["تَسْـَٔلُوا۟","kamu tanya"],["رَسُولَكُمْ","Rasul kamu"],["كَمَا","seperti"],["سُئِلَ","ditanya"],["مُوسَىٰ","Musa"],["مِن","daripada"],["قَبْلُ ۗ","sebelum"],["وَمَن","Dan sesiapa"],["يَتَبَدَّلِ","pertukaran"],["ٱلْكُفْرَ","[yang] tidak beriman"],["بِٱلْإِيمَـٰنِ","dengan iman"],["فَقَدْ","jadi pasti"],["ضَلَّ","dia telah sesat (dari)"],["سَوَآءَ","(the) kesamarataan"],["ٱلسَّبِيلِ","(dari) jalan"]]],"116":["(Sebagian besar Ahli Kitab menginginkan agar) 'lau' atau 'agar' mashdariyah, artinya melebur kalimat sesudahnya menjadi mashdar (mereka dapat mengembalikan kamu pada kekafiran setelah kamu beriman disebabkan kedengkian) 'maf`ul lah' menunjukkan motif dari keinginan mereka itu (dari diri mereka sendiri) maksudnya timbul dan didorong oleh jiwa mereka yang kotor (setelah nyata bagi mereka) dalam Taurat (kebenaran) mengenai diri Nabi. (Maka biarkanlah mereka) tinggalkan (dan berpalinglah) tak usah dilayani mereka itu, (sampai Allah mendatangkan perintah-Nya) tentang mereka dengan menyuruh memerangi mereka. (Sesungguhnya Allah Maha Kuasa atas segala sesuatu).",[["وَدَّ","Wish[ed]"],["كَثِيرٌۭ","ramai"],["مِّنْ","daripada"],["أَهْلِ","(the) Rakyat"],["ٱلْكِتَـٰبِ","Kitab"],["لَوْ","jika"],["يَرُدُّونَكُم","mereka boleh membalikkan kamu"],["مِّنۢ","daripada"],["بَعْدِ","selepas"],["إِيمَـٰنِكُمْ","(mempunyai) iman kamu"],["كُفَّارًا","(kepada) orang-orang kafir"],["حَسَدًۭا","(kerana) cemburu"],["مِّنْ","daripada"],["عِندِ","(daripada)"],["أَنفُسِهِم","diri mereka"],["مِّنۢ","(malah) daripada"],["بَعْدِ","selepas"],["مَا","[apa]"],["تَبَيَّنَ","menjadi jelas"],["لَهُمُ","kepada mereka"],["ٱلْحَقُّ ۖ","kebenaran"],["فَٱعْفُوا۟","Jadi maafkan"],["وَٱصْفَحُوا۟","dan terlepas pandang"],["حَتَّىٰ","sehingga"],["يَأْتِىَ","membawa"],["ٱللَّهُ","Allah"],["بِأَمْرِهِۦٓ ۗ","PerintahNya"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["عَلَىٰ","pada"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["قَدِيرٌۭ","(adalah) Maha Kuasa"]]],"117":["(Dan dirikanlah salat serta bayarkanlah zakat dan apa-apa yang kamu persembahkan buat dirimu berupa kebaikan) artinya ketaatan seperti sedekah dan menghubungkan silaturahmi, (tentulah kamu akan mendapatinya) maksudnya pahalanya (di sisi Allah, sesungguhnya Allah Maha Melihat akan apa-apa yang kamu kerjakan) sehingga kamu akan menerima balasan daripadanya.",[["وَأَقِيمُوا۟","Dan dirikanlah"],["ٱلصَّلَوٰةَ","solat"],["وَءَاتُوا۟","dan memberi"],["ٱلزَّكَوٰةَ ۚ","zakat"],["وَمَا","Dan apa sahaja"],["تُقَدِّمُوا۟","kamu hantar"],["لِأَنفُسِكُم","untuk diri kamu sendiri"],["مِّنْ","daripada"],["خَيْرٍۢ","kebaikan (perbuatan)"],["تَجِدُوهُ","kamu akan menemuinya"],["عِندَ","dengan"],["ٱللَّهِ ۗ","Allah"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["بِمَا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"],["بَصِيرٌۭ","(ialah) Maha Melihat"]]],"118":["(Dan mereka, orang-orang Yahudi dan Kristen, mengatakan, \"Sekali-kali tidak akan masuk surga kecuali orang-orang yang beragama Yahudi atau Kristen.\") Ucapan ini dikeluarkan oleh orang-orang Yahudi Madinah dan Kristen Najran tatkala mereka berbantahan di hadapan Nabi saw. Kata Yahudi, \"Hanya orang Yahudilah yang akan masuk ke dalamnya.\" Orang Kristen menjawab, \"Surga itu tidak akan dimasuki, kecuali oleh orang Kristen.\" (Demikianlah itu) yakni ucapan mereka itu (hanyalah angan-angan mereka saja) artinya keinginan kosong belaka. (Katakanlah) kepada mereka, (Tunjukkanlah bukti kebenaranmu) yaitu hujah atas yang demikian itu (jika kamu orang yang benar) mengenai hal tersebut.",[["وَقَالُوا۟","Dan mereka berkata"],["لَن","tidak pernah"],["يَدْخُلَ","akan masuk"],["ٱلْجَنَّةَ","syurga itu"],["إِلَّا","kecuali"],["مَن","yang"],["كَانَ","ialah"],["هُودًا","(a) Yahudi"],["أَوْ","atau"],["نَصَـٰرَىٰ ۗ","(a) Kristian"],["تِلْكَ","Itu"],["أَمَانِيُّهُمْ ۗ","(ialah) angan-angan mereka"],["قُلْ","Katakanlah"],["هَاتُوا۟","bawa"],["بُرْهَـٰنَكُمْ","bukti kamu"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","[orang-orang yang] benar"]]],"119":["(Tidak demikian) bahkan yang akan masuk surga itu ialah selain mereka (barang siapa yang menyerahkan wajahnya kepada Allah) maksudnya tunduk pada perintah-Nya. Ditekankan menyerahkan 'wajah' atau 'muka' karena merupakan anggota tubuh yang paling mulia, maka anggota tubuh yang lainnya harus lebih tunduk lagi (sedangkan ia berbuat kebaikan) terutama bertauhid, (maka baginya pahala di sisi Tuhannya) artinya sebagai ganjaran amal perbuatannya itu ialah surga. (Tidak ada kekhawatiran terhadap mereka dan tidak pula mereka akan berduka cita) yakni di akhirat kelak.",[["بَلَىٰ","ya"],["مَنْ","sesiapa sahaja"],["أَسْلَمَ","menyerahkan"],["وَجْهَهُۥ","mukanya"],["لِلَّهِ","kepada Allah"],["وَهُوَ","dan dia"],["مُحْسِنٌۭ","(adalah) seorang yang berbuat baik"],["فَلَهُۥٓ","jadi bagi dia"],["أَجْرُهُۥ","(ialah) pahalanya"],["عِندَ","dengan"],["رَبِّهِۦ","Tuhannya"],["وَلَا","Dan tidak"],["خَوْفٌ","bertakwa"],["عَلَيْهِمْ","(akan) pada mereka"],["وَلَا","dan bukan"],["هُمْ","mereka"],["يَحْزَنُونَ","(akan) bersedih"]]],"120":["(Dan orang-orang Yahudi berkata, \"Orang-orang Nasrani tidak mempunyai sesuatu pegangan\") yakni sesuatu yang dapat diakui di samping mereka tidak pula beriman kepada Isa. (Sebaliknya orang-orang Nasrani mengatakan, \"Orang Yahudi tidak mempunyai sesuatu pegangan,\") yang dapat dipercaya dan mereka kafir pula kepada Nabi Musa (padahal mereka) kedua golongan tersebut (sama-sama membaca Alkitab) yang diturunkan kepada mereka. Di dalam kitab suci orang Yahudi terdapat pengukuhan terhadap Nabi Isa dan dalam kitab suci orang Kristen terdapat pengukuhan terhadap Nabi Musa. Kalimat yang belakangan ini menjadi 'hal'. (Demikian pula) maksudnya seperti yang mereka katakan itu (dikatakan oleh orang-orang yang tidak mengetahui) yakni orang-orang musyrik dari golongan Arab dan lainnya (seperti ucapan mereka itu) penjelasan bagi makna 'demikian pula', artinya kepada setiap penganut agama lain, mereka katakan bahwa mereka tidak mempunyai dasar atau pedoman. (Maka Allah akan mengadili di antara mereka pada hari kiamat mengenai apa yang mereka persengketakan itu) yakni tentang urusan agama, sehingga semua pihak yang membenarkannya akan masuk surga dan sebaliknya orang yang menyangkalnya akan masuk neraka.",[["وَقَالَتِ","Dan berkata"],["ٱلْيَهُودُ","orang Yahudi"],["لَيْسَتِ","Tidak"],["ٱلنَّصَـٰرَىٰ","orang Kristian"],["عَلَىٰ","(ada) pada"],["شَىْءٍۢ","sesuatu"],["وَقَالَتِ","dan berkata"],["ٱلنَّصَـٰرَىٰ","orang Kristian"],["لَيْسَتِ","Tidak"],["ٱلْيَهُودُ","orang Yahudi"],["عَلَىٰ","(ada) pada"],["شَىْءٍۢ","sesuatu"],["وَهُمْ","walaupun mereka"],["يَتْلُونَ","mengaji"],["ٱلْكِتَـٰبَ ۗ","Kitab"],["كَذَٰلِكَ","macam tu"],["قَالَ","berkata"],["ٱلَّذِينَ","orang yang"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"],["مِثْلَ","serupa"],["قَوْلِهِمْ ۚ","kata-kata mereka"],["فَٱللَّهُ","[Maka] Allah"],["يَحْكُمُ","akan menilai"],["بَيْنَهُمْ","antara mereka"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ","(dari) Kebangkitan"],["فِيمَا","pada apa"],["كَانُوا۟","mereka adalah"],["فِيهِ","[di dalamnya]"],["يَخْتَلِفُونَ","berbeza"]]],"121":["(Dan siapakah yang melarang menyebut nama Allah dalam mesjid-mesjid-Nya) misalnya salat dan bertasbih (dan berusaha untuk merobohkannya) baik dengan jalan meruntuhkan mesjid itu maupun dengan menggagalkan orang untuk mengunjungi dan memasukinya. Ayat ini turun menceritakan perbuatan orang-orang Romawi yang telah merobohkan Baitulmakdis atau orang-orang musyrik Mekah yang menghalang-halangi Nabi saw. ketika mengunjungi Baitullah pada tahun perjanjian Hudaibiah. (Mereka itu tidak sepatutnya memasukinya kecuali dengan rasa takut). Kalimat ini kalimat berita dengan arti perintah, artinya ancamlah mereka itu dengan jihad, sehingga tidak seorang pun masuk ke dalamnya dengan rasa aman. (Mereka di dunia mendapat kehinaan) atau kenistaan disebabkan terbunuh, ditawan atau membayar upeti (dan di akhirat mereka mendapat siksa yang besar) neraka.",[["وَمَنْ","Dan siapa"],["أَظْلَمُ","(adalah) lebih zalim"],["مِمَّن","daripada (seorang) yang"],["مَّنَعَ","menghalang"],["مَسَـٰجِدَ","(the) masjid"],["ٱللَّهِ","(milik) Allah"],["أَن","kepada"],["يُذْكَرَ","disebut"],["فِيهَا","dalam diri mereka"],["ٱسْمُهُۥ","nama dia"],["وَسَعَىٰ","dan berusaha"],["فِى","bagi"],["خَرَابِهَآ ۚ","kemusnahan mereka"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["مَا","Tidak"],["كَانَ","ia adalah"],["لَهُمْ","bagi mereka"],["أَن","bahawa"],["يَدْخُلُوهَآ","mereka memasukinya"],["إِلَّا","kecuali"],["خَآئِفِينَ ۚ","(seperti) mereka yang ketakutan"],["لَهُمْ","Untuk mereka"],["فِى","dalam"],["ٱلدُّنْيَا","dunia"],["خِزْىٌۭ","(adalah) aib"],["وَلَهُمْ","dan untuk mereka"],["فِى","dalam"],["ٱلْـَٔاخِرَةِ","akhirat"],["عَذَابٌ","(ialah) azab"],["عَظِيمٌۭ","yang besar"]]],"122":["Ketika orang-orang Yahudi mengecam penggantian kiblat atau tentang salat sunah di atas kendaraan selama dalam perjalanan dengan menghadap ke arah yang dituju, turunlah ayat, (Dan milik Allahlah timur dan barat) karena keduanya merupakan ujung dan pangkalnya, (maka ke mana saja kamu menghadap) maksudnya menghadapkan mukamu di waktu salat atas titah-Nya, (maka di sanalah) di arah sanalah (wajah Allah) maksudnya kiblat yang diridai-Nya. (Sesungguhnya Allah Maha Luas) maksudnya kemurahan-Nya meliputi segala sesuatu (lagi Maha Mengetahui) tentang pengaturan makhluk-Nya.",[["وَلِلَّهِ","Dan untuk Allah"],["ٱلْمَشْرِقُ","(ialah) timur"],["وَٱلْمَغْرِبُ ۚ","dan barat"],["فَأَيْنَمَا","jadi di mana sahaja"],["تُوَلُّوا۟","kamu pusing"],["فَثَمَّ","[jadi] di sana"],["وَجْهُ","(adalah) muka"],["ٱللَّهِ ۚ","(milik) Allah"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["وَٰسِعٌ","(adalah) Merangkumi"],["عَلِيمٌۭ","Maha Mengetahui"]]],"123":["(Dan mereka berkata) dengan wau atau tanpa wau, maksudnya orang-orang Yahudi dan Kristen serta orang-orang yang mengakui bahwa malaikat-malaikat itu anak-anak perempuan Allah, ('Allah mempunyai anak.') Allah berfirman, (\"Maha Suci Dia) menyucikan-Nya dari pernyataan tersebut, (bahkan apa-apa yang ada di langit dan di bumi kepunyaan-Nya belaka) baik sebagai hak milik, sebagai makhluk, maupun sebagai hamba. Pemilikan itu bertentangan dengan pengambilan atau mempunyai anak. Di sini dipakai 'maa' artinya 'apa-apa untuk yang tidak berakal' karena 'taghlib', artinya untuk mengambil yang lebih banyak. (semua tunduk kepada-Nya.\") Artinya menaatinya, masing-masing sesuai dengan tujuan diciptakan-Nya. Di sini lebih ditekankan kepada makhluk yang berakal.",[["وَقَالُوا۟","Dan mereka berkata"],["ٱتَّخَذَ","telah mengambil"],["ٱللَّهُ","Allah"],["وَلَدًۭا ۗ","seorang anak lelaki"],["سُبْحَـٰنَهُۥ ۖ","Maha Suci Dia"],["بَل","Bahkan"],["لَّهُۥ","untuk Dia"],["مَا","(ialah) apa"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۖ","dan bumi"],["كُلٌّۭ","Semua"],["لَّهُۥ","kepada-Nya"],["قَـٰنِتُونَ","(adalah) taat dengan rendah hati"]]],"124":["(Penemu langit dan bumi) maksudnya penciptanya tanpa meniru pada contoh-contoh yang lain (dan bila Dia berkehendak) (akan sesuatu perkara) artinya menciptakannya (maka Dia hanya mengucapkan kepadanya, \"Jadilah kamu!\" Lalu jadilah ia) artinya sesuatu itu pun terjadilah. Menurut satu qiraat 'fayakuuna' dengan baris di atas sebagai 'jawaabul amr'.",[["بَدِيعُ","(The) Pemula"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۖ","dan bumi"],["وَإِذَا","Dan apabila"],["قَضَىٰٓ","Dia menetapkan"],["أَمْرًۭا","sesuatu perkara"],["فَإِنَّمَا","[jadi] sahaja"],["يَقُولُ","Dia berkata"],["لَهُۥ","kepadanya"],["كُن","Jadilah"],["فَيَكُونُ","dan ia menjadi"]]],"125":["(Dan berkatalah orang-orang yang tidak mengetahui) yakni kaum kafir Mekah kepada Nabi saw., (\"Mengapa Allah tidak berbicara dengan kami) bahwa kamu adalah Rasul-Nya (atau datang kepada kami suatu tanda) atau bukti yang kami usulkan untuk menunjukkan kebenaranmu?\" (Demikian pulalah) artinya seperti yang mereka ucapkan itu (dikatakan kepada orang-orang yang sebelum mereka) yakni umat-umat yang kafir terhadap nabi mereka masing-masing (seperti ucapan mereka) berupa pembangkangan dan permintaan mukjizat-mukjizat, (hati mereka serupa) yakni dalam kekafiran dan pembangkangan. Ini menjadi hiburan dan bujukan bagi Nabi saw. (Sesungguhnya Kami telah menjelaskan tanda kekuasaan Kami kepada kaum yang yakin) yang mengetahui bahwa ia adalah ayat atau tanda, sehingga mereka beriman. Maka mengusulkan ayat atau tanda-tanda lain merupakan dosa atau kesalahan.",[["وَقَالَ","Dan berkata"],["ٱلَّذِينَ","orang yang"],["لَا","jangan"],["يَعْلَمُونَ","mengetahui"],["لَوْلَا","kenapa tidak"],["يُكَلِّمُنَا","bercakap kepada kita"],["ٱللَّهُ","Allah"],["أَوْ","atau"],["تَأْتِينَآ","datang kepada kita"],["ءَايَةٌۭ ۗ","satu tanda"],["كَذَٰلِكَ","macam tu"],["قَالَ","berkata"],["ٱلَّذِينَ","mereka"],["مِن","daripada"],["قَبْلِهِم","sebelum mereka"],["مِّثْلَ","serupa"],["قَوْلِهِمْ ۘ","kata-kata mereka"],["تَشَـٰبَهَتْ","Menjadi serupa"],["قُلُوبُهُمْ ۗ","hati mereka"],["قَدْ","Sesungguhnya"],["بَيَّنَّا","Kami telah menjelaskan"],["ٱلْـَٔايَـٰتِ","tanda-tanda"],["لِقَوْمٍۢ","untuk orang"],["يُوقِنُونَ","(yang) sungguh-sungguh beriman"]]],"126":["(Sesungguhnya Kami telah mengutusmu) hai Muhammad (dengan kebenaran) maksudnya dengan petunjuk (sebagai pembawa berita gembira) bahwa barang siapa yang memenuhinya, ia akan mendapat surga (dan pembawa peringatan) bahwa barang siapa yang menolaknya akan masuk neraka. (Dan kamu tidak akan dimintai pertanggungjawaban tentang penghuni-penghuni neraka) maksudnya orang-orang kafir. Tidak menjadi soal bagimu jika mereka tidak beriman, karena kewajibanmu hanyalah menyampaikan. Menurut satu riwayat dibaca 'tas-al', yaitu dengan sukun atau baris mati, menunjukkan larangan.",[["إِنَّآ","Sesungguhnya Kami"],["أَرْسَلْنَـٰكَ","[Kami] telah menghantar kamu"],["بِٱلْحَقِّ","dengan kebenaran"],["بَشِيرًۭا","(sebagai) pembawa berita gembira"],["وَنَذِيرًۭا ۖ","dan (sebagai) pemberi amaran"],["وَلَا","Dan tidak"],["تُسْـَٔلُ","kamu akan ditanya"],["عَنْ","tentang"],["أَصْحَـٰبِ","(para) sahabat"],["ٱلْجَحِيمِ","(dari) api yang menyala-nyala"]]],"127":["(Orang-orang Yahudi dan Kristen tidak akan senang kepadamu hingga kamu mengikuti millah mereka) maksudnya agama mereka. (Katakanlah, \"Sesungguhnya petunjuk Allah) yaitu agama Islam (itulah petunjuk) yang sesungguhnya, sedangkan yang selainnya hanyalah kesesatan belaka. (Sesungguhnya, jika) 'lam' menunjukkan sumpah (kamu ikuti keinginan mereka) yakni apa-apa yang mereka anjurkan (setelah datangnya pengetahuan kepadamu) maksudnya wahyu dari Allah (maka Allah tidak lagi menjadi pelindung) yang akan melindungimu (dan tidak pula menolong.\") yang akan menghindarkanmu dari bahaya.",[["وَلَن","Dan tidak pernah"],["تَرْضَىٰ","akan gembira"],["عَنكَ","bersama kamu"],["ٱلْيَهُودُ","orang Yahudi"],["وَلَا","dan [bukan]"],["ٱلنَّصَـٰرَىٰ","orang Kristian"],["حَتَّىٰ","sehingga"],["تَتَّبِعَ","kamu ikut"],["مِلَّتَهُمْ ۗ","agama mereka"],["قُلْ","Katakanlah"],["إِنَّ","Sesungguhnya"],["هُدَى","(the) Bimbingan"],["ٱللَّهِ","(milik) Allah"],["هُوَ","ia"],["ٱلْهُدَىٰ ۗ","(adalah) Petunjuk"],["وَلَئِنِ","Dan jika"],["ٱتَّبَعْتَ","kamu ikut"],["أَهْوَآءَهُم","keinginan mereka"],["بَعْدَ","selepas"],["ٱلَّذِى","apa"],["جَآءَكَ","telah datang kepada kamu"],["مِنَ","daripada"],["ٱلْعِلْمِ ۙ","pengetahuan itu"],["مَا","tidak"],["لَكَ","bagi kamu"],["مِنَ","daripada"],["ٱللَّهِ","Allah"],["مِن","sebarang"],["وَلِىٍّۢ","pelindung"],["وَلَا","dan bukan"],["نَصِيرٍ","mana-mana pembantu"]]],"128":["(Orang-orang yang telah Kami beri Alkitab) merupakan subjek (sedangkan mereka membacanya dengan bacaan yang sebenarnya) artinya membacanya sebagaimana diturunkan dan digabungkan dengan kalimat ini menjadi 'hal'; 'haqqa' mendapat baris di atas sebagai mashdar atau maf`ul muthlak, sedangkan yang menjadi khabarnya ialah, (mereka itulah yang beriman kepadanya). Ayat ini diturunkan menceritakan segolongan orang yang datang dari Abessinia lalu masuk Islam. (Dan barang siapa yang ingkar terhadapnya) artinya terhadap kitab yang diturunkan itu, misalnya dengan mengubahnya dari yang asli (maka merekalah orang-orang yang rugi) disebabkan mereka disediakan tempat di neraka yang kekal lagi abadi.",[["ٱلَّذِينَ","Mereka itu"],["ءَاتَيْنَـٰهُمُ","Kami telah memberi mereka"],["ٱلْكِتَـٰبَ","Kitab"],["يَتْلُونَهُۥ","membacanya"],["حَقَّ","(kerana ia mempunyai) hak"],["تِلَاوَتِهِۦٓ","(dari) bacaannya"],["أُو۟لَـٰٓئِكَ","Mereka (orang-orang)"],["يُؤْمِنُونَ","beriman"],["بِهِۦ ۗ","di dalamnya"],["وَمَن","Dan sesiapa"],["يَكْفُرْ","tidak beriman"],["بِهِۦ","di dalamnya"],["فَأُو۟لَـٰٓئِكَ","kemudian mereka"],["هُمُ","mereka"],["ٱلْخَـٰسِرُونَ","(adalah) orang-orang yang rugi"]]],"129":["(Hai Bani Israel! Ingatlah akan nikmat-Ku yang telah Aku berikan kepadamu dan sesungguhnya Aku telah mengutamakan kamu dari segala umat). Ayat seperti ini telah kita temui di muka.",[["يَـٰبَنِىٓ","Wahai Kanak-kanak"],["إِسْرَٰٓءِيلَ","(dari) Israel"],["ٱذْكُرُوا۟","Ingat"],["نِعْمَتِىَ","Nikmat Aku"],["ٱلَّتِىٓ","yang"],["أَنْعَمْتُ","aku kurniakan"],["عَلَيْكُمْ","ke atas kamu"],["وَأَنِّى","dan bahawa aku"],["فَضَّلْتُكُمْ","[Aku] lebih suka kamu"],["عَلَى","atas"],["ٱلْعَـٰلَمِينَ","dunia"]]],"130":["(Dan takutlah kamu akan) (suatu hari di waktu tidak dapat menggantikan) (seseorang atas orang yang lainnya) padanya (sedikit pun dan tidak diterima suatu tebusan darinya) (dan tidak akan memberi manfaat kepadanya suatu syafaat dan tidak pula akan ditolong) atau dihindarkan dari azab Allah.",[["وَٱتَّقُوا۟","Dan ketakutan"],["يَوْمًۭا","sehari"],["لَّا","tidak"],["تَجْزِى","akan mendapat manfaat"],["نَفْسٌ","sebuah jiwa"],["عَن","(daripada)"],["نَّفْسٍۢ","jiwa (yang lain)."],["شَيْـًۭٔا","sesuatu"],["وَلَا","dan bukan"],["يُقْبَلُ","akan diterima"],["مِنْهَا","daripadanya"],["عَدْلٌۭ","sebarang pampasan"],["وَلَا","dan bukan"],["تَنفَعُهَا","akan menguntungkannya"],["شَفَـٰعَةٌۭ","sebarang syafaat"],["وَلَا","dan bukan"],["هُمْ","mereka"],["يُنصَرُونَ","akan dibantu"]]],"131":["(Dan) ingatlah (ketika Ibrahim mendapat ujian) menurut satu qiraat Ibraham (dari Tuhannya dengan beberapa kalimat) maksudnya dengan perintah dan larangan yang dibebankan kepadanya. Ada yang mengatakan manasik atau pekerjaan haji, ada pula berkumur-kumur, menghirup air ke hidung, menggosok gigi, memotong kumis, membelah rambut, memotong kuku, mencabut bulu ketiak, mencukur bulu kemaluan, berkhitan dan istinja (lalu disempurnakannya) maksudnya dikerjakannya secara sempurna. (Firman-Nya) yakni Allah Taala, (\"Sesungguhnya Aku akan menjadikanmu sebagai imam bagi manusia.\") Artinya contoh dan ikutan dalam keagamaan. (Kata Ibrahim, \"Aku mohon juga dari keturunanku!\") maksudnya dari anak cucuku dijadikan imam-imam. (Firman-Nya, \"Janji-Ku ini tidak mencapai) untuk dijadikan imam (orang-orang yang aniaya\") yakni orang-orang yang ingkar di antara mereka. Sebaliknya bagi orang yang tidak aniaya, tidak tertutup kemungkinan untuk diangkat sebagai imam.",[["۞ وَإِذِ","Dan apabila"],["ٱبْتَلَىٰٓ","mencuba"],["إِبْرَٰهِـۧمَ","Ibrahim"],["رَبُّهُۥ","Tuhannya"],["بِكَلِمَـٰتٍۢ","dengan kata-kata"],["فَأَتَمَّهُنَّ ۖ","dan dia memenuhinya"],["قَالَ","Dia berkata"],["إِنِّى","Sesungguhnya aku"],["جَاعِلُكَ","(adalah) yang menjadikan kamu"],["لِلنَّاسِ","untuk umat manusia"],["إِمَامًۭا ۖ","seorang pemimpin"],["قَالَ","Dia berkata"],["وَمِن","Dan daripada"],["ذُرِّيَّتِى ۖ","keturunan aku"],["قَالَ","Dia berkata"],["لَا","(Tidak) tidak"],["يَنَالُ","capai"],["عَهْدِى","Perjanjian-Ku"],["ٱلظَّـٰلِمِينَ","(kepada) orang-orang yang zalim"]]],"132":["(Dan ketika Kami menjadikan Baitullah itu) yakni Kakbah (sebagai tempat kembali bagi manusia) maksudnya tempat berkumpul dari segenap pelosok (dan tempat yang aman) maksudnya aman dari penganiayaan dan serangan yang sering terjadi di tempat lain. Sebagai contohnya pernah seseorang menemukan pembunuh bapaknya, tetapi ia tidak mau membalas dendam di tempat ini, (dan jadikanlah) hai manusia (sebagian makam Ibrahim) yakni batu tempat berdirinya Nabi Ibrahim a.s. ketika membangun Baitullah (sebagai tempat salat) yaitu dengan mengerjakan salat sunah tawaf di belakangnya. Menurut satu qiraat dibaca 'wattakhadzuu' yang artinya, dan mereka menjadikan; hingga menjadi kalimat berita. (Dan telah Kami perintahkan kepada Ibrahim dan Ismail) (yang bunyinya) (\"Bersihkanlah rumah-Ku) dari berhala (untuk orang-orang yang tawaf, yang iktikaf) artinya yang bermukim di sana (orang-orang yang rukuk dan orang-orang yang sujud!\") artinya orang-orang yang salat.",[["وَإِذْ","Dan apabila"],["جَعَلْنَا","Kami buat"],["ٱلْبَيْتَ","Dewan"],["مَثَابَةًۭ","tempat kembali"],["لِّلنَّاسِ","untuk manusia"],["وَأَمْنًۭا","dan (tempat) keselamatan"],["وَٱتَّخِذُوا۟","dan (berkata), \"Ambillah"],["مِن","[dari]"],["مَّقَامِ","(tempat) berdiri"],["إِبْرَٰهِـۧمَ","(dari) Ibrahim"],["مُصَلًّۭى ۖ","(sebagai) tempat solat"],["وَعَهِدْنَآ","Dan Kami telah mengadakan perjanjian"],["إِلَىٰٓ","dengan"],["إِبْرَٰهِـۧمَ","Ibrahim"],["وَإِسْمَـٰعِيلَ","dan Ismail"],["أَن","[bahawa]"],["طَهِّرَا","[Kamu berdua] sucikan"],["بَيْتِىَ","Rumah Aku"],["لِلطَّآئِفِينَ","bagi mereka yang tawaf"],["وَٱلْعَـٰكِفِينَ","dan orang-orang yang mengasingkan diri untuk beribadah dan sembahyang"],["وَٱلرُّكَّعِ","dan orang-orang yang sujud"],["ٱلسُّجُودِ","dan orang-orang yang sujud"]]],"133":["(Dan ketika Ibrahim berdoa, \"Ya Tuhanku! Jadikanlah ini) maksudnya tempat ini (sebagai suatu negeri yang aman). Doanya dikabulkan Allah sehingga negeri Mekah dijadikan sebagai suatu negeri yang suci, darah manusia tidak boleh ditumpahkan, seorang pun tidak boleh dianiaya, tidak boleh pula diburu binatang buruannya dan dicabut rumputnya. (Dan berilah penduduknya rezeki berupa buah-buahan) dan ini juga sudah menjadi kenyataan dengan diangkutnya berbagai macam buah-buahan dari negeri Syam melalui orang-orang yang hendak tawaf sekalipun tanahnya merupakan suatu tempat yang tandus tanpa air dan tumbuh-tumbuhan (yakni yang beriman di antara mereka kepada Allah dan hari akhir\") merupakan 'badal' atau kalimat pengganti bagi 'penduduknya' yang dikhususkan dengan doa, sesuai dengan firman-Nya, \"Dan janji-Ku ini tidaklah mencapai orang-orang yang aniaya.\" (Firman Allah, \"Dan) Aku beri mereka pula (orang-orang kafir lalu Aku beri kesenangan sedikit) atau sementara, yakni selama hidup di dunia dengan rezeki, dibaca 'fa-umatti`uhu', yakni dengan tasydid. (Kemudian Aku paksa ia) di akhirat kelak (menjalani siksa neraka) sehingga tidak mendapatkan jalan keluar (dan itulah seburuk-buruk tempat kembali\").",[["وَإِذْ","Dan apabila"],["قَالَ","berkata"],["إِبْرَٰهِـۧمُ","Ibrahim"],["رَبِّ","Tuhanku"],["ٱجْعَلْ","buat"],["هَـٰذَا","ini"],["بَلَدًا","sebuah bandar"],["ءَامِنًۭا","selamat"],["وَٱرْزُقْ","dan menyediakan"],["أَهْلَهُۥ","rakyatnya"],["مِنَ","dengan"],["ٱلثَّمَرَٰتِ","buah-buahan"],["مَنْ","(kepada) sesiapa sahaja"],["ءَامَنَ","beriman"],["مِنْهُم","daripada mereka"],["بِٱللَّهِ","kepada Allah"],["وَٱلْيَوْمِ","dan Hari"],["ٱلْـَٔاخِرِ ۖ","yang Terakhir"],["قَالَ","Dia berkata"],["وَمَن","Dan sesiapa"],["كَفَرَ","kufur"],["فَأُمَتِّعُهُۥ","[maka] Aku akan berikan kepadanya kesenangan"],["قَلِيلًۭا","sedikit"],["ثُمَّ","kemudian"],["أَضْطَرُّهُۥٓ","Aku akan paksa dia"],["إِلَىٰ","kepada"],["عَذَابِ","azab"],["ٱلنَّارِ ۖ","(dari) api"],["وَبِئْسَ","dan jahat"],["ٱلْمَصِيرُ","(adalah) destinasi"]]],"134":["(Dan) ingatlah (ketika Ibrahim meninggikan sendi-sendi) dasar-dasar atau dinding-dinding (Baitullah) maksudnya membinanya yang dapat dipahami dari kata 'meninggikan' tadi (beserta Ismail) `athaf atau dihubungkan kepada Ibrahim sambil keduanya berdoa, (\"Ya Tuhan kami! Terimalah dari kami) amal kami membina ini, (sesungguhnya Engkau Maha Mendengar) akan permohonan kami (lagi Maha Mengetahui) akan perbuatan kami.",[["وَإِذْ","Dan apabila"],["يَرْفَعُ","(sedang) membesarkan"],["إِبْرَٰهِـۧمُ","Ibrahim"],["ٱلْقَوَاعِدَ","asas-asas"],["مِنَ","daripada"],["ٱلْبَيْتِ","Dewan"],["وَإِسْمَـٰعِيلُ","dan Ismail"],["رَبَّنَا","(sambil berkata), “Ya Tuhan kami"],["تَقَبَّلْ","Terima"],["مِنَّآ ۖ","daripada kami"],["إِنَّكَ","Sesungguhnya Engkau"],["أَنتَ","[Kamu] (adalah)"],["ٱلسَّمِيعُ","yang Maha Mendengar"],["ٱلْعَلِيمُ","yang Maha Mengetahui"]]],"135":["(Ya Tuhan kami! Jadikanlah kami berdua ini orang yang patuh) dan tunduk (kepada-Mu dan) jadikanlah pula (di antara keturunan kami) maksudnya anak cucu kami (umat) atau golongan (yang patuh kepada-Mu). 'Min' menyatakan 'sebagian' dan diajukan mereka demikian karena firman Allah yang lalu, 'Dan janji-Ku ini tidak mencapai orang-orang yang aniaya.' (Dan tunjukkanlah kepada kami) ajarkanlah kepada kami (syariat ibadah haji kami) maksudnya cara-cara dan tempat-tempatnya (dan terimalah tobat kami, sesungguhnya Engkau Maha Penerima tobat lagi Maha Penyayang). Mereka bertobat kepada Allah padahal mereka maksum atau terpelihara dari dosa, disebabkan kerendahan hati mereka dan sebagai pelajaran bagi anak cucu mereka.",[["رَبَّنَا","Wahai Tuhan kami"],["وَٱجْعَلْنَا","[dan] Jadikan kami"],["مُسْلِمَيْنِ","sama-sama tunduk"],["لَكَ","kepada-Mu"],["وَمِن","Dan daripada"],["ذُرِّيَّتِنَآ","zuriat kita"],["أُمَّةًۭ","sesebuah komuniti"],["مُّسْلِمَةًۭ","tunduk"],["لَّكَ","kepada-Mu"],["وَأَرِنَا","Dan tunjukkan kepada kami"],["مَنَاسِكَنَا","cara ibadah kita"],["وَتُبْ","dan pusing"],["عَلَيْنَآ ۖ","kepada kami"],["إِنَّكَ","Sesungguhnya Engkau"],["أَنتَ","[Kamu] (adalah)"],["ٱلتَّوَّابُ","yang Sering kembali"],["ٱلرَّحِيمُ","Yang Maha Mengasihani"]]],"136":["(Ya Tuhan kami! Utuslah untuk mereka) yakni Ahlulbait (seorang rasul dari kalangan mereka) ini telah dikabulkan Allah dengan dibangkitkannya kepada mereka Nabi Muhammad saw. (yang akan membacakan kepada mereka ayat-ayat-Mu) Alquran (dan mengajari mereka Alkitab) yakni Alquran (dan hikmah) maksudnya hukum-hukum yang terdapat di dalamnya (serta menyucikan mereka) dari kemusyrikan (sesungguhnya Engkau Maha Kuasa) sehingga mengungguli siapa pun (lagi Maha Bijaksana\") dalam segala tindakan dan perbuatan.",[["رَبَّنَا","Wahai Tuhan kami"],["وَٱبْعَثْ","[Dan] bangkitlah"],["فِيهِمْ","dalam diri mereka"],["رَسُولًۭا","seorang Rasul"],["مِّنْهُمْ","daripada mereka"],["يَتْلُوا۟","(yang) akan mengaji"],["عَلَيْهِمْ","kepada mereka"],["ءَايَـٰتِكَ","Ayat-ayat Mu"],["وَيُعَلِّمُهُمُ","dan akan mengajar mereka"],["ٱلْكِتَـٰبَ","Kitab"],["وَٱلْحِكْمَةَ","dan hikmahnya"],["وَيُزَكِّيهِمْ ۚ","dan menyucikan mereka"],["إِنَّكَ","Sesungguhnya Engkau"],["أَنتَ","kamu (adalah)"],["ٱلْعَزِيزُ","Yang Maha Perkasa"],["ٱلْحَكِيمُ","Yang Maha Bijaksana"]]],"137":["(Dan siapakah) maksudnya tidak ada orang (yang benci pada agama Ibrahim) lalu meninggalkannya (kecuali orang yang memperbodoh dirinya sendiri) artinya tidak mengerti bahwa ia makhluk Allah dan harus mengabdikan diri kepada-Nya atau yang dimaksud, mencelakakan dan menghinakan dirinya sendiri (dan sungguh Kami telah memilihnya di dunia) sebagai seorang rasul dan seorang khalil, artinya 'sebagai seorang sahabat', (dan sesungguhnya di akhirat dia benar-benar termasuk orang-orang yang saleh) yang mempunyai kedudukan tinggi.",[["وَمَن","Dan siapa"],["يَرْغَبُ","akan berpaling"],["عَن","daripada"],["مِّلَّةِ","(agama)."],["إِبْرَٰهِـۧمَ","(dari) Ibrahim"],["إِلَّا","kecuali"],["مَن","yang"],["سَفِهَ","tertipu"],["نَفْسَهُۥ ۚ","dirinya sendiri"],["وَلَقَدِ","Dan sesungguhnya"],["ٱصْطَفَيْنَـٰهُ","Kami memilih dia"],["فِى","dalam"],["ٱلدُّنْيَا ۖ","dunia"],["وَإِنَّهُۥ","dan sesungguhnya dia"],["فِى","dalam"],["ٱلْـَٔاخِرَةِ","akhirat"],["لَمِنَ","nescaya (akan) antara"],["ٱلصَّـٰلِحِينَ","orang yang soleh"]]],"138":["Ingatlah! (Ketika Tuhannya berfirman kepadanya, \"Tunduk dan berserah dirilah kamu!\") maksudnya \"Tunduklah kepada Allah dan bulatkan pengabdianmu kepada-Nya!\" (Jawab Ibrahim, \"Aku tunduk dan berserah diri kepada Tuhan semesta alam.\")",[["إِذْ","Apabila"],["قَالَ","berkata"],["لَهُۥ","kepadanya"],["رَبُّهُۥٓ","Tuhannya"],["أَسْلِمْ ۖ","Serahkan (diri sendiri)"],["قَالَ","dia berkata"],["أَسْلَمْتُ","Aku (telah) menyerahkan (diri aku)"],["لِرَبِّ","kepada (Tuhan)."],["ٱلْعَـٰلَمِينَ","sekalian alam"]]],"139":["(Dan Ibrahim telah mewasiatkan) maksudnya agama itu. Menurut suatu qiraat 'aushaa', (kepada anak-anaknya, demikian pula Yakub) kepada anak-anaknya, katanya, (\"Hai anak-anakku! Sesungguhnya Allah telah memilih agama ini untukmu) yakni agama Islam, (maka janganlah kamu mati kecuali dalam menganut agama Islam!\") Artinya ia melarang mereka meninggalkan agama Islam dan menyuruh mereka agar memegang teguh agama itu sampai nyawa berpisah dari badan.",[["وَوَصَّىٰ","Dan diperintahkan"],["بِهَآ","[ia]"],["إِبْرَٰهِـۧمُ","Ibrahim"],["بَنِيهِ","(ke atas) anak-anaknya"],["وَيَعْقُوبُ","dan Yaqub"],["يَـٰبَنِىَّ","Wahai anak-anakku"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["ٱصْطَفَىٰ","telah memilih"],["لَكُمُ","bagi kamu"],["ٱلدِّينَ","agama itu"],["فَلَا","jadi tidak"],["تَمُوتُنَّ","(sepatutnya) kamu mati"],["إِلَّا","kecuali"],["وَأَنتُم","sedangkan kamu"],["مُّسْلِمُونَ","(adalah) tunduk"]]],"140":["Tatkala orang-orang Yahudi mengatakan kepada Nabi saw., \"Apakah kamu tidak tahu bahwa ketika akan mati itu Yakub memesankan kepada putra-putranya supaya memegang teguh agama Yahudi,\" maka turunlah ayat, (\"Apakah kalian menyaksikan) atau turut hadir (ketika tanda-tanda kematian telah datang kepada Yakub, yakni ketika) menjadi 'bada' atau huruf pengganti bagi 'idz' yang sebelumnya, (ia menanyakan kepada anak-anaknya, 'Apa yang kamu sembah sepeninggalku?\") yakni setelah aku meninggal? (Jawab mereka, \"Kami akan menyembah Tuhanmu dan Tuhan bapak-bapakmu Ibrahim, Ismail dan Ishak). Ismail dianggap sebagai 'bapak' berdasarkan taghlib atau pukul rata, karena kedudukan paman sama dengan bapak (yakni Tuhan Yang Maha Esa) merupakan 'badal' atau kata pengganti dari 'Tuhanmu', (dan kami tunduk serta berserah diri kepada-Nya.\") Kata 'am' atau 'apakah' di atas berarti penolakan, artinya kalian tidak hadir ketika ia wafat, maka betapa kalian berani menyatakan dan mengucapkan kepadanya perkataan yang tidak-tidak!",[["أَمْ","Atau"],["كُنتُمْ","adakah kamu"],["شُهَدَآءَ","saksi"],["إِذْ","apabila"],["حَضَرَ","datang ke"],["يَعْقُوبَ","Yaqub"],["ٱلْمَوْتُ","[the] kematian"],["إِذْ","apabila"],["قَالَ","dia berkata"],["لِبَنِيهِ","kepada anak-anak lelakinya"],["مَا","Apa"],["تَعْبُدُونَ","adakah kamu akan menyembah"],["مِنۢ","daripada"],["بَعْدِى","selepas aku"],["قَالُوا۟","Mereka berkata"],["نَعْبُدُ","Kami akan beribadat"],["إِلَـٰهَكَ","Tuhanmu"],["وَإِلَـٰهَ","dan (Allah)."],["ءَابَآئِكَ","(dari) nenek moyang kamu"],["إِبْرَٰهِـۧمَ","Ibrahim"],["وَإِسْمَـٰعِيلَ","dan Ismail"],["وَإِسْحَـٰقَ","dan Ishak"],["إِلَـٰهًۭا","Tuhan"],["وَٰحِدًۭا","satu"],["وَنَحْنُ","Dan kami"],["لَهُۥ","kepada-Nya"],["مُسْلِمُونَ","(adalah) tunduk"]]],"141":["(Itu) isyarat kepada Ibrahim dan Yakub serta anak cucu mereka, menjadi 'mubtada' atau subyek dan dipakai kata muannats/jenis wanita disebabkan predikatnya yang muannats pula, (adalah umat yang telah lalu) (bagi mereka apa yang telah mereka usahakan) maksudnya balasan atau ganjaran amal perbuatan mereka (dan bagi kamu) ditujukan kepada orang-orang Yahudi (apa yang kamu usahakan dan kamu tidak akan diminta pertanggungjawaban tentang apa-apa yang mereka kerjakan) sebagaimana mereka tidak pula akan diminta pertanggungjawaban tentang amal perbuatanmu. Kalimat yang di belakang ini memperkuat maksud kalimat di muka.",[["تِلْكَ","Ini"],["أُمَّةٌۭ","(adalah) sebuah komuniti"],["قَدْ","(yang)"],["خَلَتْ ۖ","telah meninggal dunia"],["لَهَا","baginya"],["مَا","apa"],["كَسَبَتْ","ia diperolehi"],["وَلَكُم","dan untuk kamu"],["مَّا","apa"],["كَسَبْتُمْ ۖ","kamu telah memperolehi"],["وَلَا","Dan tidak"],["تُسْـَٔلُونَ","kamu akan ditanya"],["عَمَّا","tentang apa"],["كَانُوا۟","mereka dahulu"],["يَعْمَلُونَ","lakukan"]]],"142":["(Dan kata mereka, \"Jadilah kamu sebagai penganut agama Yahudi atau Kristen, niscaya kamu mendapat petunjuk.\") 'Au' yang berarti 'atau' berfungsi sebagai pemisah. Yang pertama diucapkan oleh orang-orang Yahudi Madinah, sedangkan yang kedua oleh kaum Kristen Najran. (Katakanlah) kepada mereka (tidak, bahkan) kami akan mengikuti (agama Ibrahim yang lurus) yang bertentangan dengan agama lain dan berpaling menjadi agama yang lurus dan benar. 'Hanifa' ini menjadi 'hal' dari Ibrahim. (Dan bukanlah dia dari golongan orang-orang musyrik).",[["وَقَالُوا۟","Dan mereka berkata"],["كُونُوا۟","Jadilah"],["هُودًا","Yahudi"],["أَوْ","atau"],["نَصَـٰرَىٰ","Kristian"],["تَهْتَدُوا۟ ۗ","(maka) kamu akan mendapat petunjuk"],["قُلْ","Katakanlah"],["بَلْ","Bahkan"],["مِلَّةَ","(agama)."],["إِبْرَٰهِـۧمَ","(dari) Ibrahim"],["حَنِيفًۭا ۖ","(yang) tegak"],["وَمَا","dan bukan"],["كَانَ","dia adalah"],["مِنَ","daripada"],["ٱلْمُشْرِكِينَ","mereka yang mempersekutukan (dengan Allah)"]]],"143":["(Katakanlah,) ucapan ini ditujukan kepada orang-orang beriman (\"Kami beriman kepada Allah dan pada apa yang diturunkan kepada kami) yakni Alquran (dan pada apa yang diturunkan kepada Ibrahim) yakni shuhuf, yaitu lembaran-lembaran yang sepuluh (kepada Ismail, Ishak, Yakub dan anak cucunya) (dan apa yang diberikan kepada Musa) berupa Taurat (dan Isa) yakni Injil (begitu juga yang diberikan kepada nabi-nabi dari Tuhan mereka) baik berupa kitab maupun ayat. (Tidaklah kami beda-bedakan seorang pun di antara mereka) sehingga mengakibatkan kami beriman kepada sebagian dan kafir kepada sebagian yang lain sebagaimana halnya orang-orang Yahudi dan Kristen, (dan kami hanya tunduk kepada-Nya semata.\")",[["قُولُوٓا۟","Katakanlah"],["ءَامَنَّا","Kami telah beriman"],["بِٱللَّهِ","kepada Allah"],["وَمَآ","dan apa"],["أُنزِلَ","(adalah) didedahkan"],["إِلَيْنَا","kepada kami"],["وَمَآ","dan apa"],["أُنزِلَ","telah didedahkan"],["إِلَىٰٓ","kepada"],["إِبْرَٰهِـۧمَ","Ibrahim"],["وَإِسْمَـٰعِيلَ","dan Ismail"],["وَإِسْحَـٰقَ","dan Ishak"],["وَيَعْقُوبَ","dan Yaqub"],["وَٱلْأَسْبَاطِ","dan keturunan"],["وَمَآ","dan apa"],["أُوتِىَ","telah diberikan"],["مُوسَىٰ","(kepada) Musa"],["وَعِيسَىٰ","dan Isa"],["وَمَآ","dan apa"],["أُوتِىَ","telah diberikan"],["ٱلنَّبِيُّونَ","(kepada) para Nabi"],["مِن","daripada"],["رَّبِّهِمْ","Tuhan mereka"],["لَا","Tidak"],["نُفَرِّقُ","kita membuat perbezaan"],["بَيْنَ","antara"],["أَحَدٍۢ","sebarang"],["مِّنْهُمْ","daripada mereka"],["وَنَحْنُ","Dan kami"],["لَهُۥ","kepada-Nya"],["مُسْلِمُونَ","(adalah) tunduk"]]],"144":["(Maka jika mereka beriman) yakni orang-orang Yahudi dan Kristen tadi (dengan) 'mitsli' atau 'seperti' hanya sebagai tambahan (apa yang kamu imani, maka mereka telah memperoleh petunjuk dan jika mereka berpaling) dari keimanan itu, (berarti mereka dalam permusuhan) denganmu. (Maka Allah akan memeliharamu dari permusuhan mereka itu) hai Muhammad! (Dan Allah Maha Mendengar) ucapan-ucapan mereka (lagi Maha Mengetahui) semua keadaan mereka. Misalnya kamu telah ditolong-Nya dengan pembunuhan Bani Quraizhah, pengusiran Bani Nadhir dan pembebanan upeti atas mereka.",[["فَإِنْ","Jadi jika"],["ءَامَنُوا۟","mereka beriman[d]"],["بِمِثْلِ","dalam (sebagai) seperti"],["مَآ","apa"],["ءَامَنتُم","kamu telah beriman"],["بِهِۦ","di dalamnya"],["فَقَدِ","maka sesungguhnya"],["ٱهْتَدَوا۟ ۖ","mereka telah mendapat petunjuk"],["وَّإِن","Tetapi jika"],["تَوَلَّوْا۟","mereka berpaling"],["فَإِنَّمَا","kemudian sahaja"],["هُمْ","mereka"],["فِى","(ada) dalam"],["شِقَاقٍۢ ۖ","perselisihan faham"],["فَسَيَكْفِيكَهُمُ","Maka cukuplah kamu terhadap mereka"],["ٱللَّهُ ۚ","Allah"],["وَهُوَ","dan Dia"],["ٱلسَّمِيعُ","(ialah) Yang Maha Mendengar"],["ٱلْعَلِيمُ","yang Maha Mengetahui"]]],"145":["(Celupan Allah) 'mashdar' yang memperkuat 'kami beriman' tadi. Mendapat baris di atas sebagai maf`ul muthlak dari fi`il yang tersembunyi yang diperkirakan berbunyi 'Shabaghanallaahu shibghah', artinya \"Allah mencelup kami suatu celupan\". Sedang maksudnya ialah agama-Nya yang telah difitrahkan-Nya atas manusia dengan pengaruh dan bekasnya yang menonjol, tak ubah bagai celupan terhadap kain. (Dan siapakah) maksudnya tidak seorang pun (yang lebih baik celupannya dari Allah) shibghah di sini menjadi 'tamyiz' (dan hanya kepada-Nya kami menyembah).",[["صِبْغَةَ","(The) warna (agama)"],["ٱللَّهِ ۖ","(milik) Allah"],["وَمَنْ","Dan siapa"],["أَحْسَنُ","(lebih) baik"],["مِنَ","daripada"],["ٱللَّهِ","Allah"],["صِبْغَةًۭ ۖ","pada mewarna"],["وَنَحْنُ","Dan kami"],["لَهُۥ","kepada-Nya"],["عَـٰبِدُونَ","(adalah) ahli ibadah"]]],"146":["(Katakanlah) kepada mereka! (\"Apakah kamu hendak memperbantahkan) dengan kami (tentang Allah) karena Dia memilih seorang nabi dari kalangan Arab? (Padahal Dia adalah Tuhan kamu) dan berhak memilih siapa saja yang dikehendaki-Nya di antara hamba-hamba-Nya (dan bagi kamu amalan kamu) dan kamu akan memperoleh balasannya pula dan tidak mustahil jika di antara amal-amalan kami itu ada yang patut menerima ganjaran istimewa (dan hanya kepada-Nya kami mengikhlaskan) agama dan amalan kami; berbeda halnya dengan kamu, sehingga sepatutnyalah kami yang dipilih-Nya. 'Hamzah' atau 'apakah' di atas, maksudnya menolak, sedangkan ketiga kalimat di belakang berarti 'hal'.",[["قُلْ","Katakanlah"],["أَتُحَآجُّونَنَا","Adakah kamu berdebat dengan kami"],["فِى","tentang"],["ٱللَّهِ","Allah"],["وَهُوَ","manakala Dia"],["رَبُّنَا","(ialah) Tuhan kami"],["وَرَبُّكُمْ","dan Tuhanmu"],["وَلَنَآ","Dan untuk kita"],["أَعْمَـٰلُنَا","(adalah) perbuatan kita"],["وَلَكُمْ","dan untuk kamu"],["أَعْمَـٰلُكُمْ","(adalah) perbuatan kamu"],["وَنَحْنُ","dan kita"],["لَهُۥ","kepada-Nya"],["مُخْلِصُونَ","(adalah) ikhlas"]]],"147":["(Atau) apakah (kamu hendak mengatakan) ada pula yang membaca 'yaquuluuna', artinya mereka hendak mengatakan (bahwa Ibrahim, Ismail, Ishak, Yakub dan anak cucunya adalah penganut agama Yahudi dan Kristen?\" Katakanlah) kepada mereka, (\"Apakah kamu yang lebih tahu ataukah Allah\") artinya Allahlah yang lebih mengetahui dan Allah sendiri telah membebaskan Ibrahim dari kedua agama itu, firman-Nya, \"Ibrahim itu bukanlah seorang Yahudi atau Kristen.\" Demikian pula nabi-nabi yang disebutkan bersamanya mereka itu adalah juga mengikuti agamanya. (Dan siapakah lagi yang aniaya daripada orang yang menyembunyikan) atau merahasiakan kepada umat manusia (kesaksian yang terdapat padanya) (dari Allah) maksudnya tidak ada lain yang lebih aniaya daripadanya. Yang dituju adalah orang-orang Yahudi yang menyembunyikan kesaksian Allah dalam Taurat bahwa Ibrahim itu menganut agama hanafiah, yaitu agama Islam yang lurus. (Dan Allah sekali-kali tidak lalai dari apa yang kamu kerjakan) merupakan ancaman dan peringatan terhadap mereka.",[["أَمْ","Atau"],["تَقُولُونَ","(adakah) kamu katakan"],["إِنَّ","bahawa"],["إِبْرَٰهِـۧمَ","Ibrahim"],["وَإِسْمَـٰعِيلَ","dan Ismail"],["وَإِسْحَـٰقَ","dan Ishak"],["وَيَعْقُوبَ","dan Yaqub"],["وَٱلْأَسْبَاطَ","dan keturunan"],["كَانُوا۟","adalah"],["هُودًا","Yahudi"],["أَوْ","atau"],["نَصَـٰرَىٰ ۗ","Kristian"],["قُلْ","Katakanlah"],["ءَأَنتُمْ","adakah kamu"],["أَعْلَمُ","lebih mengetahui"],["أَمِ","atau"],["ٱللَّهُ ۗ","(ialah) Allah"],["وَمَنْ","Dan siapa"],["أَظْلَمُ","(adalah) lebih zalim"],["مِمَّن","daripada (yang) yang"],["كَتَمَ","disembunyikan"],["شَهَـٰدَةً","sebuah kesaksian"],["عِندَهُۥ","(yang) dia ada"],["مِنَ","daripada"],["ٱللَّهِ ۗ","Allah"],["وَمَا","Dan tidak"],["ٱللَّهُ","(ialah) Allah"],["بِغَـٰفِلٍ","tak sedar"],["عَمَّا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"]]],"148":["(Mereka itu adalah umat yang telah lalu, bagi mereka apa yang telah mereka usahakan dan bagi kamu apa yang kamu usahakan; dan kamu tidak akan diminta pertanggungjawaban tentang apa yang telah mereka kerjakan). Ayat seperti ini telah kita temui di muka.",[["تِلْكَ","Ini"],["أُمَّةٌۭ","(adalah) sebuah komuniti"],["قَدْ","(yang)"],["خَلَتْ ۖ","telah meninggal dunia"],["لَهَا","baginya"],["مَا","apa"],["كَسَبَتْ","ia diperolehi"],["وَلَكُم","dan untuk kamu"],["مَّا","apa"],["كَسَبْتُمْ ۖ","kamu telah memperolehi"],["وَلَا","Dan tidak"],["تُسْـَٔلُونَ","kamu akan ditanya"],["عَمَّا","tentang apa"],["كَانُوا۟","mereka dahulu"],["يَعْمَلُونَ","lakukan"]]]});